import ast
import asyncio
import base64
import collections
import contextlib
import datetime
import decimal
import io
import json
import math
import os
from pathlib import Path
import re
import sys
import time
import traceback

import httpx
from openai import AsyncOpenAI


class BudgetStop(Exception):
    pass


def text_json(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"), default=str)


def decode_result(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except (ValueError, TypeError):
            return value
    return value


def load_tools():
    source = json.loads(Path('/run-input/tools.json').read_text())
    if isinstance(source, dict):
        source = source.get('tools', source.get('functions', source))
    if isinstance(source, dict):
        source = [dict(value, name=value.get('name', key)) for key, value in source.items()]
    tools = []
    for entry in source:
        definition = entry.get('function', entry)
        name = definition.get('name', '')
        if not any(part in name for part in ('api_search', 'api_fetch', 'base64_encode')):
            continue
        tools.append({
            'type': 'function',
            'name': name,
            'description': definition.get('description', ''),
            'parameters': definition.get('parameters', definition.get('input_schema', definition.get('inputSchema', {'type': 'object', 'properties': {}}))),
            'strict': False,
        })
    if not tools:
        raise RuntimeError('No simulated API tools found in supplied definitions')
    return tools


class Workflow:
    def __init__(self, instruction):
        self.instruction = instruction
        self.started = time.monotonic()
        self.api_calls = 0
        self.model_calls = 0
        self.results = {}
        self.tools = load_tools()
        self.names = {definition['name'] for definition in self.tools}
        self.semaphore = asyncio.Semaphore(8)
        self.client = httpx.AsyncClient(timeout=65)
        self.model = AsyncOpenAI(
            base_url=os.environ['TASK_MODEL_API_BASE'],
            api_key=os.environ['TASK_MODEL_API_KEY'],
            max_retries=0,
            timeout=180,
        )
        self.log_dir = Path(os.environ.get('METHOD_OUTPUT_DIR', '/workspace/run-output'))
        self.log_dir.mkdir(parents=True, exist_ok=True)
        self.conversation = []
        self.scope = {
            'json': json, 'asyncio': asyncio, 'datetime': datetime,
            'decimal': decimal, 'math': math, 're': re, 'base64': base64,
            'collections': collections, 'results': self.results,
            'tool_schemas': self.tools, 'tool': self.tool,
        }
        for short_name in ('api_search', 'api_fetch', 'base64_encode'):
            name = next((name for name in self.names if name.endswith(short_name)), None)
            if name:
                self.scope[short_name] = self.make_helper(name)

    def make_helper(self, name):
        async def helper(**arguments):
            return await self.tool(name, arguments)
        return helper

    def trace(self, event):
        with (self.log_dir / 'trace.jsonl').open('a') as output:
            output.write(text_json(event) + '\n')

    def remaining(self):
        return 570 - (time.monotonic() - self.started)

    async def invoke(self, name, arguments):
        if name not in self.names:
            return {'error': 'Unknown tool', 'available': sorted(self.names)}, None
        if self.api_calls >= 98 or self.remaining() < 8:
            raise BudgetStop('Simulated API/time budget exhausted')
        self.api_calls += 1
        reference = f'r{self.api_calls}'
        async with self.semaphore:
            try:
                response = await self.client.post(
                    os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call',
                    headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN']},
                    json={'name': name, 'arguments': arguments},
                    timeout=min(65, max(1, self.remaining())),
                )
                if response.status_code == 402:
                    raise BudgetStop('Host budget exhausted (HTTP 402)')
                response.raise_for_status()
                envelope = response.json()
                value = decode_result(envelope.get('result', envelope))
            except BudgetStop:
                raise
            except Exception as error:
                value = {'transport_error': str(error), 'note': 'If this was a write, check whether it committed before retrying.'}
        self.results[reference] = value
        self.trace({'type': 'tool', 'ref': reference, 'name': name, 'arguments': arguments, 'result': value})
        return value, reference

    async def tool(self, name, arguments=None, **kwargs):
        value, reference = await self.invoke(name, arguments if arguments is not None else kwargs)
        return value

    async def python(self, code):
        output = io.StringIO()
        try:
            with contextlib.redirect_stdout(output):
                compiled = compile(code, '<workflow-python>', 'exec', flags=ast.PyCF_ALLOW_TOP_LEVEL_AWAIT)
                pending = eval(compiled, self.scope)
                if pending is not None:
                    await asyncio.wait_for(pending, timeout=max(1, min(110, self.remaining())))
        except BudgetStop:
            raise
        except Exception:
            output.write(traceback.format_exc(limit=4))
        text = output.getvalue() or 'Executed successfully (no printed output).'
        if len(text) > 42000:
            self.results['python_output'] = text
            text = text[:42000] + '\n[Display truncated; complete output in results["python_output"]. Print a focused extraction.]'
        return text

    async def execute_call(self, item):
        try:
            arguments = json.loads(item.arguments)
            if item.name == 'python':
                text = await self.python(arguments['code'])
            else:
                value, reference = await self.invoke(item.name, arguments)
                text = text_json({'ref': reference, 'result': value})
                if len(text) > 55000:
                    text = text[:55000] + f'\n[Display truncated. Complete decoded result is in results[{reference!r}]; use python to extract necessary data.]'
            return {'type': 'function_call_output', 'call_id': item.call_id, 'output': text}
        except BudgetStop:
            raise
        except Exception as error:
            return {'type': 'function_call_output', 'call_id': item.call_id, 'output': text_json({'error': str(error)})}

    async def run(self):
        prompt = Path(__file__).with_name('workflow_prompt.txt').read_text()
        self.conversation = [
            {'role': 'system', 'content': prompt},
            {'role': 'user', 'content': self.instruction},
        ]
        tools = self.tools + [{
            'type': 'function', 'name': 'python',
            'description': 'Execute persistent Python code for exact computation, inspection of saved full tool results, or batches of simulated API calls. Supports top-level await. Print concise useful results.',
            'parameters': {'type': 'object', 'properties': {'code': {'type': 'string'}}, 'required': ['code'], 'additionalProperties': False},
            'strict': True,
        }]
        report = ''
        for turn in range(46):
            if self.remaining() < 12:
                break
            if turn in (18, 32, 41) or (self.remaining() < 95 and turn % 3 == 0):
                self.conversation.append({'role': 'system', 'content': f'Runtime checkpoint: {int(self.remaining())} seconds and {98-self.api_calls} simulated calls remain. Reconcile the original request against completed actions. Prioritize outstanding required changes, then essential verification. Avoid unnecessary exploration.'})
            self.model_calls += 1
            response = await self.model.responses.create(
                model=os.environ['TASK_MODEL_NAME'],
                input=self.conversation,
                tools=tools,
                store=False,
                include=['reasoning.encrypted_content'],
            )
            outputs = [item.model_dump(exclude_none=True) for item in response.output]
            self.conversation.extend(outputs)
            self.trace({'type': 'model', 'turn': turn, 'usage': response.usage.model_dump() if response.usage else None, 'output': outputs})
            calls = [item for item in response.output if item.type == 'function_call']
            if not calls:
                report = response.output_text
                break
            if any(item.name == 'python' for item in calls):
                tool_outputs = []
                for item in calls:
                    tool_outputs.append(await self.execute_call(item))
            else:
                tool_outputs = await asyncio.gather(*(self.execute_call(item) for item in calls))
            self.conversation.extend(tool_outputs)
        if not report:
            report = 'Execution reached its limit. Some requested changes may be incomplete; consult the confirmed tool receipts.'
        return report

    async def close(self):
        (self.log_dir / 'conversation.json').write_text(text_json(self.conversation))
        await self.client.aclose()
        await self.model.close()


async def main():
    inputs = json.load(sys.stdin)
    runner = Workflow(inputs['instruction'])
    try:
        report = await runner.run()
    except BudgetStop as error:
        report = f'Execution stopped: {error}. Completed changes remain applied; unconfirmed items may be incomplete.'
    except Exception as error:
        runner.trace({'type': 'error', 'error': repr(error)})
        report = f'Execution stopped due to a service error: {error}. Completed changes remain applied.'
    finally:
        await runner.close()
    print(text_json({'report': report}))


if __name__ == '__main__':
    asyncio.run(main())

import ast
import asyncio
import contextlib
import io
import json
import os
import sys
import time
import traceback
from pathlib import Path

import httpx
from openai import AsyncOpenAI


class BudgetStopped(Exception):
    pass


def encode(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"), default=str)


def decode(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except (ValueError, TypeError):
            return value
    return value


def definitions(raw):
    if isinstance(raw, dict):
        for key in ("tools", "functions", "definitions"):
            if key in raw:
                return definitions(raw[key])
        if "name" in raw or "function" in raw:
            raw = [raw]
        else:
            raw = [dict(value, name=key) for key, value in raw.items() if isinstance(value, dict)]
    normalized = []
    for original in raw:
        definition = original.get("function", original)
        if "name" not in definition:
            continue
        normalized.append({
            "type": "function",
            "name": definition["name"],
            "description": definition.get("description", ""),
            "parameters": definition.get("parameters", definition.get("inputSchema", definition.get("input_schema", {"type": "object", "properties": {}}))),
            "strict": False,
        })
    return normalized


class Workflow:
    def __init__(self, instruction, tool_definitions):
        self.instruction = instruction
        self.started = time.monotonic()
        self.tool_calls = 0
        self.model_requests = 0
        self.tool_definitions = tool_definitions
        self.allowed_tools = {item["name"] for item in tool_definitions}
        self.results = []
        self.namespace = {
            "asyncio": asyncio,
            "json": json,
            "tool": self.call_tool,
            "tool_results": self.results,
            "instruction": instruction,
        }
        for name in self.allowed_tools:
            self.namespace[name] = self.make_helper(name)
        self.log_dir = Path(os.environ.get("METHOD_OUTPUT_DIR", "/workspace/runtime-output"))
        self.log_dir.mkdir(parents=True, exist_ok=True)
        self.trace = (self.log_dir / "trace.jsonl").open("a", encoding="utf-8")
        self.http = httpx.AsyncClient(timeout=60.0)

    def log(self, event, **values):
        self.trace.write(encode({"event": event, "elapsed": round(time.monotonic() - self.started, 2), **values}) + "\n")
        self.trace.flush()

    def make_helper(self, name):
        async def helper(**arguments):
            return await self.call_tool(name, arguments)
        return helper

    async def call_tool(self, name, arguments):
        if name not in self.allowed_tools:
            return {"error": "Unknown tool", "available": sorted(self.allowed_tools)}
        if self.tool_calls >= 98 or time.monotonic() - self.started > 555:
            raise BudgetStopped("Tool or time budget exhausted")
        self.tool_calls += 1
        self.log("tool_call", name=name, arguments=arguments)
        try:
            response = await self.http.post(
                os.environ["MAC_TERMINAL_URL"].rstrip("/") + "/call",
                headers={"Authorization": "Bearer " + os.environ["MAC_TERMINAL_TOKEN"]},
                json={"name": name, "arguments": arguments},
            )
            if response.status_code == 402:
                raise BudgetStopped("HTTP 402: host budget exhausted")
            response.raise_for_status()
            payload = response.json()
            result = decode(payload.get("result", payload))
        except BudgetStopped:
            raise
        except Exception as error:
            result = {"error": str(error), "note": "No automatic retry. If this was a write, inspect app state before retrying."}
        self.results.append({"name": name, "arguments": arguments, "result": result})
        self.log("tool_result", name=name, result=result)
        return result

    async def python(self, code):
        captured = io.StringIO()
        try:
            compiled = compile(code, "<workflow-python>", "exec", flags=ast.PyCF_ALLOW_TOP_LEVEL_AWAIT)
            with contextlib.redirect_stdout(captured):
                execution = eval(compiled, self.namespace)
                if asyncio.iscoroutine(execution):
                    await execution
        except BudgetStopped:
            raise
        except Exception:
            captured.write(traceback.format_exc(limit=4))
        output = captured.getvalue()
        if len(output) > 50000:
            artifact = self.log_dir / f"python-output-{len(self.results)}.txt"
            artifact.write_text(output, encoding="utf-8")
            output = output[:45000] + "\n[Output truncated. Values remain in Python variables and tool_results; print a smaller selection.]"
        return output or "Completed. No printed output. Variables persist."

    async def execute(self):
        prompt = Path(__file__).with_name("instructions.txt").read_text(encoding="utf-8")
        history = [
            {"role": "system", "content": prompt},
            {"role": "user", "content": self.instruction},
        ]
        tools = self.tool_definitions + [{
            "type": "function",
            "name": "run_python",
            "description": "Run persistent Python for calculations and simulated API batches. Top-level await works. Available: api_search, api_fetch, base64_encode as async keyword-argument helpers, tool(name, arguments), asyncio, json, tool_results, instruction. Use only simulated tool helpers for app access. Print concise relevant output.",
            "parameters": {"type": "object", "properties": {"code": {"type": "string"}}, "required": ["code"], "additionalProperties": False},
            "strict": True,
        }]
        client = AsyncOpenAI(
            base_url=os.environ["TASK_MODEL_API_BASE"],
            api_key=os.environ["TASK_MODEL_API_KEY"],
            max_retries=0,
            timeout=180.0,
        )
        final = ""
        self.log("start", instruction=self.instruction, tools=self.tool_definitions)
        try:
            for turn in range(46):
                if time.monotonic() - self.started > 555:
                    break
                self.model_requests += 1
                response = await client.responses.create(
                    model=os.environ["TASK_MODEL_NAME"],
                    input=history,
                    tools=tools,
                    store=False,
                    include=["reasoning.encrypted_content"],
                )
                items = [item.model_dump(exclude_none=True) for item in response.output]
                history.extend(items)
                self.log("model", turn=turn, output=items, usage=response.usage.model_dump() if response.usage else {})
                calls = [item for item in response.output if item.type == "function_call"]
                if not calls:
                    final = response.output_text
                    if final:
                        break
                    history.append({"role": "user", "content": "Continue executing outstanding requirements, or provide your final report if done."})
                    continue
                for call in calls:
                    try:
                        arguments = json.loads(call.arguments)
                        if call.name == "run_python":
                            result = await self.python(arguments["code"])
                        else:
                            result = await self.call_tool(call.name, arguments)
                        output = result if isinstance(result, str) else encode(result)
                    except BudgetStopped:
                        raise
                    except Exception as error:
                        output = encode({"error": str(error)})
                    history.append({"type": "function_call_output", "call_id": call.call_id, "output": output})
                    self.log("function_output", name=call.name, output=output)
                if turn == 34 or self.tool_calls >= 85 or time.monotonic() - self.started > 450:
                    history.append({"role": "user", "content": f"Budget checkpoint: {self.tool_calls}/100 simulated calls used; {round(570 - (time.monotonic() - self.started))} seconds remain. Prioritize remaining required writes and a compact final verification. Do not repeat completed work."})
        except Exception as error:
            self.log("stopped", error=str(error))
            print("Workflow stopped: " + str(error), file=sys.stderr)
            if getattr(error, "status_code", None) == 402 or isinstance(error, BudgetStopped):
                final = "Execution stopped at the available budget limit. Completed API operations are retained; the remaining workflow could not be confirmed."
            else:
                final = "Execution stopped due to an error: " + str(error)
        finally:
            await client.close()
            await self.http.aclose()
            self.log("finish", model_requests=self.model_requests, tool_calls=self.tool_calls, report=final)
            self.trace.close()
        return final or "Execution reached its time or request limit. Some requested work may remain incomplete."


async def main():
    inputs = json.load(sys.stdin)
    raw_tools = json.loads(Path("/run-input/tools.json").read_text(encoding="utf-8"))
    agent = Workflow(inputs["instruction"], definitions(raw_tools))
    report = await agent.execute()
    print(encode({"report": report}))


if __name__ == "__main__":
    asyncio.run(main())

import asyncio
import base64
import contextlib
import datetime
import email
import io
import json
import os
import re
import sys
import time
import traceback
from decimal import Decimal
from pathlib import Path

import httpx
from openai import AsyncOpenAI


class ResourceStop(BaseException):
    pass


def serialize(value):
    return json.dumps(value, ensure_ascii=False, default=str, separators=(",", ":"))


def parse_result(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except (ValueError, TypeError):
            return value
    return value


def load_tools(path):
    source = json.loads(Path(path).read_text())
    if isinstance(source, dict):
        source = source.get("tools", source)
    if isinstance(source, dict):
        source = [dict(value, name=value.get("name", name)) for name, value in source.items()]
    normalized = []
    for item in source:
        definition = item.get("function", item)
        name = definition.get("name")
        if not name:
            continue
        parameters = definition.get("parameters", definition.get("inputSchema", definition.get("input_schema", {"type": "object", "properties": {}})))
        normalized.append({"type": "function", "name": name, "description": definition.get("description", ""), "parameters": parameters, "strict": False})
    if not normalized:
        raise ValueError("No simulated tool definitions supplied")
    return normalized


class Workflow:
    def __init__(self, instruction):
        self.instruction = instruction
        self.started = time.monotonic()
        self.deadline = self.started + 565
        self.tools = load_tools("/run-input/tools.json")
        self.tool_names = {tool["name"] for tool in self.tools}
        self.aliases = {}
        for alias in ("api_search", "api_fetch", "base64_encode"):
            matches = [name for name in self.tool_names if name == alias or name.endswith("__" + alias) or name.endswith("_" + alias)]
            if matches:
                self.aliases[alias] = matches[0]
        self.results = {}
        self.state = {}
        self.calls = 0
        self.requests = 0
        self.stop_reason = None
        self.notes = set()
        self.last_report = ""
        self.history = []
        self.semaphore = asyncio.Semaphore(6)
        self.http = httpx.AsyncClient(timeout=httpx.Timeout(65))
        self.client = AsyncOpenAI(base_url=os.environ["TASK_MODEL_API_BASE"], api_key=os.environ["TASK_MODEL_API_KEY"], max_retries=0, timeout=180)
        output_dir = Path(os.environ.get("METHOD_OUTPUT_DIR", "/workspace/output"))
        output_dir.mkdir(parents=True, exist_ok=True)
        self.trace_file = (output_dir / "workflow-trace.jsonl").open("a")

    def trace(self, kind, data):
        self.trace_file.write(serialize({"kind": kind, "elapsed": round(time.monotonic() - self.started, 2), "data": data}) + "\n")
        self.trace_file.flush()

    def remaining(self):
        return self.deadline - time.monotonic()

    async def remote(self, name, arguments):
        if self.stop_reason:
            raise ResourceStop(self.stop_reason)
        name = self.aliases.get(name, name)
        if name not in self.tool_names:
            return {"error": "Unknown simulated tool", "available": sorted(self.tool_names)}
        async with self.semaphore:
            if self.calls >= 98 or self.remaining() < 8:
                self.stop_reason = "Execution tool/time limit reached"
                raise ResourceStop(self.stop_reason)
            self.calls += 1
            reference = "r" + str(self.calls)
            self.trace("tool_request", {"ref": reference, "name": name, "arguments": arguments})
            try:
                response = await self.http.post(os.environ["MAC_TERMINAL_URL"].rstrip("/") + "/call", headers={"Authorization": "Bearer " + os.environ["MAC_TERMINAL_TOKEN"]}, json={"name": name, "arguments": arguments}, timeout=min(65, max(1, self.remaining() - 3)))
                if response.status_code == 402:
                    self.stop_reason = "HTTP 402: execution budget exhausted"
                    raise ResourceStop(self.stop_reason)
                if response.status_code >= 400:
                    result = {"error": "Tool transport HTTP " + str(response.status_code), "detail": response.text, "write_status": "If this was a write, completion is uncertain; read back before retry."}
                else:
                    envelope = response.json()
                    result = parse_result(envelope.get("result", envelope))
            except (httpx.HTTPError, ValueError) as error:
                result = {"error": str(error), "write_status": "Completion uncertain if this was a write. Read back before retrying."}
            self.results[reference] = result
            self.trace("tool_result", {"ref": reference, "result": result})
            return reference, result

    async def call_tool(self, name, arguments):
        result = await self.remote(name, arguments)
        if isinstance(result, tuple):
            return result[1]
        return result

    def wrapper(self, name):
        async def invoke(**arguments):
            return await self.call_tool(name, arguments)
        return invoke

    async def python(self, code):
        capture = io.StringIO()
        namespace = {"call_tool": self.call_tool, "tools": self.tools, "results": self.results, "state": self.state, "asyncio": asyncio, "json": json, "Decimal": Decimal, "datetime": datetime, "re": re, "base64": base64, "email": email}
        for name in self.aliases:
            namespace[name] = self.wrapper(name)
        wrapped = "async def __task__():\n" + "\n".join("    " + line for line in code.splitlines())
        first_call = self.calls + 1
        try:
            with contextlib.redirect_stdout(capture):
                exec(compile(wrapped, "<workflow-python>", "exec"), namespace)
                returned = await asyncio.wait_for(namespace["__task__"](), timeout=min(100, max(1, self.remaining() - 5)))
            output = {"stdout": capture.getvalue()}
            if returned is not None:
                output["return"] = returned
        except Exception as error:
            output = {"stdout": capture.getvalue(), "error": type(error).__name__ + ": " + str(error), "traceback": traceback.format_exc(limit=4), "warning": "Earlier calls in this code may have succeeded; inspect results before retrying."}
        if self.calls >= first_call:
            output["stored_results"] = ["r" + str(number) for number in range(first_call, self.calls + 1)]
        return serialize(output)

    async def dispatch(self, item):
        try:
            arguments = json.loads(item.arguments)
        except ValueError as error:
            return serialize({"error": "Invalid JSON arguments: " + str(error)})
        if item.name == "python":
            return await self.python(arguments["code"])
        result = await self.remote(item.name, arguments)
        if isinstance(result, tuple):
            return serialize({"ref": result[0], "result": result[1]})
        return serialize(result)

    async def run(self):
        system = Path(__file__).with_name("workflow_prompt.txt").read_text()
        self.history = [{"role": "system", "content": system}, {"role": "user", "content": self.instruction}]
        local_tool = {"type": "function", "name": "python", "description": "Execute an async Python body for precise calculations, processing stored API results, and bounded batches of simulated API calls. Use print to return evidence, state for persistent values, results for past raw responses. No networking or subprocesses.", "parameters": {"type": "object", "properties": {"code": {"type": "string"}}, "required": ["code"], "additionalProperties": False}, "strict": True}
        available_tools = self.tools + [local_tool]
        try:
            while self.requests < 46 and self.remaining() > 10:
                remaining = self.remaining()
                if (remaining < 140 or self.calls >= 75 or self.requests >= 37) and "low" not in self.notes:
                    self.notes.add("low")
                    self.history.append({"role": "user", "content": "Runtime notice: approximately " + str(int(remaining)) + " seconds, " + str(98 - self.calls) + " API calls, and " + str(46 - self.requests) + " model turns remain. Prioritize any still-missing requested outcomes, verify essential writes, then report. Avoid optional exploration."})
                self.requests += 1
                self.trace("model_request", {"number": self.requests, "messages": len(self.history), "remaining": round(remaining)})
                response = await self.client.responses.create(model=os.environ["TASK_MODEL_NAME"], input=self.history, tools=available_tools, store=False, include=["reasoning.encrypted_content"], timeout=min(180, max(5, remaining - 4)))
                output_items = [item.model_dump(mode="json", exclude_none=True) for item in response.output]
                self.trace("model_response", {"output": output_items, "usage": response.usage.model_dump() if response.usage else None})
                self.history.extend(output_items)
                calls = [item for item in response.output if item.type == "function_call"]
                if response.output_text:
                    self.last_report = response.output_text
                if not calls:
                    if response.output_text:
                        return response.output_text
                    self.history.append({"role": "user", "content": "Please continue the requested work using tools, or provide the final report if complete."})
                    continue
                for item in calls:
                    output = await self.dispatch(item)
                    self.history.append({"type": "function_call_output", "call_id": item.call_id, "output": output})
                    self.trace("function_output", {"name": item.name, "output": output})
            self.stop_reason = "Execution time or model-request limit reached"
        except ResourceStop as error:
            self.stop_reason = str(error)
        except Exception as error:
            status = getattr(error, "status_code", None)
            self.stop_reason = "HTTP 402: execution budget exhausted" if status == 402 else type(error).__name__ + ": " + str(error)
            self.trace("error", {"message": self.stop_reason})
        finally:
            await self.http.aclose()
            await self.client.close()
            self.trace_file.close()
        report = "Execution stopped: " + str(self.stop_reason) + ". " + str(self.calls) + " simulated API calls were attempted. The full requested workflow is not confirmed complete."
        if self.last_report:
            report += "\n\nLast progress report (not a completion confirmation):\n" + self.last_report
        return report


async def main():
    supplied = json.load(sys.stdin)
    instruction = supplied.get("instruction", supplied.get("inputs", {}).get("instruction", ""))
    if not isinstance(instruction, str) or not instruction.strip():
        raise ValueError("A nonempty instruction is required")
    workflow = Workflow(instruction)
    report = await workflow.run()
    print(serialize({"report": report}))


if __name__ == "__main__":
    asyncio.run(main())

import ast
import asyncio
import contextlib
import inspect
import io
import json
import os
import re
import sys
import time
import traceback
from pathlib import Path

import httpx
from openai import AsyncOpenAI


class BudgetExhausted(BaseException):
    pass


def decode_result(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except (ValueError, TypeError):
            return value
    return value


def get_tool_definitions(document):
    candidates = []

    def visit(value, key=None):
        if isinstance(value, list):
            for item in value:
                visit(item)
        elif isinstance(value, dict):
            if isinstance(value.get("function"), dict):
                visit(value["function"])
            elif "name" in value and any(
                field in value for field in ("parameters", "input_schema", "inputSchema")
            ):
                candidates.append(value)
            elif key and any(
                field in value for field in ("parameters", "input_schema", "inputSchema")
            ):
                candidates.append({"name": key, **value})
            else:
                for child_key, child in value.items():
                    visit(child, child_key)

    visit(document)
    result = {}
    for definition in candidates:
        name = definition["name"]
        if any(part in name for part in ("api_search", "api_fetch", "base64_encode")):
            result[name] = definition
    if not result:
        raise ValueError("No supplied api_search/api_fetch/base64_encode definitions found")
    return result


class WorkflowAgent:
    def __init__(self, instruction):
        self.instruction = instruction
        self.started = time.monotonic()
        self.remote_calls = 0
        self.turns = 0
        self.results = {}
        self.events = []
        self.history = []
        self.client = AsyncOpenAI(
            base_url=os.environ["TASK_MODEL_API_BASE"],
            api_key=os.environ["TASK_MODEL_API_KEY"],
            max_retries=0,
            timeout=180,
        )
        self.http = httpx.AsyncClient(timeout=90)
        document = json.loads(Path("/run-input/tools.json").read_text())
        self.definitions = get_tool_definitions(document)
        self.aliases = {}
        self.tools = []
        for original_name, definition in self.definitions.items():
            alias = re.sub(r"[^a-zA-Z0-9_-]", "_", original_name)[-64:]
            self.aliases[alias] = original_name
            self.tools.append({
                "type": "function",
                "name": alias,
                "description": definition.get("description", original_name),
                "parameters": definition.get(
                    "parameters", definition.get("input_schema", definition.get("inputSchema"))
                ),
                "strict": False,
            })
        self.tools.append({
            "type": "function",
            "name": "workbench",
            "description": (
                "Execute Python with persistent variables and top-level await for calculations, "
                "data inspection, and batches of discovered simulated API calls. print() returns "
                "output. Wrappers api_search(**kwargs), api_fetch(**kwargs), base64_encode(**kwargs), "
                "and call_tool(name, arguments) return decoded results. Prior remote results are "
                "in results['t1'], etc. Original schemas are in tool_definitions. All remote calls "
                "use the same host budgets. No automatic retries; reconcile uncertain writes."
            ),
            "parameters": {
                "type": "object",
                "properties": {"code": {"type": "string"}},
                "required": ["code"],
                "additionalProperties": False,
            },
            "strict": True,
        })
        self.namespace = {
            "__builtins__": __builtins__,
            "asyncio": asyncio,
            "json": json,
            "results": self.results,
            "tool_definitions": self.definitions,
            "call_tool": self.call_tool,
        }
        for short_name in ("api_search", "api_fetch", "base64_encode"):
            matches = [name for name in self.definitions if short_name in name]
            if matches:
                self.namespace[short_name] = self.make_wrapper(matches[0])

    def remaining(self):
        return 560 - (time.monotonic() - self.started)

    def make_wrapper(self, name):
        async def wrapper(**arguments):
            value, reference = await self.remote(name, arguments)
            return value

        return wrapper

    async def call_tool(self, name, arguments):
        value, reference = await self.remote(self.aliases.get(name, name), arguments)
        return value

    async def remote(self, name, arguments):
        if name not in self.definitions:
            raise ValueError(f"Unknown supplied tool: {name}")
        if self.remote_calls >= 96 or self.remaining() < 8:
            return {"error": "Local time or tool limit reached; report confirmed results."}, None
        self.remote_calls += 1
        reference = f"t{self.remote_calls}"
        event = {"ref": reference, "name": name, "arguments": arguments}
        self.events.append(event)
        try:
            response = await self.http.post(
                os.environ["MAC_TERMINAL_URL"].rstrip("/") + "/call",
                headers={"Authorization": "Bearer " + os.environ["MAC_TERMINAL_TOKEN"]},
                json={"name": name, "arguments": arguments},
                timeout=max(1, min(90, self.remaining() - 5)),
            )
            if response.status_code == 402:
                raise BudgetExhausted("The service budget was exhausted (HTTP 402).")
            if response.is_error:
                value = {"error": f"Tool transport HTTP {response.status_code}", "detail": response.text}
            else:
                payload = response.json()
                value = decode_result(payload.get("result", payload))
        except BudgetExhausted:
            raise
        except Exception as error:
            value = {
                "error": str(error),
                "note": "No automatic retry occurred. For writes, check whether it committed before retrying.",
            }
        self.results[reference] = value
        event["result"] = value
        return value, reference

    async def execute_tool(self, item):
        try:
            arguments = json.loads(item.arguments)
            if item.name == "workbench":
                output = io.StringIO()
                try:
                    with contextlib.redirect_stdout(output):
                        code = compile(arguments["code"], "<workbench>", "exec", ast.PyCF_ALLOW_TOP_LEVEL_AWAIT)
                        execution = eval(code, self.namespace, self.namespace)
                        if inspect.isawaitable(execution):
                            await asyncio.wait_for(execution, timeout=max(1, min(140, self.remaining() - 5)))
                except BudgetExhausted:
                    raise
                except Exception:
                    output.write(traceback.format_exc(limit=4))
                return output.getvalue() or "Executed successfully; no output printed. Variables persist."
            original_name = self.aliases[item.name]
            value, reference = await self.remote(original_name, arguments)
            text = value if isinstance(value, str) else json.dumps(value, ensure_ascii=False)
            return f"Python reference: results[{reference!r}]\n{text}"
        except BudgetExhausted:
            raise
        except Exception as error:
            return json.dumps({"error": str(error), "action": "Correct the tool arguments and continue."})

    def save_trace(self):
        try:
            destination = Path(os.environ.get("METHOD_OUTPUT_DIR", "/tmp/workflow-agent"))
            destination.mkdir(parents=True, exist_ok=True)
            (destination / "workflow-trace.json").write_text(json.dumps({
                "history": self.history,
                "events": self.events,
                "model_requests": self.turns,
                "remote_calls": self.remote_calls,
            }, ensure_ascii=False, default=str))
        except Exception as error:
            print(f"Trace could not be saved: {error}", file=sys.stderr)

    def fallback_report(self, reason):
        receipts = []
        for event in self.events:
            arguments = event.get("arguments", {})
            method = str(arguments.get("method", arguments.get("http_method", ""))).upper()
            if method in ("POST", "PUT", "PATCH", "DELETE"):
                endpoint = next((arguments[key] for key in ("path", "url", "endpoint", "resource") if key in arguments), "")
                response = json.dumps(event.get("result", "Unconfirmed"), ensure_ascii=False, default=str)
                if len(response) > 1400:
                    response = response[:1400] + " [receipt excerpt]"
                receipts.append(f"- {method} {endpoint}: {response}")
        report = f"Execution stopped: {reason} Not all requested outcomes are verified."
        if receipts:
            report += "\nRecorded write responses (these may include errors):\n" + "\n".join(receipts[-12:])
            if len(receipts) > 12:
                report += f"\n{len(receipts) - 12} earlier write responses are retained in the execution trace."
        else:
            report += " No completed changes can be confirmed from the write receipts."
        return report

    async def run(self):
        prompt = Path(__file__).with_name("workflow_prompt.txt").read_text()
        self.history = [
            {"role": "developer", "content": prompt},
            {"role": "user", "content": self.instruction},
        ]
        try:
            for turn in range(48):
                self.turns = turn + 1
                if self.remaining() < 8:
                    return self.fallback_report("The execution time limit was reached.")
                finishing = self.remaining() < 35 or self.remote_calls >= 96 or turn == 47
                if finishing or turn in (12, 24, 36) or (self.remaining() < 100 and turn % 3 == 0):
                    self.history.append({
                        "role": "developer",
                        "content": (
                            f"Execution budget: {self.remaining():.0f} seconds remaining, "
                            f"{96 - self.remote_calls} remote calls, {48 - turn} model requests. "
                            + ("No tools remain for this turn. Report confirmed results and any gaps now."
                               if finishing else "Prioritize completing remaining requested outcomes; avoid redundant exploration.")
                        ),
                    })
                response = await self.client.responses.create(
                    model=os.environ["TASK_MODEL_NAME"],
                    input=self.history,
                    tools=[] if finishing else self.tools,
                    store=False,
                    include=["reasoning.encrypted_content"],
                    timeout=max(5, min(180, self.remaining())),
                )
                self.history.extend(item.model_dump(mode="json", exclude_none=True) for item in response.output)
                calls = [item for item in response.output if item.type == "function_call"]
                if not calls:
                    if response.output_text:
                        return response.output_text
                    self.history.append({"role": "developer", "content": "Continue the task, or return the final factual report if finished."})
                    continue
                for item in calls:
                    result = await self.execute_tool(item)
                    self.history.append({"type": "function_call_output", "call_id": item.call_id, "output": result})
                self.save_trace()
            return self.fallback_report("The model request limit was reached.")
        except BudgetExhausted as error:
            return self.fallback_report(str(error))
        except Exception as error:
            if getattr(error, "status_code", None) == 402:
                return self.fallback_report("The model service budget was exhausted (HTTP 402).")
            print(traceback.format_exc(), file=sys.stderr)
            return self.fallback_report(f"{type(error).__name__}: {error}")
        finally:
            self.save_trace()
            await self.http.aclose()
            await self.client.close()


async def main():
    inputs = json.load(sys.stdin)
    instruction = inputs.get("instruction", "")
    if not isinstance(instruction, str) or not instruction.strip():
        raise ValueError("A nonempty instruction is required")
    agent = WorkflowAgent(instruction)
    report = await agent.run()
    print(json.dumps({"report": report}, ensure_ascii=False))


if __name__ == "__main__":
    asyncio.run(main())

import ast
import asyncio
import base64
import collections
import contextlib
import datetime
import io
import json
import os
from pathlib import Path
import re
import sys
import time
import traceback
import urllib.parse
from decimal import Decimal

import httpx
from openai import AsyncOpenAI


class BudgetStop(BaseException):
    pass


def json_text(value):
    return json.dumps(value, ensure_ascii=False, default=str, separators=(",", ":"))


def decode(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except (ValueError, TypeError):
            return value
    return value


def load_tools(path):
    raw = json.loads(Path(path).read_text())
    if isinstance(raw, dict):
        raw = raw.get("tools", raw)
    if isinstance(raw, dict):
        raw = [dict(value, name=value.get("name", key)) for key, value in raw.items()]
    tools = []
    for entry in raw:
        function = entry.get("function", entry)
        name = function.get("name", "")
        if not any(part in name for part in ("api_search", "api_fetch", "base64_encode")):
            continue
        tools.append({
            "type": "function",
            "name": name,
            "description": function.get("description", ""),
            "parameters": function.get("parameters", function.get("input_schema", function.get("inputSchema", {"type": "object", "properties": {}}))),
            "strict": False,
        })
    if not tools:
        raise ValueError("No simulated API tools supplied in /run-input/tools.json")
    return tools


PYTHON_TOOL = {
    "type": "function",
    "name": "run_python",
    "description": "Execute persistent Python with top-level await. Compute, inspect stored results, encode data, or batch known simulated API operations. Use await call_tool(name, arguments) or supplied tool-name helpers. Original schemas are in tools; decoded results are in results under r1, r2, etc. Print relevant output. No direct network calls or real business services.",
    "parameters": {"type": "object", "properties": {"code": {"type": "string"}}, "required": ["code"], "additionalProperties": False},
    "strict": True,
}


class Workflow:
    def __init__(self):
        self.start = time.monotonic()
        self.tools = load_tools("/run-input/tools.json")
        self.tool_names = {tool["name"] for tool in self.tools}
        self.results = {}
        self.calls = 0
        self.requests = 0
        self.last_report = ""
        self.semaphore = asyncio.Semaphore(6)
        self.http = httpx.AsyncClient(timeout=httpx.Timeout(65.0, connect=15.0))
        self.client = AsyncOpenAI(
            base_url=os.environ["TASK_MODEL_API_BASE"],
            api_key=os.environ["TASK_MODEL_API_KEY"],
            max_retries=0,
            timeout=180.0,
        )
        self.namespace = {
            "__builtins__": __builtins__, "json": json, "asyncio": asyncio,
            "base64": base64, "re": re, "datetime": datetime,
            "Decimal": Decimal, "collections": collections, "urllib": urllib,
            "results": self.results, "tools": self.tools, "call_tool": self.call_tool,
        }
        for name in self.tool_names:
            self.namespace[name] = self.make_helper(name)
        for alias in ("api_search", "api_fetch", "base64_encode"):
            matches = [name for name in self.tool_names if alias in name]
            if len(matches) == 1:
                self.namespace[alias] = self.make_helper(matches[0])
        output_dir = Path(os.environ.get("METHOD_OUTPUT_DIR", "/workspace"))
        output_dir.mkdir(parents=True, exist_ok=True)
        self.trace_path = output_dir / "workflow-trace.jsonl"

    def log(self, event, **data):
        with self.trace_path.open("a") as trace:
            trace.write(json_text({"event": event, "elapsed": round(time.monotonic() - self.start, 2), **data}) + "\n")

    def make_helper(self, name):
        async def helper(arguments=None, **kwargs):
            return await self.call_tool(name, {**(arguments or {}), **kwargs})
        return helper

    def check_budget(self):
        if time.monotonic() - self.start > 585:
            raise BudgetStop("Execution time limit reached")

    async def call_tool(self, name, arguments):
        self.check_budget()
        if name not in self.tool_names:
            return {"error": "Unknown simulated tool", "available": sorted(self.tool_names)}
        async with self.semaphore:
            self.check_budget()
            if self.calls >= 100:
                raise BudgetStop("Simulated tool-call limit reached")
            self.calls += 1
            key = f"r{self.calls}"
            self.log("tool_request", key=key, name=name, arguments=arguments)
            try:
                response = await self.http.post(
                    os.environ["MAC_TERMINAL_URL"].rstrip("/") + "/call",
                    headers={"Authorization": "Bearer " + os.environ["MAC_TERMINAL_TOKEN"]},
                    json={"name": name, "arguments": arguments},
                )
                if response.status_code == 402:
                    raise BudgetStop("Host budget exhausted (HTTP 402)")
                response.raise_for_status()
                envelope = response.json()
                result = decode(envelope.get("result", envelope))
            except (httpx.HTTPError, ValueError) as error:
                result = {"transport_error": str(error), "warning": "A write may have committed. Check application state before retrying."}
                if isinstance(error, httpx.HTTPStatusError):
                    result["response_body"] = error.response.text[:10000]
            self.results[key] = result
            self.log("tool_result", key=key, result=result)
            return result

    def display(self, value, limit=42000):
        text = value if isinstance(value, str) else json_text(value)
        if len(text) <= limit:
            return text
        return text[:limit] + "\n[DISPLAY SHORTENED: full data is retained in results. Use run_python to inspect omitted fields/records; do not assume completeness.]"

    async def execute(self, call):
        try:
            arguments = json.loads(call.arguments)
            if call.name == "run_python":
                capture = io.StringIO()
                with contextlib.redirect_stdout(capture):
                    try:
                        compiled = compile(arguments["code"], "<workflow-python>", "exec", flags=ast.PyCF_ALLOW_TOP_LEVEL_AWAIT)
                        execution = eval(compiled, self.namespace)
                        if execution is not None:
                            await execution
                    except Exception:
                        traceback.print_exc(file=capture)
                output = capture.getvalue() or "Executed. No output printed; variables and results persist."
                self.log("python", code=arguments["code"], output=output)
                return self.display(output)
            first_key = self.calls + 1
            result = await self.call_tool(call.name, arguments)
            return f"Stored full result in results['r{first_key}'].\n" + self.display(result)
        except Exception as error:
            return json_text({"error": type(error).__name__, "message": str(error)})

    async def run(self, instruction):
        prompt = Path(__file__).with_name("workflow_prompt.txt").read_text()
        conversation = [{"role": "system", "content": prompt}, {"role": "user", "content": instruction}]
        self.log("start", instruction=instruction, tools=self.tools)
        for turn in range(50):
            self.check_budget()
            self.requests += 1
            print(f"Workflow turn {turn + 1}; simulated calls {self.calls}; elapsed {round(time.monotonic() - self.start)}s", file=sys.stderr, flush=True)
            try:
                response = await self.client.responses.create(
                    model=os.environ["TASK_MODEL_NAME"],
                    input=conversation,
                    tools=self.tools + [PYTHON_TOOL],
                    store=False,
                    include=["reasoning.encrypted_content"],
                )
            except Exception as error:
                if getattr(error, "status_code", None) == 402:
                    raise BudgetStop("Host budget exhausted (HTTP 402)")
                self.log("model_error", error=str(error))
                raise
            outputs = [item.model_dump(mode="json", exclude_none=True) for item in response.output]
            conversation.extend(outputs)
            self.log("model_response", output=outputs, usage=response.usage.model_dump() if response.usage else None)
            calls = [item for item in response.output if item.type == "function_call"]
            if response.output_text:
                self.last_report = response.output_text
            if not calls:
                return self.last_report or "Execution ended without a final report."
            for call in calls:
                output = await self.execute(call)
                conversation.append({"type": "function_call_output", "call_id": call.call_id, "output": output})
            if self.calls >= 75 or turn >= 35 or time.monotonic() - self.start > 440:
                conversation.append({"role": "user", "content": f"Execution budget update: {self.calls}/100 simulated calls used; {turn + 1}/50 model requests used; {round(590 - (time.monotonic() - self.start))} seconds remain. Prioritize completing remaining requested writes and essential checks. Do not spend the remaining budget on repeated discovery or verbose reporting."})
        return "Execution stopped at the model request limit. Some requirements may remain incomplete."

    async def close(self):
        await self.http.aclose()
        await self.client.close()


async def main():
    payload = json.load(sys.stdin)
    workflow = None
    try:
        workflow = Workflow()
        report = await asyncio.wait_for(workflow.run(payload["instruction"]), timeout=590)
    except asyncio.TimeoutError:
        report = "Execution reached its time limit. Completed changes remain in the simulated apps; remaining work is not confirmed complete."
    except BudgetStop as error:
        report = f"Stopped: {error}. Previously completed changes remain in the simulated apps; remaining work is not confirmed complete."
    except Exception as error:
        traceback.print_exc(file=sys.stderr)
        report = f"Execution could not finish: {type(error).__name__}: {error}"
    finally:
        if workflow is not None:
            await workflow.close()
    print(json.dumps({"report": report}, ensure_ascii=False))


if __name__ == "__main__":
    asyncio.run(main())

import asyncio
import json
import os
import sys
import time
from pathlib import Path

from openai import AsyncOpenAI

from app_tools import StopRun, call_tool, decode_content, tool_definitions


def unpack(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except (ValueError, TypeError):
            pass
    return value


def decoded(value):
    if isinstance(value, list):
        return [decoded(item) for item in value]
    if not isinstance(value, dict):
        return value
    result = {key: decoded(item) for key, item in value.items()}
    if isinstance(value.get('data'), str):
        try:
            result['_decoded_text'] = decode_content([value['data']], 'base64')[0]['text']
        except Exception:
            pass
    return result


def validate_plan(plan):
    if not isinstance(plan, dict) or not isinstance(plan.get('invoices'), list):
        raise ValueError('Plan must be an object with invoices list')
    if not isinstance(plan.get('sources_complete'), bool):
        raise ValueError('sources_complete must explicitly be true or false')
    if not isinstance(plan.get('date'), str) or not isinstance(plan.get('policy_evidence', ''), str):
        raise ValueError('date and policy_evidence must be strings')
    if not isinstance(plan.get('issues', []), list) or not all(isinstance(issue, str) for issue in plan.get('issues', [])):
        raise ValueError('issues must be a list of strings')
    for invoice in plan['invoices']:
        if not isinstance(invoice, dict) or invoice.get('disposition') not in ('log', 'return', 'duplicate', 'hold'):
            raise ValueError('Every invoice must have one valid disposition')
        for field in ('vendor', 'invoice', 'amount', 'reason'):
            if not isinstance(invoice.get(field), str):
                raise ValueError('Each invoice needs a string field: ' + field)
        for field in ('source_id', 'sender', 'thread_id', 'message_id_header', 'subject', 'return_text', 'prior_return_id'):
            if field in invoice and not isinstance(invoice[field], str):
                raise ValueError('Optional invoice metadata must be a string: ' + field)
        if invoice['disposition'] == 'log':
            from execute import invoice_fields
            columns = plan.get('sheet', {}).get('columns', {})
            if any(not isinstance(value, int) or value < 0 for value in columns.values()):
                raise ValueError('Sheet columns must be nonnegative integer positions')
            invoice_fields(invoice, columns)
        if invoice['disposition'] == 'return':
            for field in ('sender', 'return_text', 'thread_id'):
                if not isinstance(invoice.get(field), str) or not invoice[field]:
                    raise ValueError('Blocked returns need verified sender, thread_id, and return_text')
    for group, fields in (('sheet', ('read', 'append')), ('mail', ('send', 'get', 'encode'))):
        recipes = plan.get(group, {})
        if recipes:
            for field in fields:
                recipe = recipes.get(field)
                if not isinstance(recipe, dict) or not isinstance(recipe.get('arguments'), dict) or not recipe.get('name'):
                    raise ValueError(group + '.' + field + ' must be a discovered tool recipe')
    mail = plan.get('mail', {})
    if mail and ('__MESSAGE_ID__' not in json.dumps(mail['get']) or '__TEXT__' not in json.dumps(mail['encode'])):
        raise ValueError('Mail recipes must use __MESSAGE_ID__ and __TEXT__ placeholders')


class Reviewer:
    def __init__(self):
        self.calls = 0
        self.stopped = False
        self.started = time.monotonic()
        self.discoveries = []

    def observe(self, name, arguments):
        arguments = unpack(arguments)
        if name == 'catalog':
            return tool_definitions()
        if name == 'batch':
            calls = arguments['calls']
            if not isinstance(calls, list) or not 1 <= len(calls) <= 12:
                raise ValueError('Use 1-12 independent reads per batch')
            return [{'name': call['name'], 'arguments': call['arguments'],
                     'result': self.observe(call['name'], call['arguments'])} for call in calls]
        if self.stopped or self.calls >= 50 or time.monotonic() - self.started > 330:
            raise ValueError('Investigation budget exhausted: submit your plan now')
        self.calls += 1
        try:
            result = decoded(unpack(call_tool(name, arguments, 'read')))
        except StopRun:
            self.stopped = True
            raise
        if name.endswith('api_search'):
            self.discoveries.append(result)
        return result


async def investigate(instruction):
    reviewer = Reviewer()
    fallback = {'date': '', 'sources_complete': False, 'issues': [], 'invoices': [],
                'sheet': {}, 'mail': {}, 'policy_evidence': ''}
    catalog = tool_definitions()
    prompt = Path(__file__).with_name('ap_prompt.txt').read_text()
    conversation = [
        {'role': 'developer', 'content': prompt + '\n\nSUPPLIED TOOL DEFINITIONS:\n' + json.dumps(catalog)},
        {'role': 'user', 'content': instruction},
    ]
    tools = [
        {'type': 'function', 'name': 'observe',
         'description': 'Call a supplied read-only simulated tool or batch independent reads. Arguments is a JSON string. Never contacts real apps.',
         'parameters': {'type': 'object', 'properties': {'name': {'type': 'string'}, 'arguments': {'type': 'string'}},
                        'required': ['name', 'arguments'], 'additionalProperties': False}},
        {'type': 'function', 'name': 'submit_plan',
         'description': 'Finish investigation by submitting the complete JSON plan described in the instructions; no external actions occur until after this.',
         'parameters': {'type': 'object', 'properties': {'plan': {'type': 'string'}},
                        'required': ['plan'], 'additionalProperties': False}},
    ]
    client = AsyncOpenAI(base_url=os.environ['TASK_MODEL_API_BASE'],
                         api_key=os.environ['TASK_MODEL_API_KEY'], max_retries=0, timeout=120)
    try:
        for turn in range(24):
            remaining = 350 - (time.monotonic() - reviewer.started)
            if remaining <= 5:
                raise TimeoutError('Read-only review time limit reached before a complete plan')
            if turn >= 19 or reviewer.calls >= 43 or remaining < 80:
                conversation.append({'role': 'developer', 'content':
                    'Finish now: submit the plan from established evidence. Hold unresolved items explicitly. '
                    'Do not spend the remaining budget on optional discovery.'})
            choice = {'type': 'function', 'name': 'submit_plan'} if turn >= 22 or remaining < 45 else 'auto'
            response = await asyncio.wait_for(client.responses.create(
                model=os.environ['TASK_MODEL_NAME'], input=conversation, tools=tools,
                tool_choice=choice, store=False, include=['reasoning.encrypted_content']), timeout=remaining)
            conversation.extend(item.model_dump(exclude_none=True) for item in response.output)
            functions = [item for item in response.output if item.type == 'function_call']
            for function in functions:
                try:
                    arguments = json.loads(function.arguments)
                    if function.name == 'submit_plan':
                        plan = json.loads(arguments['plan'])
                        validate_plan(plan)
                        plan['read_calls'] = reviewer.calls
                        plan['instruction'] = instruction
                        return plan
                    result = await asyncio.to_thread(reviewer.observe, **arguments)
                except StopRun:
                    fallback['stop'] = True
                    raise
                except Exception as error:
                    result = {'error': str(error)}
                conversation.append({'type': 'function_call_output', 'call_id': function.call_id,
                                     'output': json.dumps(result, ensure_ascii=False)})
            if not functions:
                conversation.append({'role': 'developer', 'content':
                    'You have not submitted the plan. Call submit_plan now; a prose response is not a plan.'})
        raise RuntimeError('Read-only review reached its turn limit without a plan')
    except Exception as error:
        if getattr(error, 'status_code', None) == 402:
            fallback['stop'] = True
        fallback['issues'].append('Review incomplete; no invoice writes authorized: ' + str(error))
        fallback['read_calls'] = reviewer.calls
        fallback['instruction'] = instruction
        return fallback
    finally:
        await client.close()


def main():
    inputs = json.load(sys.stdin)
    try:
        plan = asyncio.run(investigate(inputs['instruction']))
    except Exception as error:
        plan = {'date': '', 'sources_complete': False, 'invoices': [], 'sheet': {}, 'mail': {},
                'issues': ['Review unavailable: ' + str(error)], 'instruction': inputs.get('instruction', '')}
    print(json.dumps({'plan': json.dumps(plan, ensure_ascii=False)}, ensure_ascii=False))


if __name__ == '__main__':
    main()

