class BudgetStop(Exception):
    pass


def parse_amount(value):
    if not isinstance(value, str):
        raise ValueError("Amounts must be original strings, not JSON numbers")
    amount = value.strip().replace("\u00a0", " ").replace("\u202f", " ")
    negative = amount.startswith("(") and amount.endswith(")")
    if negative:
        amount = amount[1:-1].strip()
    amount = re.sub(r"^(?:USD|US\$|\$)\s*", "", amount, flags=re.I)
    amount = re.sub(r"\s*USD$", "", amount, flags=re.I).strip()
    if not re.fullmatch(r"[+-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?", amount):
        raise ValueError("Ambiguous or non-USD amount: " + value)
    try:
        parsed = Decimal(amount.replace(",", ""))
    except InvalidOperation as error:
        raise ValueError("Invalid amount: " + value) from error
    return -parsed if negative else parsed


def exact_total(amounts):
    parsed = [parse_amount(amount) for amount in amounts]
    with localcontext() as context:
        context.prec = max(50, sum(len(amount.as_tuple().digits) for amount in parsed) + 10)
        total = sum(parsed, Decimal("0.00"))
    return format(total, "f")


def decode_base64(value):
    raw = value.strip()
    return base64.urlsafe_b64decode(raw + "=" * (-len(raw) % 4)).decode("utf-8")


def expanded_text(value):
    pieces = []

    def visit(item, depth=0):
        if depth > 8:
            return
        if isinstance(item, dict):
            for nested in item.values():
                visit(nested, depth + 1)
        elif isinstance(item, list):
            for nested in item:
                visit(nested, depth + 1)
        elif isinstance(item, str):
            pieces.append(item)
            if item[:1] in ("{", "["):
                try:
                    visit(json.loads(item), depth + 1)
                except (ValueError, TypeError):
                    pass
            if len(item) > 24 and re.fullmatch(r"[A-Za-z0-9_+/=\s-]+", item):
                try:
                    decoded = decode_base64(item)
                    pieces.append(decoded)
                except (ValueError, UnicodeError):
                    pass
        elif item is not None:
            pieces.append(str(item))

    visit(value)
    return "\n".join(pieces)


def row_candidates(value):
    if isinstance(value, str):
        try:
            yield from row_candidates(json.loads(value))
        except (ValueError, TypeError):
            return
    elif isinstance(value, list):
        if len(value) >= 5 and all(not isinstance(item, (dict, list)) for item in value):
            yield value
        else:
            for item in value:
                yield from row_candidates(item)
    elif isinstance(value, dict):
        flat_values = [item for item in value.values() if not isinstance(item, (dict, list))]
        if len(flat_values) >= 5:
            yield flat_values
        for item in value.values():
            yield from row_candidates(item)


def sent_messages(value):
    if isinstance(value, str):
        try:
            yield from sent_messages(json.loads(value))
        except (ValueError, TypeError):
            return
    elif isinstance(value, list):
        for item in value:
            yield from sent_messages(item)
    elif isinstance(value, dict):
        if "SENT" in value.get("labelIds", value.get("label_ids", [])):
            yield value
        for item in value.values():
            yield from sent_messages(item)


def normalize_tools(raw):
    if isinstance(raw, dict):
        if "tools" in raw:
            raw = raw["tools"]
        else:
            raw = [dict(value, name=key) for key, value in raw.items()]
    tools = []
    for item in raw:
        function = item.get("function", item)
        name = function.get("name", "")
        if not any(name.endswith(allowed) for allowed in ("api_search", "api_fetch", "base64_encode")):
            continue
        parameters = function.get("parameters", function.get("input_schema", function.get("inputSchema")))
        tools.append({
            "type": "function",
            "name": name,
            "description": function.get("description", ""),
            "parameters": parameters or {"type": "object", "properties": {}},
            "strict": False,
        })
    if not any(tool["name"].endswith("api_fetch") for tool in tools):
        raise ValueError("No simulated api_fetch tool definition available")
    return tools


def local_tool(name, description, properties, required):
    return {
        "type": "function", "name": name, "description": description,
        "parameters": {"type": "object", "properties": properties, "required": required},
        "strict": False,
    }


