    "additionalProperties": False,
}
TOOLS = [
    function_tool("ap_decode", "Decode a base64/base64url UTF-8 source body; no external action.", {"data": TEXT}, ["data"]),
    function_tool(
        "ap_commit",
        "Execute the fully reviewed invoice plan and END THE RUN. Registers all candidates, appends eligible rows in RAW mode, reads them back, returns blocked invoices to original senders, sends the exact ledger summary to ap-lead@company.example.com, and returns the final report plus JSON. No further model turn is required. Discover the endpoints and review all sources first. All requests contain method, discovered url with path variables filled, and JSON-string params or null; bodies are generated safely in code. No automatic retries. Use empty URL requests when no sheet write is needed. columns maps worksheet columns in order to vendor, invoice, date, amount, due_date, note, or blank. note holds required review flags/correction provenance. reason explains every exclusion. source identifies the original email(s). Set review_complete false if investigation is unfinished or ambiguity remains.",
