]


def unpack(value):
    while isinstance(value, str):
        try:
            decoded = json.loads(value)
        except (ValueError, TypeError):
            break
        if decoded == value:
            break
        value = decoded
    return value


def objects(value):
    value = unpack(value)
    if isinstance(value, dict):
        yield value
        for child in value.values():
            yield from objects(child)
    elif isinstance(value, list):
        for child in value:
            yield from objects(child)


def sent_receipt(value):
    return not obvious_failure(value) and any(item.get("id") or item.get("messageId") for item in objects(value))


def encoded_email(value, raw):
    value = unpack(value)
    if isinstance(value, str):
        candidate = re.sub(r"\s+", "", value)
        try:
            if base64.urlsafe_b64decode(candidate + "=" * (-len(candidate) % 4)).decode("utf-8") == raw:
                return candidate.replace("+", "-").replace("/", "_")
        except (ValueError, UnicodeError):
            pass
    elif isinstance(value, (dict, list)):
        for child in value.values() if isinstance(value, dict) else value:
            candidate = encoded_email(child, raw)
            if candidate:
                return candidate
    return None


class BatchAgent(APAgent):
    def __init__(self):
        super().__init__()
        self.deadline = time.monotonic() + 565
        self.discovery_deadline = time.monotonic() + 410
        self.names = {}
        self.definitions = []
        self.discovered = []
        self.committing = False

    def endpoint(self, request, method):
        if request["method"].upper() != method:
            raise ValueError(f"Expected {method} request")
        for endpoint in self.discovered:
            pattern = re.escape(endpoint["url"])
            pattern = re.sub(r"\\\{[^}]+\\\}", r"[^/?]+", pattern)
            if endpoint.get("method", "GET").upper() == method and re.fullmatch(pattern, request["url"]):
                return endpoint
        raise ValueError("Request must match an endpoint definition already discovered with api_search")

    async def app(self, suffix, arguments):
        remaining = self.deadline - time.monotonic()
        if remaining < 2 or self.app_calls >= 95:
            raise StopExecution("Execution resources exhausted; unresolved actions require review.")
        name = next(name for name in self.names.values() if name.endswith(suffix))
        self.app_calls += 1
        reference = "api_" + str(self.app_calls)
        self.calls[reference] = {"name": name, "arguments": copy.deepcopy(arguments), "result": {"error": "Completion unknown"}}
        response = await self.transport.post(
            os.environ["MAC_TERMINAL_URL"].rstrip("/") + "/call",
            headers={"Authorization": "Bearer " + os.environ["MAC_TERMINAL_TOKEN"]},
            json={"name": name, "arguments": arguments},
            timeout=min(20, remaining),
        )
        if response.status_code == 402:
            raise StopExecution("HTTP 402: service budget exhausted; stopped without retrying.")
        response.raise_for_status()
        payload = response.json()
        payload = payload.get("result", payload)
        self.calls[reference]["result"] = payload
        if suffix == "api_search":
            self.discovered.extend(item for item in objects(payload) if "url" in item and "method" in item)
        return reference, payload

    async def fetch(self, request, body=None):
        return await self.app("api_fetch", {**request, "body": json.dumps(body, ensure_ascii=False) if body is not None else None})

    def encode_arguments(self, raw):
        definition = next(tool for tool in self.definitions if tool["name"].endswith("base64_encode"))
        properties = definition["parameters"].get("properties", {})
        field = next((name for name in ("text", "data", "input", "value") if name in properties), None)
        if field is None:
            raise ValueError("Unsupported supplied base64_encode input schema")
        arguments = {field: raw}
        for name in ("urlsafe", "url_safe"):
            if name in properties:
                arguments[name] = True
        return arguments

    async def send(self, request, recipient, subject, body):
        raw = mime_email(recipient, subject, body)
        _, payload = await self.app("base64_encode", self.encode_arguments(raw))
        encoded = encoded_email(payload, raw)
        if encoded is None:
            raise ValueError("Email encoding did not preserve the exact MIME content")
        reference, receipt = await self.fetch(request, {"raw": encoded})
        if not sent_receipt(receipt):
            raise ValueError("Email send was not confirmed; no automatic resend")
        return reference

    def preflight(self, plan):
        records = {}
        identities = set()
        for candidate in plan["records"]:
            if any(not isinstance(candidate.get(field), str) for field in PLAN_RECORD["required"]):
                raise ValueError("All invoice plan fields must be strings")
            if candidate["action"] not in PLAN_RECORD["properties"]["action"]["enum"]:
                raise ValueError("Unknown invoice action")
            identity = candidate["vendor"], candidate["invoice"]
            if candidate["key"] in records or identity in identities:
                raise ValueError("Duplicate invoice plan entry; merge repeated sources")
            identities.add(identity)
            if candidate["action"] == "log":
                if any(not candidate[field] for field in ("vendor", "invoice", "date", "amount", "due_date")):
                    raise ValueError("Cannot log an invoice with missing required data")
                money(candidate["amount"])
            elif not candidate["reason"]:
                raise ValueError("Each excluded invoice needs a precise reason")
            if candidate["action"] == "return":
                mime_email(candidate["sender"], "Invoice returned by accounts payable", candidate["reason"])
            records[candidate["key"]] = {
                **candidate,
                "outcome": "pending" if candidate["action"] in ("log", "return") else candidate["action"],
                "write_refs": [], "verify_refs": [],
            }
        if any(record["action"] == "log" for record in records.values()):
            if any(plan["columns"].count(field) != 1 for field in ("vendor", "invoice", "date", "amount", "due_date")):
                raise ValueError("Column map must contain all five required fields exactly once")
            if any(record["action"] == "log" and record["note"] for record in records.values()) and "note" not in plan["columns"]:
                raise ValueError("Required review notes must be mapped to a worksheet column")
            append_endpoint = self.endpoint(plan["append_request"], "POST")
            if "append" not in (append_endpoint.get("id", "") + append_endpoint["url"]).lower():
                raise ValueError("Spreadsheet writes must use the discovered append endpoint")
            self.endpoint(plan["verify_request"], "GET")
            parameters = json.loads(plan["append_request"].get("params") or "{}")
            if parameters.get("valueInputOption") != "RAW":
                raise ValueError("Append must use valueInputOption RAW")
        endpoint = self.endpoint(plan["send_request"], "POST")
        if "send" not in (endpoint.get("id", "") + endpoint["url"]).lower():
            raise ValueError("Email request must be a discovered send endpoint, not a draft")
        self.encode_arguments("preflight")
        self.records = records

    async def commit(self, plan):
        self.preflight(plan)
        self.committing = True
        problems = []
        pending = [record for record in self.records.values() if record["action"] == "log"]
        if pending:
            rows = [[record.get(field, "") if field != "blank" else "" for field in plan["columns"]] for record in pending]
            write_reference = None
            try:
                write_reference, receipt = await self.fetch(plan["append_request"], {"majorDimension": "ROWS", "values": rows})
                if obvious_failure(receipt):
                    raise ValueError("Spreadsheet append reported an error")
            except StopExecution:
                raise
            except Exception as error:
                problems.append(f"Spreadsheet append: {error}")
            try:
                verify_reference, receipt = await self.fetch(plan["verify_request"])
                if obvious_failure(receipt):
                    raise ValueError("Spreadsheet readback failed")
                observed_rows = spreadsheet_rows(receipt)
                for record in pending:
                    record["verify_refs"] = [verify_reference]
                    try:
                        verify_logged_record(record, self.calls)
                        expected_row = [record.get(field, "") if field != "blank" else "" for field in plan["columns"]]
                        while expected_row and expected_row[-1] == "":
                            expected_row.pop()
                        if not any(row[:len(expected_row)] == expected_row for row in observed_rows):
                            raise ValueError("Readback did not preserve the planned column order, exact fields, and required review notes.")
                    except ValueError as error:
                        record["outcome"] = "failed"
                        record["reason"] = str(error)
                        continue
                    record["write_refs"] = [write_reference] if write_reference and not obvious_failure(self.calls[write_reference]["result"]) else [verify_reference]
                    record["outcome"] = "logged"
            except StopExecution:
                raise
            except Exception as error:
                problems.append(f"Spreadsheet verification: {error}")
            for record in pending:
                if record["outcome"] == "pending":
                    record["outcome"] = "failed"
                    record["reason"] = "Spreadsheet write could not be verified; inspect the tracker before retrying."
        for record in self.records.values():
            if record["action"] != "return":
                continue
            if self.app_calls > 91 or self.deadline - time.monotonic() < 45:
                record["outcome"] = "failed"
                record["reason"] += " Return not attempted: remaining execution resources were reserved for the required AP lead summary."
                continue
            body = (
                "Accounts payable cannot accept this invoice.\n\n"
                f"Vendor: {record['vendor']}\nInvoice: {record['invoice']}\n"
                f"Date: {record['date']}\nAmount: {record['amount']}\nDue date: {record['due_date']}\n\n"
                + record["reason"]
            )
            try:
                reference = await self.send(plan["send_request"], record["sender"], "Invoice returned by accounts payable", body)
                record["write_refs"] = [reference]
                record["outcome"] = "returned"
            except StopExecution:
                raise
            except Exception as error:
                record["outcome"] = "failed"
                record["reason"] += f" Return delivery was not confirmed: {error}"
        notes = "\n".join([plan["notes"]] + problems)
        await super().helper("ap_summary", {"notes": notes})
        try:
            reference = await self.send(plan["send_request"], "ap-lead@company.example.com", "Accounts payable processing summary", self.summary)
            self.summary_send_refs = [reference]
        except StopExecution:
            raise
        except Exception as error:
            notes += f"\nAP lead summary delivery was not confirmed: {error}"
        complete = plan["review_complete"] and bool(self.summary_send_refs)
        complete = complete and all(record["outcome"] not in ("pending", "failed") for record in self.records.values())
        self.final = self.report(complete, notes)
        return self.final

    async def execute(self, instruction):
        self.definitions, self.names = load_tools()
        definitions = [tool for tool in self.definitions if not tool["name"].endswith("base64_encode")]
        prompt = Path(__file__).with_name("ap_instructions.txt").read_text()
        conversation = [{"role": "system", "content": prompt}, {"role": "user", "content": instruction}]
        client = AsyncOpenAI(base_url=os.environ["TASK_MODEL_API_BASE"], api_key=os.environ["TASK_MODEL_API_KEY"], max_retries=0, timeout=120)
        async with httpx.AsyncClient(timeout=20) as self.transport:
            try:
                for turn in range(28):
                    remaining = self.discovery_deadline - time.monotonic()
                    if remaining < 3:
                        raise StopExecution("Investigation deadline reached before a safe processing plan was ready; no writes were started.")
                    if turn >= 20 or remaining < 90:
                        conversation.append({"role": "system", "content": f"Investigation budget: {28-turn} turns, {int(remaining)} seconds. Use ap_commit now if reviewed; otherwise finish essential missing reads, then commit with unresolved candidates held/failed and review_complete=false. Execution and final email/report happen in code, without another model turn."})
                    response = await client.responses.create(
                        model=os.environ["TASK_MODEL_NAME"], input=conversation, tools=definitions + TOOLS,
                        store=False, include=["reasoning.encrypted_content"], timeout=min(120, remaining),
                    )
                    conversation.extend(item.model_dump(exclude_none=True) for item in response.output)
                    calls = [item for item in response.output if item.type == "function_call"]
                    if not calls:
                        conversation.append({"role": "user", "content": "Finish with ap_commit so the actual actions, summary email, and final JSON report are produced. Do not merely describe planned work."})
                        continue
                    for call in calls:
                        try:
                            arguments = json.loads(call.arguments)
                            if call.name == "ap_commit":
                                return await self.commit(arguments)
                            if call.name == "ap_decode":
                                output = await super().helper(call.name, arguments)
                            elif call.name in self.names:
                                suffix = "api_search" if self.names[call.name].endswith("api_search") else "api_fetch"
                                if suffix == "api_fetch" and arguments.get("method", "GET").upper() != "GET":
                                    raise ValueError("Use ap_commit for all writes so verification, summary, and final reporting cannot be skipped")
                                if self.app_calls >= 70:
                                    raise ValueError("Read budget exhausted; reserve remaining calls for ap_commit")
                                reference, payload = await self.app(suffix, arguments)
                                output = {"call_ref": reference, "result": payload}
                            else:
                                raise ValueError("Unsupported tool")
                        except StopExecution:
                            raise
                        except Exception as error:
                            if getattr(error, "status_code", None) == 402:
                                raise StopExecution("HTTP 402: service budget exhausted; stopped without retrying.") from error
                            if self.committing:
                                return self.report(False, f"Processing interrupted: {error}")
                            output = {"error": str(error), "warning": "No automatic retry; correct the plan before committing."}
                        conversation.append({"type": "function_call_output", "call_id": call.call_id, "output": json.dumps(output, ensure_ascii=False)})
                raise StopExecution("Investigation turn limit reached before a safe plan was ready; no writes were started.")
            finally:
                await client.close()


async def main():
    agent = BatchAgent()
    try:
        payload = json.load(sys.stdin)
        instruction = payload.get("instruction", payload.get("inputs", {}).get("instruction"))
        if not isinstance(instruction, str) or not instruction.strip():
            raise ValueError("A nonempty daily instruction is required")
        result = await agent.execute(instruction)
    except Exception as error:
        result = agent.report(False, f"Stopped: {type(error).__name__}: {error}")
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    asyncio.run(main())

import asyncio
import json
import re
import sys
import time
from decimal import Decimal, localcontext
from pathlib import Path

from ap_runtime import app_call, definitions, dump, model_client, output_dir, readonly


def exact_total(amounts):
    numbers = []
    for original in amounts:
        amount = original.strip()
        amount = re.sub(r"^(?:USD\s*|\$\s*)", "", amount)
        amount = re.sub(r"\s*USD$", "", amount).strip()
        negative = amount.startswith("(") and amount.endswith(")")
        if negative:
            amount = amount[1:-1]
        if not re.fullmatch(r"[+-]?(?:[0-9]+|[0-9]{1,3}(?:,[0-9]{3})+)(?:\.[0-9]+)?", amount):
            raise ValueError("Ambiguous/non-USD amount; do not guess: " + original)
        number = Decimal(amount.replace(",", ""))
        numbers.append(-number if negative else number)
    with localcontext() as context:
        context.prec = max(80, sum(len(str(number)) for number in numbers) + 20)
        total = sum(numbers, Decimal("0.00"))
    return {"total": format(total, "f"), "reported_total": "$" + format(total, "f"), "amounts": amounts}


LOCAL_TOOLS = [
    {"type": "function", "name": "exact_total", "description": "Sum source USD amount strings using Decimal without rounding. Only supply confirmed newly logged amounts.", "parameters": {"type": "object", "properties": {"amounts": {"type": "array", "items": {"type": "string"}}}, "required": ["amounts"], "additionalProperties": False}},
    {"type": "function", "name": "finish_run", "description": "Finish with the actual human report ending in required JSON, plus read-only API verification requests covering all claimed changes.", "parameters": {"type": "object", "properties": {"report": {"type": "string"}, "audit": {"type": "array", "items": {"type": "object", "properties": {"description": {"type": "string"}, "tool_name": {"type": "string"}, "arguments": {"type": "object", "additionalProperties": True}, "expected": {"type": "string"}}, "required": ["description", "tool_name", "arguments", "expected"]}}}, "required": ["report", "audit"], "additionalProperties": False}, "strict": False},
]


def validate_finish(arguments, allowed):
    report = arguments["report"]
    matches = list(re.finditer(r"```(?:json)?\s*(\{.*?\})\s*```\s*$", report, re.DOTALL))
    if not matches:
        raise ValueError("End report with the required fenced JSON block")
    ledger = json.loads(matches[-1].group(1))
    if set(ledger) != {"logged", "not_logged", "logged_total", "status"}:
        raise ValueError("Incorrect final JSON keys")
    if ledger["status"] not in ("complete", "incomplete"):
        raise ValueError("Invalid status")
    total = exact_total([item["amount"] for item in ledger["logged"]])["total"]
    if ledger["logged_total"]:
        claimed = ledger["logged_total"].replace("$", "").replace(",", "")
        if Decimal(claimed) != Decimal(total):
            raise ValueError("Final total does not equal logged invoice amounts")
    elif ledger["status"] == "complete":
        raise ValueError("Complete requires a sent summary and reported total")
    for check in arguments["audit"]:
        if check["tool_name"] not in allowed or "api_fetch" not in check["tool_name"].lower() or not readonly(check["arguments"]):
            raise ValueError("Audit must use api_fetch with explicit GET read requests")
    if ledger["status"] == "complete" and not arguments["audit"]:
        raise ValueError("Complete requires persisted-effect verification")
    return {"report": report, "audit": dump(arguments["audit"])}


async def main():
    supplied = json.load(sys.stdin)
    tools = definitions()
    allowed = {item["name"] for item in tools}
    prompt = Path(__file__).with_name("ap_prompt.txt").read_text()
    conversation = [{"role": "system", "content": prompt}, {"role": "user", "content": supplied["instruction"]}]
    started = time.monotonic()
    calls = 0
    final = None
    failure = "Execution did not reach a confirmed final report."
    client = model_client()
    try:
        for turn in range(40):
            if time.monotonic() - started > 460 or calls >= 85 or turn == 37:
                conversation.append({"role": "user", "content": "Execution budget is nearly exhausted. Finish necessary readbacks and finish_run now. Report partial results as incomplete; do not start new optional work."})
            response = await client.responses.create(
                model=__import__("os").environ["TASK_MODEL_NAME"],
                input=conversation, tools=tools + LOCAL_TOOLS,
                store=False, include=["reasoning.encrypted_content"],
            )
            conversation.extend(item.model_dump(exclude_none=True) for item in response.output)
            requests = [item for item in response.output if item.type == "function_call"]
            if not requests:
                conversation.append({"role": "user", "content": "Use finish_run to submit your final report and readback audit. Do not stop with a plan or unsupported claims."})
                continue
            for request in requests:
                try:
                    arguments = json.loads(request.arguments)
                    if request.name == "finish_run":
                        final = validate_finish(arguments, allowed)
                        result = {"accepted": True}
                    elif request.name == "exact_total":
                        result = exact_total(arguments["amounts"])
                    elif request.name in allowed:
                        if calls >= 88:
                            raise ValueError("App call budget exhausted; finish incomplete")
                        calls += 1
                        result = await app_call(request.name, arguments)
                    else:
                        raise ValueError("Unknown tool")
                except Exception as error:
                    if getattr(error, "status_code", None) == 402 or getattr(getattr(error, "response", None), "status_code", None) == 402:
                        raise
                    result = {"error": str(error), "warning": "Do not assume a write failed without checking its persisted effect."}
                conversation.append({"type": "function_call_output", "call_id": request.call_id, "output": result if isinstance(result, str) else dump(result)})
                if final is not None:
                    break
            output_dir().joinpath("conversation.json").write_text(dump(conversation))
            if final is not None:
                break
    except Exception as error:
        failure = str(error)
    finally:
        await client.close()
    if final is None:
        final = {"report": "AP processing is incomplete: " + failure + " Some actions may have persisted; inspect the run trace and live records before retrying. No complete ledger or reported total could be verified.\n\n```json\n" + dump({"logged": [], "not_logged": [], "logged_total": "", "status": "incomplete"}) + "\n```", "audit": "[]"}
    print(dump(final))


if __name__ == "__main__":
    asyncio.run(main())

import asyncio
import base64
import json
import os
import re
import sys
import time
from decimal import Decimal, localcontext
from email.message import EmailMessage
from email.policy import SMTP
from pathlib import Path

import httpx
from openai import AsyncOpenAI


class BudgetStop(Exception):
    pass


def decimal_total(amounts):
    parsed = []
    precision = 2
    for original in amounts:
        value = original.strip()
        value = re.sub(r'^(?:USD\s*|\$\s*)', '', value, flags=re.I)
        value = re.sub(r'\s*USD$', '', value, flags=re.I)
        negative = value.startswith('(') and value.endswith(')')
        if negative:
            value = value[1:-1]
        if not re.fullmatch(r'[+-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?', value):
            raise ValueError('Ambiguous or non-USD amount: ' + original)
        number = Decimal(value.replace(',', ''))
        if negative:
            number = -number
        precision = max(precision, -number.as_tuple().exponent)
        parsed.append(number)
    with localcontext() as context:
        context.prec = max(80, sum(len(str(number)) for number in parsed) + 10)
        total = sum(parsed, Decimal(0))
        return format(total, f'.{precision}f')


def searchable(value):
    fragments = []
    def visit(item):
        if isinstance(item, dict):
            for child in item.values():
                visit(child)
        elif isinstance(item, list):
            for child in item:
                visit(child)
        else:
            text = str(item)
            fragments.append(text)
            try:
                decoded = json.loads(text)
                if isinstance(decoded, (dict, list)):
                    visit(decoded)
            except (ValueError, TypeError):
                pass
            if len(text) >= 16 and re.fullmatch(r'[A-Za-z0-9_+/=-]+', text):
                try:
                    decoded = base64.urlsafe_b64decode(text + '=' * (-len(text) % 4)).decode('utf-8')
                    fragments.append(decoded)
                except (ValueError, UnicodeError):
                    pass
    visit(value)
    return '\n'.join(fragments)


def function(name, description, properties, required):
    return {'type': 'function', 'name': name, 'description': description,
            'parameters': {'type': 'object', 'properties': properties,
                           'required': required, 'additionalProperties': False},
            'strict': False}


TEXT = {'type': 'string'}
STRINGS = {'type': 'array', 'items': TEXT}
LOCAL_TOOLS = [
    function('exact_total', 'Sum exact USD source amount strings using decimal arithmetic without rounding.',
             {'amounts': STRINGS}, ['amounts']),
    function('compose_email', 'Build safe plain-text MIME email, returning raw_text for the supplied base64_encode tool. Also returns base64url. Does not send.',
             {'to': TEXT, 'subject': TEXT, 'body': TEXT, 'in_reply_to': TEXT}, ['to', 'subject', 'body']),
    function('verify_effect', 'Independently read a changed destination using api_fetch. Pass its complete arguments as arguments_json. Records exact-value matches; inspect returned placement/context too. READ operations only. One verification per invoice, return, or summary.',
             {'kind': {'type': 'string', 'enum': ['invoice', 'return', 'summary']},
              'invoice': TEXT, 'amount': TEXT, 'arguments_json': TEXT, 'expected_values': STRINGS},
             ['kind', 'invoice', 'arguments_json', 'expected_values']),
    function('finish_report', 'End with actual verified outcomes. Renders narrative and required final JSON. Logged invoices require independent read-back; complete requires a verified summary.',
             {'narrative': TEXT, 'logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': TEXT, 'amount': TEXT}, 'required': ['invoice', 'amount'], 'additionalProperties': False}},
              'not_logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': TEXT, 'reason': TEXT}, 'required': ['invoice', 'reason'], 'additionalProperties': False}},
              'logged_total': TEXT, 'status': {'type': 'string', 'enum': ['complete', 'incomplete']},
              'required_returns': STRINGS,
              'unconfirmed_actions': STRINGS},
             ['narrative', 'logged', 'not_logged', 'logged_total', 'status', 'required_returns', 'unconfirmed_actions'])
]


def load_tools():
    source = json.loads(Path('/run-input/tools.json').read_text())
    if isinstance(source, dict):
        source = source.get('tools', source)
    if isinstance(source, dict):
        source = [dict(value, name=key) for key, value in source.items()]
    tools = []
    for item in source:
        definition = item.get('function', item)
        name = definition.get('name', '')
        if not any(term in name for term in ('api_search', 'api_fetch', 'base64_encode')):
            continue
        if item.get('type') == 'custom':
            tools.append(item)
        else:
            tools.append({'type': 'function', 'name': name,
                          'description': definition.get('description', ''),
                          'parameters': definition.get('parameters', definition.get('input_schema', definition.get('inputSchema', {'type': 'object', 'properties': {}}))),
                          'strict': False})
    if not any('api_fetch' in tool['name'] for tool in tools):
        raise ValueError('No supplied api_fetch tool definition found')
    return tools


class Agent:
    def __init__(self, instruction):
        self.instruction = instruction
        self.evidence = []
        self.calls = 0
        self.finished = None
        self.started = time.monotonic()
        self.log_dir = Path(os.environ.get('METHOD_OUTPUT_DIR', '/tmp/ap-run'))
        self.log_dir.mkdir(parents=True, exist_ok=True)
        self.http = httpx.AsyncClient(timeout=45)
        self.remote_tools = load_tools()
        self.fetch_name = next(tool['name'] for tool in self.remote_tools if 'api_fetch' in tool['name'])

    def record(self, value):
        with (self.log_dir / 'ap-audit.jsonl').open('a') as handle:
            handle.write(json.dumps(value, ensure_ascii=False) + '\n')

    async def bridge(self, name, arguments):
        if self.calls >= 90:
            raise BudgetStop('Simulated tool-call limit reached')
        self.calls += 1
        response = await self.http.post(os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call',
                                        headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN']},
                                        json={'name': name, 'arguments': arguments})
        if response.status_code == 402:
            raise BudgetStop('Service budget exhausted (HTTP 402)')
        response.raise_for_status()
        result = response.json().get('result', response.text)
        self.record({'tool': name, 'arguments': arguments, 'result': result})
        return result

    async def tool(self, name, arguments):
        if name == 'exact_total':
            total = decimal_total(arguments['amounts'])
            return {'total': total, 'dollars': '$' + total}
        if name == 'compose_email':
            message = EmailMessage(policy=SMTP)
            message['From'] = 'ap@company.example.com'
            message['To'] = arguments['to']
            message['Subject'] = arguments['subject']
            if arguments.get('in_reply_to'):
                message['In-Reply-To'] = arguments['in_reply_to']
                message['References'] = arguments['in_reply_to']
            message.set_content(arguments['body'], cte='8bit')
            raw = message.as_bytes()
            return {'raw_text': raw.decode('utf-8'), 'base64url': base64.urlsafe_b64encode(raw).decode().rstrip('=')}
        if name == 'verify_effect':
            read_arguments = json.loads(arguments['arguments_json'])
            serialized = json.dumps(read_arguments).lower()
            if re.search(r'"method"\s*:\s*"(?:post|put|patch|delete)"', serialized):
                return {'error': 'Verification requires an independent read, not a write'}
            observation = await self.bridge(self.fetch_name, read_arguments)
            haystack = searchable(observation)
            missing = [value for value in arguments['expected_values'] if value not in haystack]
            passed = bool(arguments['expected_values']) and not missing
            proof = dict(arguments, confirmed=passed, observation=observation)
            self.evidence.append(proof)
            self.record({'verification': proof})
            return {'confirmed': passed, 'missing': missing, 'observation': observation}
        if name == 'finish_report':
            claimed = arguments['logged']
            for item in claimed:
                if not any(proof['confirmed'] and proof['kind'] == 'invoice' and proof['invoice'] == item['invoice']
                           and all(value in proof['expected_values'] for value in (item['invoice'], item['amount'])) for proof in self.evidence):
                    return {'error': 'Logged invoice lacks independent verification', 'invoice': item['invoice']}
            expected_total = '$' + decimal_total([item['amount'] for item in claimed])
            if arguments['logged_total'] and arguments['logged_total'] != expected_total:
                return {'error': 'Reported total must equal verified logged amounts', 'expected': expected_total}
            summary_verified = any(proof['confirmed'] and proof['kind'] == 'summary'
                                   and 'ap-lead@company.example.com' in searchable(proof['observation'])
                                   and 'Logged total: ' + expected_total in searchable(proof['observation']) for proof in self.evidence)
            if arguments['status'] == 'complete' and (arguments['unconfirmed_actions'] or not summary_verified or not arguments['logged_total']):
                return {'error': 'Complete requires verified summary and no unresolved actions'}
            payload = {key: arguments[key] for key in ('logged', 'not_logged', 'logged_total', 'status')}
            for invoice in arguments['required_returns']:
                if arguments['status'] == 'complete' and not any(proof['confirmed'] and proof['kind'] == 'return' and proof['invoice'] == invoice for proof in self.evidence):
                    return {'error': 'Required return lacks independent verification', 'invoice': invoice}
            report = arguments['narrative'].rstrip() + '\n\n```json\n' + json.dumps(payload, ensure_ascii=False, indent=2) + '\n```'
            self.finished = {'report': report, 'verification': json.dumps({'payload': payload, 'evidence': self.evidence, 'required_returns': arguments['required_returns'], 'unconfirmed_actions': arguments['unconfirmed_actions']}, ensure_ascii=False)}
            self.record({'final': payload, 'unconfirmed_actions': arguments['unconfirmed_actions']})
            return {'finished': True}
        return await self.bridge(name, arguments)

    async def run(self):
        client = AsyncOpenAI(api_key=os.environ['TASK_MODEL_API_KEY'], base_url=os.environ['TASK_MODEL_API_BASE'], max_retries=0, timeout=100)
        history = [{'role': 'developer', 'content': Path(__file__).with_name('ap_instructions.txt').read_text()},
                   {'role': 'user', 'content': self.instruction}]
        try:
            for turn in range(42):
                if time.monotonic() - self.started > 510:
                    raise BudgetStop('Execution time limit approaching')
                response = await client.responses.create(model=os.environ['TASK_MODEL_NAME'], input=history,
                                                          tools=self.remote_tools + LOCAL_TOOLS,
                                                          store=False, include=['reasoning.encrypted_content'])
                dumped = [item.model_dump(exclude_none=True) for item in response.output]
                history.extend(dumped)
                self.record({'model_turn': turn, 'output': dumped})
                calls = [item for item in response.output if item.type in ('function_call', 'custom_tool_call')]
                for call in calls:
                    try:
                        arguments = json.loads(call.arguments) if call.type == 'function_call' else call.input
                        result = await self.tool(call.name, arguments)
                    except BudgetStop:
                        raise
                    except Exception as error:
                        if getattr(error, 'status_code', None) == 402:
                            raise BudgetStop('Service budget exhausted (HTTP 402)')
                        result = {'error': str(error), 'guidance': 'If a write may have happened, read the destination before retrying.'}
                    history.append({'type': 'function_call_output' if call.type == 'function_call' else 'custom_tool_call_output',
                                    'call_id': call.call_id, 'output': json.dumps(result, ensure_ascii=False)})
                    if self.finished:
                        return self.finished
                if not calls:
                    history.append({'role': 'user', 'content': 'Complete the actual task and call finish_report with verified outcomes. If blocked, call finish_report with an honest incomplete report.'})
                if turn == 33 or self.calls >= 75:
                    history.append({'role': 'developer', 'content': 'Resources are running low. Prioritize read-backs, summary, and finish_report; avoid unnecessary research.'})
            raise BudgetStop('Model turn limit reached')
        except Exception as error:
            self.record({'stopped': str(error)})
            logged = []
            for proof in self.evidence:
                if proof['confirmed'] and proof['kind'] == 'invoice' and proof.get('amount'):
                    item = {'invoice': proof['invoice'], 'amount': proof['amount']}
                    if item not in logged:
                        logged.append(item)
            report = 'Processing stopped before completion: ' + str(error) + '. The JSON lists independently verified rows only. Other changes may have occurred; inspect destinations before retrying.'
            total = '$' + decimal_total([item['amount'] for item in logged])
            reported = total if any(proof['confirmed'] and proof['kind'] == 'summary' and 'Logged total: ' + total in searchable(proof['observation']) for proof in self.evidence) else ''
            payload = {'logged': logged, 'not_logged': [], 'logged_total': reported, 'status': 'incomplete'}
            return {'report': report + '\n\n```json\n' + json.dumps(payload, ensure_ascii=False) + '\n```',
                    'verification': json.dumps({'payload': payload, 'evidence': self.evidence, 'required_returns': [], 'unconfirmed_actions': [str(error)]}, ensure_ascii=False)}
        finally:
            if not self.finished:
                self.record({'incomplete_evidence': self.evidence})
            await client.close()
            await self.http.aclose()


async def main():
    data = json.load(sys.stdin)
    agent = Agent(data['instruction'])
    result = await agent.run()
    print(json.dumps(result, ensure_ascii=False))


