class APRunner:
    def __init__(self):
        self.calls = []
        self.evidence = []
        self.final = None
        self.started = time.monotonic()
        self.output = Path(os.environ.get("METHOD_OUTPUT_DIR", "/tmp/ap-run"))
        self.output.mkdir(parents=True, exist_ok=True)

    def save(self):
        (self.output / "ap-audit.json").write_text(compact({"calls": self.calls, "evidence": self.evidence, "final": self.final}))

    async def call_app(self, name, arguments):
        if len(self.calls) >= 95 or time.monotonic() - self.started > 530:
            raise StopRun("Execution limit reached; app calls stopped.")
        token = os.environ["MAC_TERMINAL_TOKEN"]
        url = os.environ["MAC_TERMINAL_URL"].rstrip("/") + "/call"
        record = {"index": len(self.calls), "name": name, "arguments": arguments}
        self.calls.append(record)
        self.save()
        async with httpx.AsyncClient(timeout=45) as client:
            response = await client.post(url, headers={"Authorization": "Bearer " + token}, json={"name": name, "arguments": arguments})
        if response.status_code == 402:
            raise StopRun("Service budget exhausted (HTTP 402).")
        response.raise_for_status()
        result = response.json()
        record["result"] = result.get("result", result)
        record["decoded"] = decode_data(record["result"])
        self.save()
        return {"call_index": record["index"], "result": record["result"]}

    def confirm(self, arguments):
        index = arguments["read_call"]
        if index < 0 or index >= len(self.calls):
            raise ValueError("Unknown read_call.")
        call = self.calls[index]
        if "fetch" not in call["name"].lower():
            raise ValueError("Evidence must be an API fetch read.")
        parameters = call["arguments"]
        method = str(parameters.get("method", parameters.get("http_method", "GET"))).upper()
        if method not in ("GET", "HEAD"):
            raise ValueError("Evidence must be an independent GET read, not a write receipt.")
        if "decoded" not in call:
            raise ValueError("Read did not finish.")
        expected = json.loads(arguments["expected_json"])
        if not expected or not contains(call["decoded"], expected):
            return {"confirmed": False, "error": "Expected content absent from read response", "decoded_read": call["decoded"]}
        receipt = {**arguments, "expected": expected, "evidence_id": len(self.evidence), "confirmed": True}
        self.evidence.append(receipt)
        self.save()
        return receipt

    def finish(self, arguments):
        for entry in arguments["logged"]:
            receipt = self.evidence[entry["evidence_id"]]
            if receipt["kind"] != "invoice" or receipt["key"] != entry["invoice"]:
                raise ValueError("Every logged invoice needs its own invoice evidence.")
            if not contains(receipt["expected"], entry["invoice"]) or not contains(receipt["expected"], entry["amount"]):
                raise ValueError("Evidence must contain exact invoice identifier and amount.")
        total = total_amounts([entry["amount"] for entry in arguments["logged"]])
        if arguments["logged_total"] and arguments["logged_total"] != total["total"]:
            raise ValueError("Reported total must equal confirmed new rows: " + total["total"])
        if arguments["status"] == "complete":
            if not arguments["logged_total"]:
                raise ValueError("Complete requires a sent summary total.")
            summaries = [receipt for receipt in self.evidence if receipt["kind"] == "summary"]
            if not any(contains(receipt["expected"], total["summary_line"]) for receipt in summaries):
                raise ValueError("Read back sent summary and confirm exact Logged total line.")
            returned = {receipt["key"] for receipt in self.evidence if receipt["kind"] == "return"}
            if not set(arguments["required_returns"]).issubset(returned):
                raise ValueError("All blocked invoice returns must be confirmed.")
        ledger = {"logged": [{"invoice": entry["invoice"], "amount": entry["amount"]} for entry in arguments["logged"]],
                  "not_logged": arguments["not_logged"], "logged_total": arguments["logged_total"], "status": arguments["status"]}
        report = arguments["description"].rstrip() + "\n\n```json\n" + compact(ledger) + "\n```"
        self.final = {"report": report, "ledger": ledger, "finalized": True, "evidence": self.evidence}
        self.save()
        return {"finalized": True}

    async def dispatch(self, name, arguments):
        if name == "deliver_email":
            return await self.deliver_email(arguments)
        if name == "simulated_call":
            return await self.call_app(arguments["name"], json.loads(arguments["arguments"]))
        if name == "exact_total":
            return total_amounts(arguments["amounts"])
        if name == "confirm_effect":
            return self.confirm(arguments)
        if name == "finish_ap":
            return self.finish(arguments)
        raise ValueError("Unknown local tool")

    async def deliver_email(self, arguments):
        if arguments["kind"] == "summary" and arguments["to"] != "ap-lead@company.example.com":
            raise ValueError("Summary recipient must be the AP lead.")
        if any(character in arguments["to"] + arguments["subject"] for character in "\r\n"):
            raise ValueError("Email headers cannot contain line breaks.")
        encoded = await self.call_app("base64_encode", {"text": arguments["body"]})
        encoded_text = encoded["result"].strip().strip('"')
        if base64.urlsafe_b64decode(encoded_text + "=" * (-len(encoded_text) % 4)).decode() != arguments["body"]:
            raise ValueError("Encoding result did not preserve email body.")
        payload = {"payload": {"mimeType": "text/plain", "headers": [
            {"name": "From", "value": "ap@company.example.com"},
            {"name": "To", "value": arguments["to"]},
            {"name": "Subject", "value": arguments["subject"]}],
            "body": {"data": encoded_text}}}
        if arguments["thread_id"]:
            payload["threadId"] = arguments["thread_id"]
        sent = await self.call_app("api_fetch", {"method": "POST", "url": arguments["send_url"], "params": None, "body": compact(payload)})
        sent_data = decode_data(sent["result"])
        if not isinstance(sent_data, dict) or not sent_data.get("id"):
            return {"unconfirmed": True, "sent_response": sent, "recovery": "Search sent mail before any retry; delivery may have happened."}
        read = await self.call_app("api_fetch", {"method": "GET", "url": arguments["read_url_template"].replace("{id}", sent_data["id"]), "params": compact({"format": "full"}), "body": None})
        actual = self.calls[read["call_index"]]["decoded"]
        if not contains(actual, arguments["to"]) or not contains(actual, arguments["body"]):
            return {"unconfirmed": True, "message_id": sent_data["id"], "read": read, "recovery": "Readback did not match recipient and full body; inspect before retrying."}
        receipt = {"kind": arguments["kind"], "key": arguments["key"], "read_call": read["call_index"],
                   "expected": {"recipient": arguments["to"], "body": arguments["body"]},
                   "description": "Sent and read back email to " + arguments["to"],
                   "evidence_id": len(self.evidence), "confirmed": True, "message_id": sent_data["id"]}
        self.evidence.append(receipt)
        self.save()
        return receipt

    def fallback(self, reason):
        logged = []
        for receipt in self.evidence:
            expected = receipt.get("expected")
            if receipt["kind"] == "invoice" and isinstance(expected, list) and len(expected) >= 4:
                if expected[1] == receipt["key"] and isinstance(expected[3], str):
                    entry = {"invoice": receipt["key"], "amount": expected[3]}
                    if entry not in logged:
                        logged.append(entry)
        reported_total = ""
        for receipt in self.evidence:
            if receipt["kind"] == "summary":
                expected = receipt.get("expected", {})
                body = expected.get("body", "") if isinstance(expected, dict) else str(expected)
                match = re.search(r"(?m)^Logged total: (\$[^\r\n]+)$", body)
                if match:
                    reported_total = match.group(1)
        ledger = {"logged": logged, "not_logged": [], "logged_total": reported_total, "status": "incomplete"}
        details = "\n".join("- Confirmed " + receipt["kind"] + ": " + receipt["key"] + " — " + receipt["description"] for receipt in self.evidence)
        report = ("AP processing is incomplete: " + reason + "\n" + details +
                  "\nFinal ledger is partial. Only recoverable confirmed rows are listed; other writes may have occurred. Review app records before rerunning.\n\n```json\n" + compact(ledger) + "\n```")
        self.final = {"report": report, "ledger": ledger, "finalized": False, "evidence": self.evidence, "failure": reason}
        self.save()

    async def run(self, instruction):
        definitions = Path("/run-input/tools.json").read_text()
        prompt = Path(__file__).with_name("ap_prompt.txt").read_text()
        conversation = [{"role": "system", "content": prompt + "\n\nORIGINAL SIMULATED TOOL DEFINITIONS:\n" + definitions},
                        {"role": "user", "content": instruction}]
        client = AsyncOpenAI(base_url=os.environ["TASK_MODEL_API_BASE"], api_key=os.environ["TASK_MODEL_API_KEY"], max_retries=0, timeout=110)
        try:
            for turn in range(44):
                if time.monotonic() - self.started > 545:
                    raise StopRun("Time limit reached before reconciliation.")
                if time.monotonic() - self.started > 360:
                    conversation.append({"role": "user", "content": "Time remaining is limited. Stop optional research. Prioritize required messages and finalization now; use deliver_email and report remaining gaps honestly."})
                if turn in (28, 36, 41):
                    conversation.append({"role": "user", "content": str(44-turn) + " turns remain. Finish required actions and readbacks, then finish_ap. Report unresolved work as incomplete."})
                remaining = max(1, 550 - (time.monotonic() - self.started))
                response = await asyncio.wait_for(client.responses.create(model=os.environ["TASK_MODEL_NAME"], input=conversation, tools=TOOLS, store=False, include=["reasoning.encrypted_content"]), timeout=remaining)
                conversation.extend(item.model_dump(exclude_none=True) for item in response.output)
                (self.output / "conversation.json").write_text(compact(conversation))
                calls = [item for item in response.output if item.type == "function_call"]
                if not calls:
                    conversation.append({"role": "user", "content": "Finalize with finish_ap using actual confirmed actions and unresolved items. Text alone does not finalize."})
                    continue
                for call in calls:
                    try:
                        result = await self.dispatch(call.name, json.loads(call.arguments))
                    except StopRun:
                        raise
                    except Exception as error:
                        result = {"error": type(error).__name__ + ": " + str(error), "recovery": "Inspect app state before repeating any possibly committed write."}
                    conversation.append({"type": "function_call_output", "call_id": call.call_id, "output": compact(result)})
                if self.final:
                    break
            if not self.final:
                self.fallback("Model turn limit reached.")
        except Exception as error:
            self.fallback(type(error).__name__ + ": " + str(error))
        finally:
            await client.close()
        return {"report": self.final["report"], "audit": compact(self.final)}


async def main():
    data = json.load(sys.stdin)
    runner = APRunner()
    try:
        result = await runner.run(data["instruction"])
    except Exception as error:
        runner.fallback(type(error).__name__ + ": " + str(error))
        result = {"report": runner.final["report"], "audit": compact(runner.final)}
    print(compact(result))


if __name__ == "__main__":
    asyncio.run(main())

