def resolve_due_date(source, weekend_to_monday):
    if not weekend_to_monday:
        return {"source_due_date": source, "due_date": source, "adjusted": False}
    formats = ["%Y-%m-%d", "%B %d, %Y", "%b %d, %Y", "%m/%d/%Y"]
    for date_format in formats:
        try:
            parsed = datetime.strptime(source, date_format)
        except ValueError:
            continue
        if parsed.weekday() < 5:
            return {"source_due_date": source, "due_date": source, "adjusted": False}
        adjusted = parsed + timedelta(days=7 - parsed.weekday())
        rendered = adjusted.strftime(date_format)
        if date_format in ("%B %d, %Y", "%b %d, %Y"):
            rendered = rendered.replace(" 0", " ", 1)
        return {"source_due_date": source, "due_date": rendered, "adjusted": True}
    raise ValueError("Unrecognized due date; resolve from source without guessing: " + source)


