COMPLETION_TOOL = function(
    "complete_day",
    "Execute the entire reconciled AP plan without further model turns: append eligible invoices once, read back rows, return blocked invoices, send the exact-total summary even on partial failure, and generate the final report. Call once after research, BEFORE any writes. All URLs must come from discovered endpoints.",
    {
        "invoices": {"type": "array", "items": {"type": "object", "properties": {
            "invoice": {"type": "string"},
            "amount": {"type": "string"},
            "row": {"type": "array", "items": {"type": "string"}},
            "decision": {"type": "string", "enum": ["eligible", "blocked", "duplicate", "unresolved"]},
            "reason": {"type": "string", "description": "Policy basis, exact corrections/review flags, or reason for exclusion."},
