        }, "required": ["invoice", "amount", "row", "decision", "reason", "return_to", "return_body", "thread_id"], "additionalProperties": False}},
        "headers": {"type": "array", "items": {"type": "string"}, "description": "Actual sheet headers in order; row values must match these columns, including Notes."},
        "invoice_column": {"type": "integer", "description": "Zero-based invoice-number column."},
        "vendor_column": {"type": "integer", "description": "Zero-based vendor-name column."},
        "sheet_range": {"type": "string", "description": "Full Pending Invoices range in A1 notation, e.g. 'Pending Invoices'!A:F."},
