)
RESEARCH_TOOLS = [tool for tool in TOOLS if tool["name"] in ("resolve_due_date", "simulated_call")] + [COMPLETION_TOOL]


def sheet_rows(value):
    if not isinstance(value, dict):
        raise ValueError("Spreadsheet read did not return a values object.")
    if "valueRanges" in value:
        if len(value["valueRanges"]) != 1:
            raise ValueError("Read exactly one range: all Pending Invoices rows.")
        return sheet_rows(value["valueRanges"][0])
    if "values" in value:
        return value["values"]
    if "range" in value and "error" not in value:
        return []
    raise ValueError("Spreadsheet read failed: " + compact(value))


class APRunner:
    def __init__(self):
        self.calls = []
        self.evidence = []
        self.invoices = {}
        self.final = None
        self.completion_started = False
        self.delivery_attempts = []
        self.started = time.monotonic()
        self.output = Path(os.environ.get("METHOD_OUTPUT_DIR", "/tmp/ap-run"))
        self.output.mkdir(parents=True, exist_ok=True)

    def save(self):
        (self.output / "ap-audit.json").write_text(compact({"calls": self.calls, "evidence": self.evidence, "invoices": self.invoices, "deliveries": self.delivery_attempts, "final": self.final}))

    async def call_app(self, name, arguments):
        if len(self.calls) >= 95 or time.monotonic() - self.started > 530:
            raise StopRun("Execution limit reached; app calls stopped.")
        token = os.environ["MAC_TERMINAL_TOKEN"]
        url = os.environ["MAC_TERMINAL_URL"].rstrip("/") + "/call"
        record = {"index": len(self.calls), "name": name, "arguments": arguments}
        self.calls.append(record)
        self.save()
        async with httpx.AsyncClient(timeout=45) as client:
            response = await client.post(url, headers={"Authorization": "Bearer " + token}, json={"name": name, "arguments": arguments})
        if response.status_code == 402:
            raise StopRun("Service budget exhausted (HTTP 402).")
        response.raise_for_status()
        result = response.json()
        record["result"] = result.get("result", result)
        record["decoded"] = decode_data(record["result"])
        self.save()
        return {"call_index": record["index"], "result": record["result"]}

    def confirm(self, arguments):
        index = arguments["read_call"]
        if index < 0 or index >= len(self.calls):
            raise ValueError("Unknown read_call.")
        call = self.calls[index]
        if "fetch" not in call["name"].lower():
            raise ValueError("Evidence must be an API fetch read.")
        parameters = call["arguments"]
        method = str(parameters.get("method", parameters.get("http_method", "GET"))).upper()
        if method not in ("GET", "HEAD"):
            raise ValueError("Evidence must be an independent GET read, not a write receipt.")
        if "decoded" not in call:
            raise ValueError("Read did not finish.")
        expected = json.loads(arguments["expected_json"])
        if arguments["kind"] == "invoice":
            planned = self.invoices.get(arguments["key"])
            if not planned or planned["decision"] not in ("eligible", "failed"):
                raise ValueError("Checkpoint the eligible invoice and its intended row before confirming.")
            if expected != planned["row"]:
                raise ValueError("Readback must match the entire intended row, including the policy-adjusted Due Date and Notes. Fix the sheet, not the intended values.")
        if not expected or not contains(call["decoded"], expected):
            return {"confirmed": False, "error": "Expected content absent from read response", "decoded_read": call["decoded"]}
        receipt = {**arguments, "expected": expected, "evidence_id": len(self.evidence), "confirmed": True}
        self.evidence.append(receipt)
        self.save()
        return receipt

    def finish(self, arguments):
        for entry in arguments["logged"]:
            receipt = self.evidence[entry["evidence_id"]]
            if receipt["kind"] != "invoice" or receipt["key"] != entry["invoice"]:
                raise ValueError("Every logged invoice needs its own invoice evidence.")
            if not contains(receipt["expected"], entry["invoice"]) or not contains(receipt["expected"], entry["amount"]):
                raise ValueError("Evidence must contain exact invoice identifier and amount.")
            if entry["amount"] != self.invoices[entry["invoice"]]["amount"]:
                raise ValueError("Logged amount must match the checkpoint and confirmed row.")
        logged_keys = {entry["invoice"] for entry in arguments["logged"]}
        confirmed_keys = {receipt["key"] for receipt in self.evidence if receipt["kind"] == "invoice"}
        if logged_keys != confirmed_keys or len(logged_keys) != len(arguments["logged"]):
            raise ValueError("Report every confirmed new invoice exactly once.")
        excluded_keys = {entry["invoice"] for entry in arguments["not_logged"]}
        if logged_keys & excluded_keys or set(self.invoices) != logged_keys | excluded_keys:
            raise ValueError("Report each checkpointed invoice exactly once as logged or not_logged.")
        total = total_amounts([entry["amount"] for entry in arguments["logged"]])
        if arguments["logged_total"] and arguments["logged_total"] != total["total"]:
            raise ValueError("Reported total must equal confirmed new rows: " + total["total"])
        if arguments["status"] == "complete":
            if any(item["decision"] in ("eligible", "failed", "unresolved") and key not in logged_keys for key, item in self.invoices.items()):
                raise ValueError("Unresolved or failed eligible invoices require incomplete status.")
            if not arguments["logged_total"]:
                raise ValueError("Complete requires a sent summary total.")
            summaries = [receipt for receipt in self.evidence if receipt["kind"] == "summary"]
            if not any(contains(receipt["expected"], total["summary_line"]) for receipt in summaries):
                raise ValueError("Read back sent summary and confirm exact Logged total line.")
            returned = {receipt["key"] for receipt in self.evidence if receipt["kind"] == "return"}
            required_returns = set(arguments["required_returns"]) | {key for key, item in self.invoices.items() if item["decision"] == "blocked"}
            if not required_returns.issubset(returned):
                raise ValueError("All blocked invoice returns must be confirmed.")
        ledger = {"logged": [{"invoice": entry["invoice"], "amount": entry["amount"]} for entry in arguments["logged"]],
                  "not_logged": arguments["not_logged"], "logged_total": arguments["logged_total"], "status": arguments["status"]}
        report = arguments["description"].rstrip() + "\n\n```json\n" + compact(ledger) + "\n```"
        self.final = {"report": report, "ledger": ledger, "finalized": True, "evidence": self.evidence}
        self.save()
        return {"finalized": True}

    async def dispatch(self, name, arguments):
        if name == "complete_day":
            return await self.complete_day(arguments)
        if name == "resolve_due_date":
            return resolve_due_date(**arguments)
        if name == "checkpoint_invoices":
            for entry in arguments["invoices"]:
                if entry["decision"] == "eligible" and (len(entry["row"]) < 5 or entry["invoice"] not in entry["row"] or entry["amount"] not in entry["row"]):
                    raise ValueError("Eligible invoice needs all five fields in its intended row.")
                self.invoices[entry["invoice"]] = entry
            self.save()
            return {"checkpointed": list(self.invoices)}
        if name == "deliver_email":
            return await self.deliver_email(arguments)
        if name == "simulated_call":
            parameters = json.loads(arguments["arguments"])
            if "fetch" in arguments["name"].lower() and str(parameters.get("method", "GET")).upper() not in ("GET", "HEAD"):
                raise ValueError("Research is read-only. Submit all invoice decisions to complete_day for writes and guaranteed reporting.")
            return await self.call_app(arguments["name"], parameters)
        if name == "exact_total":
            return total_amounts(arguments["amounts"])
        if name == "confirm_effect":
            return self.confirm(arguments)
        if name == "finish_ap":
            return self.finish(arguments)
        raise ValueError("Unknown local tool")

    async def complete_day(self, plan):
        if self.completion_started:
            raise ValueError("Completion already started; never replay writes. Inspect the saved audit.")
        if len({entry["invoice"] for entry in plan["invoices"]}) != len(plan["invoices"]):
            raise ValueError("Invoice numbers must be unique within the plan; resolve repeated messages first.")
        for column in (plan["invoice_column"], plan["vendor_column"]):
            if not 0 <= column < len(plan["headers"]):
                raise ValueError("Column index outside sheet headers.")
        for entry in plan["invoices"]:
            if entry["decision"] == "eligible":
                if len(entry["row"]) != len(plan["headers"]) or entry["row"][plan["invoice_column"]] != entry["invoice"] or entry["amount"] not in entry["row"]:
                    raise ValueError("Eligible invoice row must match headers and exact invoice/amount: " + entry["invoice"])
                total_amounts([entry["amount"]])
            if entry["decision"] == "blocked" and (not entry["return_to"] or not entry["return_body"]):
                raise ValueError("Blocked invoice needs original sender and policy-based return body.")
        json.loads(plan["read_params"])
        await self.dispatch("checkpoint_invoices", {"invoices": plan["invoices"]})
        self.completion_started = True
        self.save()
        problems = [] if plan["research_complete"] else ["Research is incomplete; some sources or invoices remain unresolved."]
        candidates = []
        try:
            before = await self.read_sheet(plan)
            existing = sheet_rows(self.calls[before["call_index"]]["decoded"])
            for entry in self.invoices.values():
                if entry["decision"] != "eligible":
                    continue
                if any(len(row) > max(plan["invoice_column"], plan["vendor_column"]) and
                       row[plan["invoice_column"]] == entry["invoice"] and
                       row[plan["vendor_column"]] == entry["row"][plan["vendor_column"]] for row in existing):
                    entry.update(decision="duplicate", reason="Already present in Pending Invoices; not appended or counted again.")
                else:
                    candidates.append(entry)
        except StopRun:
            raise
        except Exception as error:
            problems.append("Pre-write sheet read failed; no invoice appends attempted: " + str(error))
        for entry in candidates:
            entry["policy_reason"] = entry["reason"]
            try:
                result = await self.call_app("api_fetch", {"method": "POST", "url": plan["append_url"],
                    "params": compact({"valueInputOption": "RAW", "insertDataOption": "INSERT_ROWS"}),
                    "body": compact({"range": plan["sheet_range"], "majorDimension": "ROWS", "values": [entry["row"]]})})
                decoded = decode_data(result["result"])
                if isinstance(decoded, dict) and (decoded.get("error") or decoded.get("ok") is False):
                    entry.update(decision="failed", reason="Spreadsheet rejected invoice: " + compact(decoded))
            except StopRun:
                raise
            except Exception as error:
                entry.update(decision="failed", reason="Append outcome uncertain: " + str(error))
            self.save()
        if candidates:
            try:
                after = await self.read_sheet(plan)
                sheet_rows(self.calls[after["call_index"]]["decoded"])
                for entry in candidates:
                    receipt = self.confirm({"kind": "invoice", "key": entry["invoice"], "read_call": after["call_index"],
                        "expected_json": compact(entry["row"]), "description": "All intended columns independently read back, including Due Date and Notes."})
                    if receipt["confirmed"]:
                        entry.update(decision="eligible", reason=entry["policy_reason"])
                    if not receipt["confirmed"] and entry["decision"] != "failed":
                        entry.update(decision="failed", reason="Intended row not found in spreadsheet readback; not counted. Inspect before retrying.")
            except StopRun:
                raise
            except Exception as error:
                problems.append("Spreadsheet readback failed: " + str(error))
        for entry in self.invoices.values():
            if entry["decision"] == "blocked":
                try:
                    receipt = await self.deliver_email({"kind": "return", "key": entry["invoice"],
                        "to": entry["return_to"], "subject": "Invoice return — " + entry["invoice"],
                        "body": entry["return_body"], "thread_id": entry["thread_id"],
                        "send_url": plan["send_url"], "read_url_template": plan["read_url_template"]})
                    if not receipt.get("confirmed"):
                        problems.append("Return not confirmed for " + entry["invoice"] + ": " + compact(receipt))
                except StopRun:
                    raise
                except Exception as error:
                    problems.append("Return not confirmed for " + entry["invoice"] + ": " + str(error))
        logged = self.confirmed_invoices()
        logged_keys = {entry["invoice"] for entry in logged}
        not_logged = []
        for key, entry in self.invoices.items():
            if key not in logged_keys:
                reason = entry["reason"] if entry["decision"] != "eligible" else "Logging not confirmed; inspect spreadsheet before retrying."
                not_logged.append({"invoice": key, "reason": reason})
                if entry["decision"] in ("eligible", "failed", "unresolved"):
                    problems.append(key + ": " + reason)
        total = total_amounts([entry["amount"] for entry in logged])["total"]
        status = "incomplete" if problems else "complete"
        lines = ["AP processing for " + plan["date"] + ": " + status + ".", plan["policy_summary"]]
        for entry in logged:
            planned = self.invoices[entry["invoice"]]
            lines.append("Logged and read back: " + "; ".join(header + ": " + value for header, value in zip(plan["headers"], planned["row"])))
            if planned["reason"]:
                lines.append("Decision for " + entry["invoice"] + ": " + planned["reason"])
        for entry in not_logged:
            lines.append("Not logged: " + entry["invoice"] + " — " + entry["reason"])
        for receipt in self.evidence:
            if receipt["kind"] == "return":
                lines.append("Returned " + receipt["key"] + " to " + receipt["expected"]["recipient"] + "; independently read back.")
        lines.extend("Outstanding: " + problem for problem in problems)
        body = "\n".join(line for line in lines if line)
        summary_confirmed = False
        try:
            receipt = await self.deliver_email({"kind": "summary", "key": "summary", "to": "ap-lead@company.example.com",
                "subject": "AP summary " + plan["date"] + " — " + status, "body": body, "thread_id": "",
                "send_url": plan["send_url"], "read_url_template": plan["read_url_template"]})
            summary_confirmed = receipt.get("confirmed", False)
            if not summary_confirmed:
                problems.append("Summary delivery unconfirmed; inspect sent mail before retrying.")
        except StopRun:
            raise
        except Exception as error:
            problems.append("Summary delivery unconfirmed: " + str(error))
        ledger = {"logged": logged, "not_logged": not_logged, "logged_total": total, "status": "incomplete" if problems else "complete"}
        if ledger["status"] != status:
            lines[0] = "AP processing for " + plan["date"] + ": " + ledger["status"] + "."
            body = "\n".join(line for line in lines if line)
        summary_note = "Summary sent to ap-lead@company.example.com and independently read back." if summary_confirmed else "Summary email NOT confirmed. The total below is the confirmed-row total reported here, not a claim of email delivery."
        report = "Logged total: " + total + "\n" + body + "\n" + summary_note
        if not summary_confirmed:
            report += "\n" + "\n".join(problems)
        self.final = {"report": report + "\n\n```json\n" + compact(ledger) + "\n```",
                      "ledger": ledger, "finalized": True, "evidence": self.evidence}
        self.save()
        return {"finalized": True, "logged_total": total, "status": ledger["status"]}

    async def read_sheet(self, plan):
        return await self.call_app("api_fetch", {"method": "GET", "url": plan["read_url"], "params": plan["read_params"], "body": None})

    async def deliver_email(self, arguments):
        if arguments["kind"] == "summary" and arguments["to"] != "ap-lead@company.example.com":
            raise ValueError("Summary recipient must be the AP lead.")
        if arguments["kind"] == "summary":
            total = total_amounts([entry["amount"] for entry in self.confirmed_invoices()])
            body = re.sub(r"(?m)^Logged total: [^\r\n]*(?:\r?\n)?", "", arguments["body"]).strip()
            arguments = {**arguments, "body": total["summary_line"] + "\n\n" + body}
        if any(character in arguments["to"] + arguments["subject"] for character in "\r\n"):
            raise ValueError("Email headers cannot contain line breaks.")
        encoded = await self.call_app("base64_encode", {"text": arguments["body"]})
        encoded_text = encoded["result"].strip().strip('"')
        if base64.urlsafe_b64decode(encoded_text + "=" * (-len(encoded_text) % 4)).decode() != arguments["body"]:
            raise ValueError("Encoding result did not preserve email body.")
        payload = {"payload": {"mimeType": "text/plain", "headers": [
            {"name": "From", "value": "ap@company.example.com"},
            {"name": "To", "value": arguments["to"]},
            {"name": "Subject", "value": arguments["subject"]}],
            "body": {"data": encoded_text}}}
        if arguments["thread_id"]:
            payload["threadId"] = arguments["thread_id"]
        attempt = {"kind": arguments["kind"], "key": arguments["key"], "to": arguments["to"],
                   "body": arguments["body"], "state": "send attempted; delivery unconfirmed"}
        self.delivery_attempts.append(attempt)
        self.save()
        sent = await self.call_app("api_fetch", {"method": "POST", "url": arguments["send_url"], "params": None, "body": compact(payload)})
        sent_data = decode_data(sent["result"])
        if not isinstance(sent_data, dict) or not sent_data.get("id"):
            return {"unconfirmed": True, "sent_response": sent, "recovery": "Search sent mail before any retry; delivery may have happened."}
        read = await self.call_app("api_fetch", {"method": "GET", "url": arguments["read_url_template"].replace("{id}", sent_data["id"]), "params": compact({"format": "full"}), "body": None})
        actual = self.calls[read["call_index"]]["decoded"]
        if not contains(actual, arguments["to"]) or not contains(actual, arguments["body"]):
            return {"unconfirmed": True, "message_id": sent_data["id"], "read": read, "recovery": "Readback did not match recipient and full body; inspect before retrying."}
        receipt = {"kind": arguments["kind"], "key": arguments["key"], "read_call": read["call_index"],
                   "expected": {"recipient": arguments["to"], "body": arguments["body"]},
                   "description": "Sent and read back email to " + arguments["to"],
                   "evidence_id": len(self.evidence), "confirmed": True, "message_id": sent_data["id"]}
        self.evidence.append(receipt)
        attempt["state"] = "confirmed by independent readback"
        self.save()
        return receipt

    def confirmed_invoices(self):
        logged = []
        for receipt in self.evidence:
            if receipt["kind"] == "invoice" and receipt["key"] in self.invoices:
                entry = {"invoice": receipt["key"], "amount": self.invoices[receipt["key"]]["amount"]}
                if entry not in logged:
                    logged.append(entry)
        return logged

    def fallback(self, reason):
        logged = self.confirmed_invoices()
        reported_total = total_amounts([entry["amount"] for entry in logged])["total"]
        summary_confirmed = any(receipt["kind"] == "summary" for receipt in self.evidence)
        logged_keys = {entry["invoice"] for entry in logged}
        not_logged = [{"invoice": key, "reason": item["reason"] if item["decision"] != "eligible" else "Logging not confirmed before execution stopped; check the sheet before retrying."} for key, item in self.invoices.items() if key not in logged_keys]
        ledger = {"logged": logged, "not_logged": not_logged, "logged_total": reported_total, "status": "incomplete"}
        details = "\n".join("- Confirmed " + receipt["kind"] + ": " + receipt["key"] + " — " + receipt["description"] for receipt in self.evidence)
        summary_note = "Summary email was sent and independently read back." if summary_confirmed else "Summary email NOT confirmed. This report still gives the exact confirmed-row total; it does not claim email delivery."
        report = ("Logged total: " + reported_total + "\nAP processing is incomplete: " + reason + "\n" + details +
                  "\n" + summary_note + "\n" +
                  "\n".join("Not logged: " + entry["invoice"] + " — " + entry["reason"] for entry in not_logged) +
                  "\nOnly independently confirmed rows are counted. Inspect uncertain writes before rerunning.\n\n```json\n" + compact(ledger) + "\n```")
        self.final = {"report": report, "ledger": ledger, "finalized": False, "evidence": self.evidence, "failure": reason}
        self.save()

    async def run(self, instruction):
        definitions = Path("/run-input/tools.json").read_text()
        prompt = Path(__file__).with_name("ap_prompt.txt").read_text()
        conversation = [{"role": "system", "content": prompt + "\n\nORIGINAL SIMULATED TOOL DEFINITIONS:\n" + definitions},
                        {"role": "user", "content": instruction}]
        client = AsyncOpenAI(base_url=os.environ["TASK_MODEL_API_BASE"], api_key=os.environ["TASK_MODEL_API_KEY"], max_retries=0, timeout=110)
        try:
            for turn in range(24):
                if time.monotonic() - self.started > 420:
                    raise StopRun("Research time limit reached before completion plan was available; no writes authorized.")
                if turn in (10, 15, 20, 23) or time.monotonic() - self.started > 330:
                    conversation.append({"role": "user", "content": "Reserve budget for completion. Stop optional research; submit complete_day now if required sources are read. Batch any indispensable remaining reads. The completion helper handles all writes, failures, readbacks, summary and final JSON with no further model calls."})
                remaining = max(1, 550 - (time.monotonic() - self.started))
                response = await asyncio.wait_for(client.responses.create(model=os.environ["TASK_MODEL_NAME"], input=conversation, tools=RESEARCH_TOOLS, store=False, include=["reasoning.encrypted_content"]), timeout=remaining)
                conversation.extend(item.model_dump(exclude_none=True) for item in response.output)
                (self.output / "conversation.json").write_text(compact(conversation))
                calls = [item for item in response.output if item.type == "function_call"]
                if not calls:
                    conversation.append({"role": "user", "content": "Submit complete_day with the policy-compliant invoice plan. Text alone does not execute or finalize."})
                    continue
                for call in calls:
                    try:
                        result = await self.dispatch(call.name, json.loads(call.arguments))
                    except StopRun:
                        raise
                    except Exception as error:
                        if self.completion_started:
                            self.fallback(type(error).__name__ + ": " + str(error))
                            break
                        result = {"error": type(error).__name__ + ": " + str(error), "recovery": "Inspect app state before repeating any possibly committed write."}
                    conversation.append({"type": "function_call_output", "call_id": call.call_id, "output": compact(result)})
                    if self.final:
                        break
                (self.output / "conversation.json").write_text(compact(conversation))
                if self.final:
                    break
            if not self.final:
                self.fallback("Model turn limit reached.")
        except Exception as error:
            self.fallback(type(error).__name__ + ": " + str(error))
        finally:
            await client.close()
        return {"report": self.final["report"], "audit": compact(self.final)}


async def main():
    data = json.load(sys.stdin)
    runner = APRunner()
    try:
        result = await runner.run(data["instruction"])
    except Exception as error:
        runner.fallback(type(error).__name__ + ": " + str(error))
        result = {"report": runner.final["report"], "audit": compact(runner.final)}
    print(compact(result))


if __name__ == "__main__":
    asyncio.run(main())

import asyncio
import json
import os
import sys
import time
from pathlib import Path

from openai import AsyncOpenAI

from sim_api import execute


async def run(instruction):
    prompt = Path(__file__).with_name('ap_instructions.txt').read_text(encoding='utf-8')
    prompt = prompt.replace('{{instruction}}', instruction)
    prompt += '\nReturn the final user-facing report as ordinary text, not a wrapper object. Keep tool arguments compact. Finish within 32 model turns. If any limit interrupts work, report incomplete honestly. Use sim_api with action checkpoint and report (a string) to save a provisional factual final report after writes, before doing further work.'
    conversation = [{'role': 'user', 'content': instruction}]
    tool = {'type': 'function', 'name': 'sim_api', 'description': 'Simulated API discovery/calls/batches, exact sums, base64 decoding. request is a JSON string. action checkpoint saves a provisional user-facing report without changing any app.', 'parameters': {'type': 'object', 'properties': {'request': {'type': 'string'}}, 'required': ['request'], 'additionalProperties': False}, 'strict': True}
    client = AsyncOpenAI(base_url=os.environ['TASK_MODEL_API_BASE'], api_key=os.environ['TASK_MODEL_API_KEY'], max_retries=0, timeout=100)
    directory = Path(os.environ['METHOD_OUTPUT_DIR'])
    directory.mkdir(parents=True, exist_ok=True)
    checkpoint = None
    failure = 'Processing reached its time or request limit.'
    started = time.monotonic()
    try:
        for turn in range(36):
            if time.monotonic() - started > 500:
                break
            response = await client.responses.create(model=os.environ['TASK_MODEL_NAME'], instructions=prompt, input=conversation, tools=[tool], store=False, include=['reasoning.encrypted_content'])
            output = [item.model_dump(mode='json', exclude_none=True) for item in response.output]
            conversation.extend(output)
            with (directory / 'conversation.json').open('w', encoding='utf-8') as history:
                json.dump(conversation, history, ensure_ascii=False)
            calls = [item for item in output if item['type'] == 'function_call']
            if not calls:
                if response.output_text and response.status == 'completed':
                    return response.output_text
                failure = 'The model stopped before completing its report: ' + str(response.status)
                break
            for call in calls:
                try:
                    arguments = json.loads(call['arguments'])
                    request = json.loads(arguments['request'])
                    if request.get('action') == 'checkpoint':
                        checkpoint = request['report']
                        result = 'Checkpoint saved; continue remaining work.'
                    else:
                        result = await asyncio.to_thread(execute, request, False)
                except SystemExit:
                    failure = 'Service budget exhausted (HTTP 402); stopped without retry.'
                    return fallback(directory, failure, checkpoint)
                except Exception as error:
                    result = {'error': str(error), 'warning': 'No automatic retry. Read the destination before repeating any write.'}
                conversation.append({'type': 'function_call_output', 'call_id': call['call_id'], 'output': result if isinstance(result, str) else json.dumps(result, ensure_ascii=False)})
    except Exception as error:
        failure = 'Processing stopped: ' + str(error)[:400]
    finally:
        await client.close()
    return fallback(directory, failure, checkpoint)


def fallback(directory, failure, checkpoint):
    from check_effects import parsed, rows, message_body, recipients
    from sim_api import exact_sum
    events = []
    journal = directory / 'api-journal.jsonl'
    if journal.exists():
        events = [json.loads(line) for line in journal.read_text(encoding='utf-8').splitlines() if line.strip()]
    logged = []
    summary_total = None
    for index, event in enumerate(events):
        arguments = event.get('arguments', {})
        url = arguments.get('url', '')
        if ':append' in url and arguments.get('method') == 'POST':
            body = parsed(arguments.get('body'))
            if not isinstance(body, dict):
                continue
            for intended in body.get('values', []):
                for later in events[index + 1:]:
                    if later.get('arguments', {}).get('method') == 'GET' and '/values' in later.get('arguments', {}).get('url', ''):
                        if intended in rows(parsed(later.get('result'))) and len(intended) >= 4:
                            item = {'invoice': str(intended[1]), 'amount': str(intended[3])}
                            if item not in logged:
                                logged.append(item)
        if arguments.get('method') == 'GET':
            message = parsed(event.get('result'))
            if isinstance(message, dict) and 'ap-lead@company.example.com' in recipients(message):
                for line in message_body(message).splitlines():
                    if line.startswith('Logged total: '):
                        summary_total = line[len('Logged total: '):]
    try:
        total = summary_total or exact_sum([item['amount'] for item in logged])['reported_total']
    except ValueError:
        total = 'unconfirmed'
    data = {'logged': logged, 'not_logged': [], 'logged_total': total, 'status': 'incomplete'}
    detail = 'Confirmed logged invoices: ' + (', '.join(item['invoice'] + ' (' + item['amount'] + ')' for item in logged) or 'none') + '. '
    detail += 'A sent summary was observed.' if summary_total else 'Summary delivery is not confirmed.'
    if checkpoint:
        detail += '\nLast saved progress (may be partial):\n' + checkpoint
    return 'Incomplete AP processing. ' + failure + '\n' + detail + '\nUnresolved invoices and any unconfirmed changes require reconciliation before rerunning.\n```json\n' + json.dumps(data, ensure_ascii=False) + '\n```'


if __name__ == '__main__':
    inputs = json.load(sys.stdin)
    print(json.dumps({'report': asyncio.run(run(inputs['instruction']))}, ensure_ascii=False))

import asyncio
import json
import os
import sys
import time
from pathlib import Path

from openai import AsyncOpenAI

from sim_api import execute
from outcomes import render_report, save_ledger, reconcile


async def run(instruction):
    prompt = Path(__file__).with_name('ap_instructions.txt').read_text(encoding='utf-8')
    prompt = prompt.replace('{{instruction}}', instruction)
    prompt += '\nKeep tool arguments compact. Finish within 32 model turns. Before any writes save the complete structured invoice ledger using action checkpoint. The runner renders the final report from this ledger and independently observed effects, not provisional prose. Use action status to inspect remaining work and action finish after all required work and readbacks. Do not keep investigating after status is complete.'
    conversation = [{'role': 'user', 'content': instruction}]
    tool = {'type': 'function', 'name': 'sim_api', 'description': 'Simulated API discovery/calls/batches, exact sums, base64 decoding. request is a JSON string. checkpoint saves the structured invoice ledger before writes; status reconciles the ledger with independent readbacks; finish returns the reconciled final report. These three actions make no app calls.', 'parameters': {'type': 'object', 'properties': {'request': {'type': 'string'}}, 'required': ['request'], 'additionalProperties': False}, 'strict': True}
    client = AsyncOpenAI(base_url=os.environ['TASK_MODEL_API_BASE'], api_key=os.environ['TASK_MODEL_API_KEY'], max_retries=0, timeout=100)
    directory = Path(os.environ['METHOD_OUTPUT_DIR'])
    directory.mkdir(parents=True, exist_ok=True)
    failure = 'Processing reached its time or request limit.'
    started = time.monotonic()
    try:
        for turn in range(36):
            if time.monotonic() - started > 500:
                break
            response = await client.responses.create(model=os.environ['TASK_MODEL_NAME'], instructions=prompt, input=conversation, tools=[tool], store=False, include=['reasoning.encrypted_content'], timeout=min(100, max(1, 500 - (time.monotonic() - started))))
            output = [item.model_dump(mode='json', exclude_none=True) for item in response.output]
            conversation.extend(output)
            with (directory / 'conversation.json').open('w', encoding='utf-8') as history:
                json.dump(conversation, history, ensure_ascii=False)
            calls = [item for item in output if item['type'] == 'function_call']
            if not calls:
                if response.output_text and response.status == 'completed':
                    return render_report(directory)
                failure = 'The model stopped before completing its report: ' + str(response.status)
                break
            for call in calls:
                try:
                    arguments = json.loads(call['arguments'])
                    request = json.loads(arguments['request'])
                    if request.get('action') == 'checkpoint':
                        result = save_ledger(directory, request)
                    elif request.get('action') == 'status':
                        result = reconcile(directory)
                    elif request.get('action') == 'finish':
                        result = reconcile(directory)
                        conversation.append({'type': 'function_call_output', 'call_id': call['call_id'], 'output': json.dumps(result, ensure_ascii=False)})
                        (directory / 'conversation.json').write_text(json.dumps(conversation, ensure_ascii=False), encoding='utf-8')
                        return render_report(directory)
                    else:
                        require_ledger(directory, request)
                        result = await asyncio.to_thread(execute, request, False)
                except SystemExit:
                    failure = 'Service budget exhausted (HTTP 402); stopped without retry.'
                    return render_report(directory, failure)
                except Exception as error:
                    result = {'error': str(error), 'warning': 'No automatic retry. Read the destination before repeating any write.'}
                conversation.append({'type': 'function_call_output', 'call_id': call['call_id'], 'output': result if isinstance(result, str) else json.dumps(result, ensure_ascii=False)})
                (directory / 'conversation.json').write_text(json.dumps(conversation, ensure_ascii=False), encoding='utf-8')
    except Exception as error:
        failure = 'Processing stopped: ' + str(error)[:400]
    finally:
        await client.close()
    return render_report(directory, failure)


def require_ledger(directory, request):
    calls = request.get('calls', []) if request.get('action') == 'batch' else [request]
    for call in calls:
        arguments = call.get('arguments', {})
        if arguments.get('method', 'GET').upper() not in ('GET', 'HEAD'):
            path = directory / 'invoice-ledger.json'
            if not path.exists() or not json.loads(path.read_text(encoding='utf-8')).get('discovery_complete'):
                raise ValueError('Save action checkpoint with every invoice disposition and discovery_complete=true before writing to any app.')


if __name__ == '__main__':
    inputs = json.load(sys.stdin)
    print(json.dumps({'report': asyncio.run(run(inputs['instruction']))}, ensure_ascii=False))

import asyncio
import json
import os
import re
import sys
import time
from decimal import Decimal, localcontext
from pathlib import Path
from urllib.error import HTTPError
from urllib.request import Request, urlopen

from openai import AsyncOpenAI
from ap_helpers import adjust_due_date, same_message, sent_intent, unpack


class BudgetStop(Exception):
    pass


def load_tools():
    raw = json.loads(Path('/run-input/tools.json').read_text())
    if isinstance(raw, dict):
        raw = raw.get('tools', raw.get('functions', raw))
    if isinstance(raw, dict):
        raw = [dict(value, name=key) for key, value in raw.items()]
    normalized = []
    for entry in raw:
        item = entry.get('function', entry)
        name = item.get('name', '')
        if name not in ('api_search', 'api_fetch', 'base64_encode'):
            continue
        parameters = item.get('parameters', item.get('input_schema', item.get('inputSchema', {'type': 'object', 'properties': {}})))
        normalized.append({'type': 'function', 'name': name, 'description': item.get('description', ''), 'parameters': parameters, 'strict': False})
    if not {'api_search', 'api_fetch', 'base64_encode'}.issubset({item['name'] for item in normalized}):
        raise ValueError('The runtime did not supply all required simulated API tools.')
    return normalized


def calculate_amounts(arguments):
    values = arguments['amounts']
    amounts = []
    precision = 2
    for original in values:
        value = original.strip()
        value = re.sub(r'^(?:USD\s*|\$\s*)', '', value)
        value = re.sub(r'\s*USD$', '', value).strip()
        negative = value.startswith('(') and value.endswith(')')
        if negative:
            value = value[1:-1].strip()
        if not re.fullmatch(r'[+-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?', value):
            raise ValueError('Ambiguous or non-USD amount: ' + original)
        parsed = Decimal(value.replace(',', ''))
        if negative:
            parsed = -parsed
        precision = max(precision, -parsed.as_tuple().exponent)
        amounts.append(parsed)
    with localcontext() as context:
        context.prec = max(100, sum(len(value.as_tuple().digits) for value in amounts) + precision + 10)
        total = sum(amounts, Decimal(0))
        numeric = format(total, f'.{precision}f')
    return {'amounts_unchanged': values, 'total': '$' + numeric, 'summary_line': 'Logged total: $' + numeric}


class Runner:
    def __init__(self):
        self.started = time.monotonic()
        self.tool_count = 0
        self.history = []
        self.checkpoint = {'logged': [], 'not_logged': [], 'logged_total': 'unconfirmed', 'notes': []}
        self.endpoints = {}
        self.sent = []
        self.final_report = None
        self.ready_to_complete = False
        self.trace_dir = Path(os.environ.get('METHOD_OUTPUT_DIR', '/tmp/ap-agent-output'))
        self.trace_dir.mkdir(parents=True, exist_ok=True)

    def trace(self, value):
        with (self.trace_dir / 'ap_trace.jsonl').open('a') as stream:
            stream.write(json.dumps(value, ensure_ascii=False) + '\n')

    def persist(self):
        target = self.trace_dir / 'ap_progress.json'
        temporary = target.with_suffix('.tmp')
        temporary.write_text(json.dumps({'checkpoint': self.checkpoint, 'sent': self.sent, 'final_report': self.final_report}, ensure_ascii=False))
        temporary.replace(target)

    def summary_event(self):
        return next((event for event in reversed(self.sent) if event['to'] == ['ap-lead@company.example.com']), None)

    def observe(self, name, arguments, result, event=None):
        data = unpack(result)
        if not isinstance(data, dict):
            return
        if name == 'api_search':
            for endpoint in data.get('results', []):
                if endpoint.get('id') and endpoint.get('url'):
                    self.endpoints[endpoint['id']] = endpoint
        if event is not None:
            if data.get('id') and not data.get('error'):
                event['id'] = data['id']
                event['state'] = 'accepted'
            elif data.get('error'):
                event['error'] = str(data['error'])
        if name == 'api_fetch' and arguments.get('method', '').upper() == 'GET':
            message_id = data.get('id', data.get('message_id'))
            for known in self.sent:
                if message_id and known['id'] == message_id and same_message(known, data):
                    known['state'] = 'verified'
        self.persist()

    def remote_sync(self, name, arguments):
        request = Request(os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call', data=json.dumps({'name': name, 'arguments': arguments}).encode(), headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN'], 'Content-Type': 'application/json'}, method='POST')
        try:
            with urlopen(request, timeout=60) as response:
                payload = json.loads(response.read())
                return payload.get('result', payload)
        except HTTPError as error:
            if error.code == 402:
                raise BudgetStop('HTTP 402: execution budget exhausted') from error
            return {'error': 'HTTP ' + str(error.code), 'detail': error.read().decode(errors='replace'), 'warning': 'If this was a write, inspect effects before retrying.'}

    async def remote(self, name, arguments):
        if self.tool_count >= 92:
            return {'error': 'Simulated tool-call budget reached. Finish with an honest incomplete report.'}
        if time.monotonic() - self.started > 530:
            return {'error': 'Execution time nearly exhausted. Finish with actual effects and unresolved work.'}
        self.tool_count += 1
        event = None
        if name == 'api_fetch' and arguments.get('method', '').upper() == 'POST' and arguments.get('url', '').rstrip('/').endswith('/messages/send'):
            body = unpack(arguments.get('body', {}))
            if isinstance(body, dict) and body.get('raw'):
                event = sent_intent(body['raw'])
                event['url'] = arguments['url']
                self.sent.append(event)
                self.persist()
        self.trace({'tool': name, 'arguments': arguments})
        try:
            result = await asyncio.to_thread(self.remote_sync, name, arguments)
        except BudgetStop:
            raise
        except Exception as error:
            result = {'error': str(error), 'warning': 'A write may have committed. Read effects before retrying.'}
        self.trace({'tool_result': name, 'result': result})
        self.observe(name, arguments, result, event)
        if event is not None and event['state'] == 'accepted' and 'gmail.users.messages.get' in self.endpoints:
            template = self.endpoints['gmail.users.messages.get']['url']
            user = re.search(r'/users/([^/]+)/messages/send', arguments['url'])
            if user:
                url = template.replace('{userId}', user.group(1)).replace('{id}', event['id'])
                readback = await self.remote('api_fetch', {'method': 'GET', 'url': url, 'params': json.dumps({'format': 'full'}), 'body': None})
                return {'send_result': unpack(result), 'readback': unpack(readback), 'independently_verified': event['state'] == 'verified'}
        return result

    async def execute(self, name, arguments):
        if name == 'calculate_amounts':
            return calculate_amounts(arguments)
        if name == 'adjust_due_date':
            return adjust_due_date(arguments)
        if name == 'finalize_day':
            return await self.finalize_day(arguments)
        if name == 'record_progress':
            self.checkpoint = arguments
            self.trace({'checkpoint': arguments})
            self.persist()
            return {'saved': True}
        if name == 'batch_calls':
            calls = arguments['calls']
            if len(calls) > 12:
                return {'error': 'Use at most 12 independent calls per batch.'}
            if any(call['name'] not in ('api_search', 'api_fetch', 'base64_encode') for call in calls):
                return {'error': 'Unknown simulated tool name.'}
            results = await asyncio.gather(*(self.remote(call['name'], json.loads(call['arguments'])) for call in calls))
            return [{'name': call['name'], 'result': result} for call, result in zip(calls, results)]
        if name in ('api_search', 'api_fetch', 'base64_encode'):
            return await self.remote(name, arguments)
        return {'error': 'Unknown tool'}

    async def finalize_day(self, arguments):
        if self.final_report:
            return {'report': self.final_report}
        if 'gmail.users.messages.send' not in self.endpoints or 'gmail.users.messages.get' not in self.endpoints:
            return {'error': 'Discover gmail.users.messages.send and gmail.users.messages.get before finalizing.'}
        logged = arguments['logged']
        total = calculate_amounts({'amounts': [row['amount'] for row in logged]})
        self.checkpoint = {
            'logged': [{'invoice': row['invoice'], 'amount': row['amount']} for row in logged],
            'not_logged': arguments['not_logged'],
            'logged_total': 'unconfirmed',
            'notes': arguments['notes'],
        }
        self.ready_to_complete = arguments['all_required_work_complete']
        self.persist()
        existing = self.summary_event()
        if existing is not None:
            return {'error': 'A summary send was already attempted. Inspect its recorded result and Sent before any further send; do not duplicate it.', 'send_state': existing['state']}
        lines = ['AP processing summary - ' + arguments['day'], '', 'Logged and read back from Pending Invoices:']
        for row in logged:
            lines.append(' | '.join([row['vendor'], row['invoice'], row['date'], row['amount'], 'Due: ' + row['due_date']]))
            if row['notes']:
                lines.append('Notes: ' + row['notes'])
        if not logged:
            lines.append('None.')
        lines.extend(['', total['summary_line'], '', 'Not logged:'])
        for row in arguments['not_logged']:
            lines.append(row['invoice'] + ' | ' + row['reason'])
        if not arguments['not_logged']:
            lines.append('None.')
        lines.extend([''] + arguments['notes'])
        body = '\r\n'.join(lines) + '\r\n'
        if not re.fullmatch(r'[0-9]{4}-[0-9]{2}-[0-9]{2}', arguments['day']):
            raise ValueError('Processing day must be YYYY-MM-DD.')
        mime = ('To: ap-lead@company.example.com\r\n'
                'Subject: AP processing summary - ' + arguments['day'] + '\r\n'
                'MIME-Version: 1.0\r\nContent-Type: text/plain; charset=UTF-8\r\n'
                'Content-Transfer-Encoding: 8bit\r\n\r\n' + body)
        encoded = unpack(await self.remote('base64_encode', {'text': mime}))
        if isinstance(encoded, dict):
            encoded = encoded.get('encoded', encoded.get('base64', encoded.get('result')))
        if not isinstance(encoded, str):
            raise ValueError('Email encoding failed; summary was not sent.')
        endpoint = self.endpoints['gmail.users.messages.send']
        url = endpoint['url'].replace('{userId}', 'ap@company.example.com')
        await self.remote('api_fetch', {'method': endpoint['method'], 'url': url, 'params': None, 'body': json.dumps({'raw': encoded})})
        self.final_report = self.render_report()
        self.persist()
        return {'report': self.final_report}

    def render_report(self, interruption=None):
        snapshot = {key: self.checkpoint[key] for key in ('logged', 'not_logged', 'logged_total')}
        summary = self.summary_event()
        if summary and summary['state'] in ('accepted', 'verified'):
            totals = re.findall(r'^Logged total: ([^\r\n]+)', summary['body'], re.MULTILINE)
            if totals:
                snapshot['logged_total'] = totals[-1]
            summary_note = ('Summary sent to ap-lead@company.example.com and independently verified.'
                            if summary['state'] == 'verified' else
                            'Summary send accepted by the email API; independent read-back is unconfirmed.')
        elif summary:
            summary_note = 'Summary send was attempted; delivery is uncertain. Inspect Sent before retrying.'
        else:
            summary_note = 'No summary send was recorded.'
        complete = (self.ready_to_complete and summary is not None and summary['state'] == 'verified'
                    and all(event['state'] == 'verified' for event in self.sent))
        snapshot['status'] = 'complete' if complete else 'incomplete'
        lines = [f"Logged {len(snapshot['logged'])} invoices. {summary_note}"]
        if snapshot['logged_total'] != 'unconfirmed':
            lines.append('Logged total: ' + snapshot['logged_total'])
        returns = [event for event in self.sent if event['to'] != ['ap-lead@company.example.com']]
        if returns:
            verified = sum(event['state'] == 'verified' for event in returns)
            lines.append(f'{verified} return email(s) independently verified; {len(returns) - verified} send(s) unconfirmed.')
        if snapshot['not_logged']:
            lines.append('Not logged: ' + '; '.join(row['invoice'] + ' — ' + row['reason'] for row in snapshot['not_logged']))
        if not complete and interruption:
            lines.append('Processing stopped: ' + interruption + '. Recorded sends above take precedence over earlier checkpoints; uncertain writes must be reconciled before retrying.')
        elif not complete:
            lines.append('Some required work or verification remains unresolved.')
        return '\n'.join(lines) + '\n\n```json\n' + json.dumps(snapshot, ensure_ascii=False) + '\n```'

    async def run(self, instruction):
        tools = load_tools()
        tools.extend([
            {'type': 'function', 'name': 'adjust_due_date', 'description': 'Apply an authorized weekend-to-Monday rule without changing the source date format. Weekdays are returned byte-for-byte unchanged. ISO dates remain ISO; written month dates retain their spelling style. Only set weekend_to_monday when current policy requires it.', 'parameters': {'type': 'object', 'properties': {'due_date': {'type': 'string'}, 'weekend_to_monday': {'type': 'boolean'}}, 'required': ['due_date', 'weekend_to_monday'], 'additionalProperties': False}, 'strict': True},
            {'type': 'function', 'name': 'finalize_day', 'description': 'Finish the run without another model request: save verified outcomes, compute the exact total, construct the AP summary from verbatim logged fields, encode and send it through discovered simulated endpoints, independently read it back, and return the final user report. Call once after all sheet read-backs and blocked returns. Does not log invoices. Only include actually logged and verified rows. all_required_work_complete means all applicable policy/source investigations, invoice dispositions, sheet writes, and blocked returns are done, except this summary. Discover Gmail send/get first. Do not manually send the summary.', 'parameters': {'type': 'object', 'properties': {'day': {'type': 'string'}, 'logged': {'type': 'array', 'items': {'type': 'object', 'properties': {key: {'type': 'string'} for key in ('vendor', 'invoice', 'date', 'amount', 'due_date', 'notes')}, 'required': ['vendor', 'invoice', 'date', 'amount', 'due_date', 'notes'], 'additionalProperties': False}}, 'not_logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': {'type': 'string'}, 'reason': {'type': 'string'}}, 'required': ['invoice', 'reason'], 'additionalProperties': False}}, 'notes': {'type': 'array', 'items': {'type': 'string'}}, 'all_required_work_complete': {'type': 'boolean'}}, 'required': ['day', 'logged', 'not_logged', 'notes', 'all_required_work_complete'], 'additionalProperties': False}, 'strict': True},
            {'type': 'function', 'name': 'record_progress', 'description': 'Save a full snapshot of independently verified actions for an honest interruption report. Call after spreadsheet read-back and again after verifying email sends. Include every verified logged invoice so far, all known non-logged dispositions, and factual action notes. logged_total is the total actually sent to the lead, or unconfirmed if not yet sent and verified. This does not change simulated apps.', 'parameters': {'type': 'object', 'properties': {'logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': {'type': 'string'}, 'amount': {'type': 'string'}}, 'required': ['invoice', 'amount'], 'additionalProperties': False}}, 'not_logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': {'type': 'string'}, 'reason': {'type': 'string'}}, 'required': ['invoice', 'reason'], 'additionalProperties': False}}, 'logged_total': {'type': 'string'}, 'notes': {'type': 'array', 'items': {'type': 'string'}}}, 'required': ['logged', 'not_logged', 'logged_total', 'notes'], 'additionalProperties': False}, 'strict': True},
            {'type': 'function', 'name': 'calculate_amounts', 'description': 'Exactly add the verbatim USD amounts of newly logged verified invoices using Decimal, without rounding. Does not modify source values. Returns the total and required email line.', 'parameters': {'type': 'object', 'properties': {'amounts': {'type': 'array', 'items': {'type': 'string'}}}, 'required': ['amounts'], 'additionalProperties': False}, 'strict': True},
            {'type': 'function', 'name': 'batch_calls', 'description': 'Execute independent simulated tool calls concurrently. Use primarily for searches/reads. Do not put a write and its verification or dependent calls in the same batch. Arguments must be JSON strings matching each original tool schema.', 'parameters': {'type': 'object', 'properties': {'calls': {'type': 'array', 'items': {'type': 'object', 'properties': {'name': {'type': 'string', 'enum': ['api_search', 'api_fetch', 'base64_encode']}, 'arguments': {'type': 'string'}}, 'required': ['name', 'arguments'], 'additionalProperties': False}}}, 'required': ['calls'], 'additionalProperties': False}, 'strict': True},
        ])
        self.history = [{'role': 'system', 'content': Path(__file__).with_name('ap_instructions.txt').read_text()}, {'role': 'user', 'content': instruction}]
        self.trace({'tools': tools})
        client = AsyncOpenAI(base_url=os.environ['TASK_MODEL_API_BASE'], api_key=os.environ['TASK_MODEL_API_KEY'], max_retries=0, timeout=110)
        try:
            for turn in range(44):
                if turn == 37 or time.monotonic() - self.started > 470:
                    self.history.append({'role': 'developer', 'content': 'Resources are running low. Complete essential verification and summary if possible, then give an honest final report. Do not start optional investigation or claim unverified actions succeeded.'})
                response = await client.responses.create(model=os.environ['TASK_MODEL_NAME'], input=self.history, tools=tools, store=False, include=['reasoning.encrypted_content'])
                output = [item.model_dump(exclude_none=True) for item in response.output]
                self.history.extend(output)
                self.trace({'turn': turn, 'output': output})
                calls = [item for item in response.output if item.type == 'function_call']
                if not calls:
                    if response.output_text.strip():
                        return response.output_text
                    self.history.append({'role': 'developer', 'content': 'Return your final AP report now if finished, otherwise continue using tools.'})
                    continue
                for call in calls:
                    try:
                        result = await self.execute(call.name, json.loads(call.arguments))
                    except BudgetStop:
                        raise
                    except Exception as error:
                        result = {'error': str(error)}
                    self.history.append({'type': 'function_call_output', 'call_id': call.call_id, 'output': result if isinstance(result, str) else json.dumps(result, ensure_ascii=False)})
                    if self.final_report is not None:
                        return self.final_report
            return self.fallback('Model-turn limit reached before a final report was produced.')
        except Exception as error:
            self.trace({'stopped': str(error)})
            return self.fallback(str(error))
        finally:
            await client.close()

    def fallback(self, reason):
        return self.final_report or self.render_report(reason)


async def main():
    inputs = json.load(sys.stdin)
    runner = Runner()
    try:
        report = await runner.run(inputs['instruction'])
    except Exception as error:
        report = runner.fallback(str(error))
    print(json.dumps({'report': report}, ensure_ascii=False))


if __name__ == '__main__':
