import asyncio
import json
import os
import sys
import time
from pathlib import Path

from openai import AsyncOpenAI

import sim_api
from finish_ap import finalize, readback_writes
from outcomes import render_report, save_ledger, reconcile


def save_history(directory, conversation):
    (directory / 'conversation.json').write_text(json.dumps(conversation, ensure_ascii=False), encoding='utf-8')


def persist_report(directory, interruption=None):
    (directory / 'interruption.json').write_text(json.dumps(interruption), encoding='utf-8')
    report = render_report(directory, interruption)
    (directory / 'final-report.txt').write_text(report, encoding='utf-8')
    return report


async def run(instruction):
    directory = Path(os.environ['METHOD_OUTPUT_DIR'])
    directory.mkdir(parents=True, exist_ok=True)
    started = time.monotonic()
    sim_api.DEADLINE = started + 530
    prompt = Path(__file__).with_name('ap_instructions.txt').read_text(encoding='utf-8').replace('{{instruction}}', instruction)
    prompt += '\nKeep tool arguments compact. Complete investigation and invoice writes in at most 26 model turns. The runner automatically reads back app writes after each tool request. Do not repeat successful readbacks. Before writes save the complete invoice ledger. The runner sends the AP summary and renders the final report deterministically when you call finish or stop. Do not send the summary yourself. Call finish once every eligible invoice has been attempted and every blocked invoice returned. If the sheet persistently rejects a specific row, keep its log decision, preserve its exact data, and finish the other work; the runner reports it as not logged. Do not loop on that failure.'
    conversation = [{'role': 'user', 'content': instruction}]
    tool = {'type': 'function', 'name': 'sim_api', 'description': 'Simulated API discovery/calls/batches, exact sums, base64 decoding. request is a JSON string. checkpoint saves the structured invoice ledger before writes; status reconciles outcomes; finish ends invoice processing and hands off to deterministic summary delivery and final reporting. Writes are automatically followed by independent readbacks; their current outcomes are included in tool results.', 'parameters': {'type': 'object', 'properties': {'request': {'type': 'string'}}, 'required': ['request'], 'additionalProperties': False}, 'strict': True}
    client = AsyncOpenAI(base_url=os.environ['TASK_MODEL_API_BASE'], api_key=os.environ['TASK_MODEL_API_KEY'], max_retries=0, timeout=80)
    failure = None
    finished = False
    try:
        for turn in range(30):
            remaining = 405 - (time.monotonic() - started)
            if remaining < 8:
                failure = 'Invoice processing reached its time limit; reserved time was used for summary and reporting.'
                break
            response = await client.responses.create(model=os.environ['TASK_MODEL_NAME'], instructions=prompt, input=conversation, tools=[tool], store=False, include=['reasoning.encrypted_content'], timeout=min(80, remaining))
            output = [item.model_dump(mode='json', exclude_none=True) for item in response.output]
            conversation.extend(output)
            save_history(directory, conversation)
            calls = [item for item in output if item['type'] == 'function_call']
            if not calls:
                finished = response.status == 'completed'
                if not finished:
                    failure = 'Model execution stopped: ' + str(response.status)
                break
            for call in calls:
                try:
                    arguments = json.loads(call['arguments'])
                    request = json.loads(arguments['request'])
                    action = request.get('action')
                    if action == 'checkpoint':
                        result = save_ledger(directory, request)
                    elif action in ('status', 'finish'):
                        result = reconcile(directory)
                        if action == 'finish':
                            finished = True
                    else:
                        require_ledger(directory, request)
                        result = await asyncio.to_thread(sim_api.execute, request, False)
                        if has_write(request):
                            await asyncio.to_thread(readback_writes, directory)
                            result = {'api_result': result, 'observed_outcomes': reconcile(directory)}
                except SystemExit:
                    sim_api.STOPPED = True
                    failure = 'Service budget exhausted (HTTP 402); stopped without retry.'
                    finished = True
                    result = {'error': failure}
                except Exception as error:
                    result = {'error': str(error), 'warning': 'No automatic retry. Read the destination before repeating any write.'}
                conversation.append({'type': 'function_call_output', 'call_id': call['call_id'], 'output': result if isinstance(result, str) else json.dumps(result, ensure_ascii=False)})
                save_history(directory, conversation)
                persist_report(directory, failure)
            if finished:
                break
        else:
            failure = 'Invoice processing reached its model-turn limit; summary and reporting continued.'
    except Exception as error:
        if getattr(error, 'status_code', None) == 402:
            sim_api.STOPPED = True
            failure = 'Service budget exhausted (HTTP 402); stopped without retry.'
        else:
            failure = 'Invoice processing stopped: ' + str(error)[:400]
    finally:
        await client.close()
    if not sim_api.STOPPED:
        try:
            await asyncio.to_thread(finalize, directory, instruction)
        except SystemExit:
            sim_api.STOPPED = True
            failure = 'Service budget exhausted (HTTP 402); stopped without retry.'
        except Exception as error:
            failure = (failure + ' ' if failure else '') + 'Finalization: ' + str(error)[:400]
    return persist_report(directory, failure)


def has_write(request):
    calls = request.get('calls', []) if request.get('action') == 'batch' else [request]
    return any(call.get('arguments', {}).get('method', 'GET').upper() not in ('GET', 'HEAD') for call in calls)


def require_ledger(directory, request):
    if has_write(request):
        path = directory / 'invoice-ledger.json'
        if not path.exists() or not json.loads(path.read_text(encoding='utf-8')).get('discovery_complete'):
            raise ValueError('Save action checkpoint with every invoice disposition and discovery_complete=true before writing to any app.')


if __name__ == '__main__':
    inputs = json.load(sys.stdin)
    print(json.dumps({'report': asyncio.run(run(inputs['instruction']))}, ensure_ascii=False))

import asyncio
import base64
import json
import os
