class BudgetStop(Exception):
    pass


def load_tools():
    raw = json.loads(Path('/run-input/tools.json').read_text())
    if isinstance(raw, dict):
        for key in ('tools', 'definitions', 'functions'):
            if key in raw:
                raw = raw[key]
                break
    if isinstance(raw, dict):
        raw = [dict(value, name=value.get('name', key)) for key, value in raw.items()]
    tools = []
    for entry in raw:
        definition = entry.get('function', entry)
        name = definition.get('name', '')
        if not any(name == wanted or name.endswith('__' + wanted) or name.endswith('_' + wanted) for wanted in ('api_search', 'api_fetch', 'base64_encode')):
            continue
        parameters = definition.get('parameters', definition.get('input_schema', definition.get('inputSchema', definition.get('schema', {'type': 'object', 'properties': {}}))))
        tools.append({'type': 'function', 'name': name, 'description': definition.get('description', ''), 'parameters': parameters, 'strict': False})
    if not any('api_search' in tool['name'] for tool in tools) or not any('api_fetch' in tool['name'] for tool in tools):
        raise ValueError('Required simulated API tools were not supplied.')
    return tools


LOCAL_TOOLS = [
    {'type': 'function', 'name': 'checkpoint_progress', 'description': 'Save the actual invoice ledger and action status locally so a timeout or budget interruption can still report completed work. Call after worksheet verification and again after required emails. Do not put merely planned rows in logged.', 'parameters': {'type': 'object', 'properties': {'logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': {'type': 'string'}, 'amount': {'type': 'string'}}, 'required': ['invoice', 'amount'], 'additionalProperties': False}}, 'not_logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': {'type': 'string'}, 'reason': {'type': 'string'}}, 'required': ['invoice', 'reason'], 'additionalProperties': False}}, 'logged_total': {'type': 'string'}, 'actions': {'type': 'string'}}, 'required': ['logged', 'not_logged', 'logged_total', 'actions'], 'additionalProperties': False}, 'strict': True},
    {'type': 'function', 'name': 'send_email', 'description': 'Compose, encode with the supplied base64_encode tool, and send a plain-text email through a previously discovered simulated Gmail send endpoint. Returns the send result, not verification. You must read it back afterward. Only AP lead or original invoice sender recipients are allowed by the workflow.', 'parameters': {'type': 'object', 'properties': {'send_url': {'type': 'string'}, 'to': {'type': 'string'}, 'subject': {'type': 'string'}, 'body': {'type': 'string'}}, 'required': ['send_url', 'to', 'subject', 'body'], 'additionalProperties': False}, 'strict': True},
    {'type': 'function', 'name': 'verify_effect', 'description': 'Independently read a changed simulated system using api_fetch and check exact expected source strings in its response. Use for worksheet and sent-email read-back instead of a separate api_fetch. Supply the documented read-only api_fetch arguments as JSON. Never use mutation endpoints here.', 'parameters': {'type': 'object', 'properties': {'fetch_arguments': {'type': 'string'}, 'expected_strings': {'type': 'array', 'items': {'type': 'string'}}, 'purpose': {'type': 'string', 'enum': ['spreadsheet', 'summary_email', 'return_email']}}, 'required': ['fetch_arguments', 'expected_strings', 'purpose'], 'additionalProperties': False}, 'strict': True},
    {'type': 'function', 'name': 'calculate_total', 'description': 'Sum exact invoice amount strings using decimal arithmetic, without rounding. Only USD at a time. Returns source strings and exact dollar total.', 'parameters': {'type': 'object', 'properties': {'amounts': {'type': 'array', 'items': {'type': 'string'}}}, 'required': ['amounts'], 'additionalProperties': False}, 'strict': True},
    {'type': 'function', 'name': 'decode_base64', 'description': 'Decode base64/base64url email text or text attachment content locally. Not for binary files.', 'parameters': {'type': 'object', 'properties': {'data': {'type': 'string'}}, 'required': ['data'], 'additionalProperties': False}, 'strict': True},
]


def calculate_total(amounts):
    parsed = []
    for amount in amounts:
        value = amount.strip()
        negative = value.startswith('(') and value.endswith(')')
        if negative:
            value = value[1:-1].strip()
        value = re.sub(r'^(?:USD\s*|\$\s*)', '', value)
        value = re.sub(r'\s*USD$', '', value).strip()
        if not re.fullmatch(r'[+-]?(?:[0-9]+|[0-9]{1,3}(?:,[0-9]{3})+)(?:\.[0-9]+)?', value):
            raise ValueError('Ambiguous or unsupported amount format: ' + amount)
        number = Decimal(value.replace(',', ''))
        parsed.append(-number if negative else number)
    with localcontext() as context:
        context.prec = max(100, sum(len(str(value)) for value in parsed) + 10)
        total = sum(parsed, Decimal('0'))
    places = max(2, max((-value.as_tuple().exponent for value in parsed), default=2))
    numeric = format(total, f'.{places}f')
    return {'amounts': amounts, 'numeric_total': numeric, 'logged_total': '$' + numeric, 'summary_line': 'Logged total: $' + numeric}


def incomplete_report(detail):
    checkpoint_path = Path(os.environ.get('METHOD_OUTPUT_DIR', '/tmp/ap-agent')) / 'ap_checkpoint.json'
    if checkpoint_path.exists():
        checkpoint = json.loads(checkpoint_path.read_text())
        actions = checkpoint.pop('actions', '')
        checkpoint['status'] = 'incomplete'
        return 'AP processing is incomplete. ' + detail + '\nLast saved actual progress: ' + actions + '\nAny actions after that checkpoint may be unconfirmed; reconcile before retrying.\n' + json.dumps(checkpoint, ensure_ascii=False)
    return ('AP processing is incomplete. ' + detail + '\nNo complete, verified ledger is available; reconcile any attempted changes before rerunning.\n' + json.dumps({'logged': [], 'not_logged': [], 'logged_total': '', 'status': 'incomplete'}))


def response_strings(value):
    found = []
    if isinstance(value, str):
        found.append(value)
        try:
            decoded = json.loads(value)
            if decoded != value:
                found.extend(response_strings(decoded))
        except (ValueError, TypeError):
            pass
    elif isinstance(value, dict):
        for child in value.values():
            found.extend(response_strings(child))
    elif isinstance(value, list):
        for child in value:
            found.extend(response_strings(child))
    return found


async def run_agent(instruction):
    started = time.monotonic()
    tools = load_tools()
    remote_names = {tool['name'] for tool in tools}
    tools.extend(LOCAL_TOOLS)
    prompt = Path(__file__).with_name('ap_instructions.txt').read_text()
    conversation = [{'role': 'system', 'content': prompt}, {'role': 'user', 'content': instruction}]
    output_dir = Path(os.environ.get('METHOD_OUTPUT_DIR', '/tmp/ap-agent'))
    output_dir.mkdir(parents=True, exist_ok=True)
    trace_path = output_dir / 'ap_trace.jsonl'
    evidence_path = output_dir / 'ap_evidence.json'
    evidence = []
    evidence_path.write_text('[]')
    checkpoint_path = output_dir / 'ap_checkpoint.json'
    if checkpoint_path.exists():
        checkpoint_path.unlink()
    tool_count = 0
    last_text = ''
    client = AsyncOpenAI(base_url=os.environ['TASK_MODEL_API_BASE'], api_key=os.environ['TASK_MODEL_API_KEY'], max_retries=0, timeout=120)
    async with httpx.AsyncClient(timeout=55) as bridge:
        for turn in range(46):
            remaining = 545 - (time.monotonic() - started)
            if remaining < 8:
                break
            finalize = remaining < 45 or tool_count >= 87 or turn >= 44
            if finalize:
                conversation.append({'role': 'user', 'content': 'Execution limit is near. Make no more external calls. Provide the final report now, describing only actual verified work and clearly marking unfinished or unverified actions. Use status incomplete if anything necessary remains. End with the required JSON.'})
            try:
                response = await asyncio.wait_for(client.responses.create(model=os.environ['TASK_MODEL_NAME'], input=conversation, tools=tools, tool_choice='none' if finalize else 'auto', store=False, include=['reasoning.encrypted_content']), timeout=max(5, min(120, remaining)))
            except Exception as error:
                if getattr(error, 'status_code', None) == 402:
                    raise BudgetStop('Model budget exhausted; stopped without further requests.') from error
                raise
            items = [item.model_dump(exclude_none=True) for item in response.output]
            conversation.extend(items)
            with trace_path.open('a') as trace:
                trace.write(json.dumps({'turn': turn, 'output': items}, ensure_ascii=False) + '\n')
            if response.output_text:
                last_text = response.output_text
            calls = [item for item in response.output if item.type == 'function_call']
            if not calls:
                if response.output_text:
                    return response.output_text
                continue
            for call in calls:
                arguments = json.loads(call.arguments)
                try:
                    if call.name == 'calculate_total':
                        result = calculate_total(arguments['amounts'])
                    elif call.name == 'checkpoint_progress':
                        checkpoint_path.write_text(json.dumps(arguments, ensure_ascii=False))
                        result = {'saved': True}
                    elif call.name == 'send_email':
                        if any(character in arguments['to'] + arguments['subject'] for character in ('\r', '\n')):
                            raise ValueError('Email headers must not contain newlines.')
                        message = EmailMessage(policy=SMTP)
                        message['From'] = 'ap@company.example.com'
                        message['To'] = arguments['to']
                        message['Subject'] = arguments['subject']
                        message.set_content(arguments['body'], charset='utf-8', cte='8bit')
                        raw_text = message.as_string()
                        encode_name = next(name for name in remote_names if 'base64_encode' in name)
                        fetch_name = next(name for name in remote_names if 'api_fetch' in name)
                        tool_count += 1
                        encoded_reply = await bridge.post(os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call', headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN']}, json={'name': encode_name, 'arguments': {'text': raw_text}})
                        if encoded_reply.status_code == 402:
                            raise BudgetStop('Email encoding budget exhausted; stopped.')
                        encoded_reply.raise_for_status()
                        encoded = encoded_reply.json().get('result')
                        expected = base64.urlsafe_b64encode(raw_text.encode('utf-8')).decode().rstrip('=')
                        if isinstance(encoded, str):
                            normalized = encoded.strip().replace('+', '-').replace('/', '_').rstrip('=')
                        else:
                            normalized = ''
                        if normalized != expected:
                            raise ValueError('Email encoding result did not match the complete message; nothing sent.')
                        tool_count += 1
                        sent_reply = await bridge.post(os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call', headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN']}, json={'name': fetch_name, 'arguments': {'method': 'POST', 'url': arguments['send_url'], 'params': None, 'body': json.dumps({'raw': normalized})}})
                        if sent_reply.status_code == 402:
                            raise BudgetStop('Email sending budget exhausted; stopped.')
                        sent_reply.raise_for_status()
                        result = sent_reply.json()
                    elif call.name == 'decode_base64':
                        data = arguments['data']
                        result = {'text': base64.urlsafe_b64decode(data + '=' * (-len(data) % 4)).decode('utf-8')}
                    elif call.name == 'verify_effect':
                        fetch_arguments = json.loads(arguments['fetch_arguments'])
                        method = str(fetch_arguments.get('method', 'GET')).upper()
                        if method not in ('GET', 'HEAD'):
                            raise ValueError('Verification must use a read-only GET endpoint.')
                        tool_count += 1
                        fetch_name = next(name for name in remote_names if 'api_fetch' in name)
                        reply = await bridge.post(os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call', headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN']}, json={'name': fetch_name, 'arguments': fetch_arguments})
                        if reply.status_code == 402:
                            raise BudgetStop('Simulated API budget exhausted; stopped without further requests.')
                        reply.raise_for_status()
                        observed = reply.json()
                        strings = response_strings(observed)
                        missing = [expected for expected in arguments['expected_strings'] if not any(expected in text for text in strings)]
                        receipt = {'purpose': arguments['purpose'], 'verified': bool(arguments['expected_strings']) and not missing, 'expected_strings': arguments['expected_strings'], 'missing': missing}
                        evidence.append(receipt)
                        evidence_path.write_text(json.dumps(evidence, ensure_ascii=False))
                        result = dict(receipt, observed=observed)
                    elif call.name in remote_names:
                        if tool_count >= 90 or time.monotonic() - started > 540:
                            result = {'error': 'Execution limit reached. Do not attempt more calls; report partial results.'}
                        else:
                            tool_count += 1
                            reply = await bridge.post(os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call', headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN']}, json={'name': call.name, 'arguments': arguments})
                            if reply.status_code == 402:
                                raise BudgetStop('Simulated API budget exhausted; stopped without further requests.')
                            reply.raise_for_status()
                            payload = reply.json()
                            result = payload.get('result', payload)
                    else:
                        result = {'error': 'Unknown tool.'}
                except BudgetStop:
                    raise
                except Exception as error:
                    result = {'error': str(error), 'warning': 'An external write may have succeeded despite this error. Read before retrying.'}
                output = result if isinstance(result, str) else json.dumps(result, ensure_ascii=False)
                conversation.append({'type': 'function_call_output', 'call_id': call.call_id, 'output': output})
                with trace_path.open('a') as trace:
                    trace.write(json.dumps({'tool': call.name, 'arguments': arguments, 'result': result}, ensure_ascii=False) + '\n')
    return incomplete_report('The execution limit was reached.' + (' Last agent update: ' + last_text if last_text else ''))


def main():
    try:
        inputs = json.load(sys.stdin)
        report = asyncio.run(run_agent(inputs['instruction']))
    except Exception as error:
        report = incomplete_report(str(error))
    output_dir = Path(os.environ.get('METHOD_OUTPUT_DIR', '/tmp/ap-agent'))
    output_dir.mkdir(parents=True, exist_ok=True)
    (output_dir / 'ap_report.txt').write_text(report)
    evidence_path = output_dir / 'ap_evidence.json'
    evidence = evidence_path.read_text() if evidence_path.exists() else '[]'
    print(json.dumps({'report': report, 'verification_evidence': evidence}, ensure_ascii=False))


if __name__ == '__main__':
    main()

import asyncio
import base64
import json
import os
import re
import sys
import time
from decimal import Decimal
from email.message import EmailMessage
from email.policy import SMTP
from pathlib import Path

import requests
from openai import AsyncOpenAI


class StopBudget(Exception):
    pass


def tool_definitions(raw):
    if isinstance(raw, dict):
        if 'tools' in raw:
            return tool_definitions(raw['tools'])
        if 'name' in raw or 'function' in raw:
            raw = [raw]
        else:
            raw = [dict(value, name=key) for key, value in raw.items() if isinstance(value, dict)]
    definitions = []
    for entry in raw:
        item = entry.get('function', entry)
        name = item.get('name', '')
        if not any(part in name for part in ('api_search', 'api_fetch', 'base64_encode')):
            continue
        if entry.get('type') == 'custom':
            definitions.append(entry)
        else:
            definitions.append({
                'type': 'function',
                'name': name,
                'description': item.get('description', ''),
                'parameters': item.get('parameters', item.get('input_schema', item.get('inputSchema', {'type': 'object', 'properties': {}}))),
            })
    if not definitions:
        raise ValueError('No simulated API tools were supplied')
    return definitions


def function(name, description, properties, required):
    return {'type': 'function', 'name': name, 'description': description, 'parameters': {
        'type': 'object', 'properties': properties, 'required': required, 'additionalProperties': False}}


def exact_total(amounts):
    total = Decimal('0')
    places = 2
    for original in amounts:
        value = original.strip()
        negative = value.startswith('(') and value.endswith(')')
        if negative:
            value = value[1:-1].strip()
        value = re.sub(r'^(?:USD\s*|US\$\s*|\$\s*)', '', value, flags=re.I)
        value = re.sub(r'\s+USD$', '', value, flags=re.I).strip()
        if value.startswith('(') and value.endswith(')'):
            negative = True
            value = value[1:-1]
        if not re.fullmatch(r'[+-]?(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d+)?', value):
            raise ValueError('Ambiguous or non-USD amount; do not guess: ' + original)
        number = Decimal(value.replace(',', ''))
        if negative:
            number = -number
        places = max(places, -number.as_tuple().exponent)
        total += number
    display = '$' + format(total, ',.' + str(places) + 'f')
    return {'total': display, 'summary_line': 'Logged total: ' + display, 'count': len(amounts)}


LOCAL_TOOLS = [
    function('send_email_checked', 'After discovering Gmail messages.send and threads.get, encode a plain-text email with the supplied base64_encode tool, send it, and read the sent thread independently. Inspect returned evidence; do not resend if verification fails.',
             {'to': {'type': 'string'}, 'subject': {'type': 'string'}, 'body': {'type': 'string'},
              'thread_id': {'type': 'string', 'description': 'Original thread for a return reply, or empty for summary.'}},
             ['to', 'subject', 'body', 'thread_id']),
    function('exact_total', 'Sum original USD amount strings exactly without changing source values. Use before emailing the summary.',
             {'amounts': {'type': 'array', 'items': {'type': 'string'}}}, ['amounts']),
    function('decode_source', 'Decode a base64 or base64url email body as UTF-8 text.',
             {'data': {'type': 'string'}}, ['data']),
    function('finish_report', 'End the run with the verified action ledger, user-facing notes, and required final JSON. Use only after performing the task or encountering a real blocker.',
             {'logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': {'type': 'string'}, 'amount': {'type': 'string'}}, 'required': ['invoice', 'amount'], 'additionalProperties': False}},
              'not_logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': {'type': 'string'}, 'reason': {'type': 'string'}}, 'required': ['invoice', 'reason'], 'additionalProperties': False}},
              'logged_total': {'type': 'string', 'description': 'Exact total string actually included in the summary; if no summary sent, state not reported.'},
              'status': {'type': 'string', 'enum': ['complete', 'incomplete']},
              'notes': {'type': 'string', 'description': 'Concise factual report of actual actions, returns, summary delivery/verification, and any unresolved work.'}},
             ['logged', 'not_logged', 'logged_total', 'status', 'notes']),
]


class DailyAgent:
    def __init__(self):
        self.started = time.monotonic()
        self.calls = 0
        self.trace = []
        self.final = None
        self.total = None
        self.remote_names = {}
        self.discovered = set()

    def save_trace(self):
        directory = os.environ.get('METHOD_OUTPUT_DIR')
        if directory:
            Path(directory).mkdir(parents=True, exist_ok=True)
            Path(directory, 'ap-audit.json').write_text(json.dumps(self.trace, ensure_ascii=False, indent=2))

    def remote(self, name, arguments):
        self.calls += 1
        if self.calls > 94:
            raise StopBudget('Simulated tool-call limit reached')
        response = requests.post(os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call',
                                 headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN']},
                                 json={'name': name, 'arguments': arguments}, timeout=70)
        if response.status_code == 402:
            raise StopBudget('Tool budget exhausted (HTTP 402)')
        response.raise_for_status()
        payload = response.json()
        result = payload.get('result', payload)
        if 'api_search' in name:
            try:
                found = json.loads(result) if isinstance(result, str) else result
                for endpoint in found.get('results', []):
                    self.discovered.add(endpoint.get('id', ''))
            except (ValueError, AttributeError):
                pass
        return result

    def send_email_checked(self, arguments):
        needed = {'gmail.users.messages.send', 'gmail.users.threads.get'}
        if not needed.issubset(self.discovered):
            return {'error': 'Discover gmail.users.messages.send and gmail.users.threads.get before sending.'}
        message = EmailMessage(policy=SMTP)
        message['From'] = 'ap@company.example.com'
        message['To'] = arguments['to']
        message['Subject'] = arguments['subject']
        message.set_content(arguments['body'], subtype='plain', charset='utf-8', cte='8bit')
        encoded = self.remote(self.remote_names['base64_encode'], {'text': message.as_string()})
        if isinstance(encoded, str):
            try:
                parsed = json.loads(encoded)
                encoded = parsed
            except ValueError:
                pass
        if isinstance(encoded, dict):
            encoded = next((encoded[key] for key in ('encoded', 'base64', 'result', 'data') if isinstance(encoded.get(key), str)), None)
        if not isinstance(encoded, str) or not re.fullmatch(r'[A-Za-z0-9+/=_-]+', encoded.strip()):
            return {'error': 'Encoder returned an unsupported response; email not sent.'}
        payload = {'raw': encoded.strip().replace('+', '-').replace('/', '_').rstrip('=')}
        if arguments['thread_id']:
            payload['threadId'] = arguments['thread_id']
        sent = self.remote(self.remote_names['api_fetch'], {
            'method': 'POST', 'url': 'https://gmail.googleapis.com/gmail/v1/users/me/messages/send',
            'params': None, 'body': json.dumps(payload)})
        sent_data = json.loads(sent) if isinstance(sent, str) else sent
        thread = sent_data.get('threadId', sent_data.get('thread_id'))
        if not thread:
            return {'sent_response': sent_data, 'verification': 'unconfirmed; no thread ID returned. Inspect sent mail before retrying.'}
        observed = self.remote(self.remote_names['api_fetch'], {
            'method': 'GET', 'url': 'https://gmail.googleapis.com/gmail/v1/users/me/threads/' + thread,
            'params': json.dumps({'format': 'full'}), 'body': None})
        return {'sent_response': sent_data, 'independent_readback': observed}

    async def dispatch(self, name, arguments):
        if name == 'send_email_checked':
            return await asyncio.to_thread(self.send_email_checked, arguments)
        if name == 'exact_total':
            self.total = exact_total(arguments['amounts'])
            return self.total
        if name == 'decode_source':
            data = arguments['data']
            return {'text': base64.urlsafe_b64decode(data + '=' * (-len(data) % 4)).decode('utf-8')}
        if name == 'finish_report':
            computed = exact_total([entry['amount'] for entry in arguments['logged']])
            if arguments['status'] == 'complete':
                reported = exact_total([arguments['logged_total']])['total']
                if Decimal(reported.replace('$', '').replace(',', '')) != Decimal(computed['total'].replace('$', '').replace(',', '')):
                    raise ValueError('Reported total differs from verified logged rows; reconcile before finishing')
            ledger = {key: arguments[key] for key in ('logged', 'not_logged', 'logged_total', 'status')}
            self.final = arguments['notes'].strip() + '\n\n```json\n' + json.dumps(ledger, ensure_ascii=False) + '\n```'
            return {'finished': True}
        return await asyncio.to_thread(self.remote, name, arguments)

    async def run(self, instruction):
        definitions = tool_definitions(json.loads(Path('/run-input/tools.json').read_text()))
        for definition in definitions:
            for operation in ('api_search', 'api_fetch', 'base64_encode'):
                if operation in definition['name']:
                    self.remote_names[operation] = definition['name']
        instructions = Path(__file__).with_name('ap_instructions.txt').read_text()
        conversation = [{'role': 'system', 'content': instructions}, {'role': 'user', 'content': instruction}]
        client = AsyncOpenAI(base_url=os.environ['TASK_MODEL_API_BASE'], api_key=os.environ['TASK_MODEL_API_KEY'], max_retries=0, timeout=150)
        try:
            for turn in range(44):
                if time.monotonic() - self.started > 510:
                    conversation.append({'role': 'user', 'content': 'The execution deadline is near. Do not start new writes. Finish with the actual verified ledger and explain unfinished or unconfirmed work.'})
                if turn == 37 or self.calls >= 84:
                    conversation.append({'role': 'user', 'content': 'Budget is nearly exhausted. Prioritize verification of existing changes, the required summary, and finish_report. Avoid unrelated discovery.'})
                response = await client.responses.create(
                    model=os.environ['TASK_MODEL_NAME'], input=conversation, tools=definitions + LOCAL_TOOLS,
                    store=False, include=['reasoning.encrypted_content'])
                output = [item.model_dump(exclude_none=True) for item in response.output]
                conversation.extend(output)
                self.trace.append({'model_turn': turn, 'output': output})
                calls = [item for item in output if item['type'] in ('function_call', 'custom_tool_call')]
                if not calls:
                    conversation.append({'role': 'user', 'content': 'Return the final actual-action report using finish_report. If the job is not finished, continue the required work first. Do not stop at a plan.'})
                    continue
                for item in calls:
                    name = item['name']
                    arguments = None
                    try:
                        arguments = json.loads(item['arguments']) if item['type'] == 'function_call' else item['input']
                        result = await self.dispatch(name, arguments)
                    except StopBudget:
                        raise
                    except Exception as error:
                        result = {'error': str(error), 'instruction': 'Do not assume success. If this was a write/send, read the destination before retrying.'}
                    self.trace.append({'tool': name, 'arguments': arguments, 'result': result})
                    serialized = result if isinstance(result, str) else json.dumps(result, ensure_ascii=False)
                    conversation.append({'type': 'function_call_output' if item['type'] == 'function_call' else 'custom_tool_call_output', 'call_id': item['call_id'], 'output': serialized})
                    self.save_trace()
                    if self.final:
                        return self.final
            raise StopBudget('Model turn limit reached before final reporting')
        finally:
            await client.close()


async def main():
    supplied = json.load(sys.stdin)
    agent = DailyAgent()
    try:
        report = await agent.run(supplied['instruction'])
    except Exception as error:
        agent.save_trace()
        ledger = {'logged': [], 'not_logged': [], 'logged_total': 'unconfirmed', 'status': 'incomplete'}
        report = 'Processing stopped: ' + str(error) + '. External changes may have occurred; this fallback does not certify a complete invoice ledger. Consult the AP audit and destinations before retrying.\n\n```json\n' + json.dumps(ledger) + '\n```'
    print(json.dumps({'report': report}, ensure_ascii=False))


if __name__ == '__main__':
    asyncio.run(main())

import asyncio
import json
import os
import re
import sys
import time
from decimal import Decimal, InvalidOperation, localcontext
from pathlib import Path

import httpx
from openai import AsyncOpenAI


class StopRun(Exception):
    pass


def exact_total(amounts):
    with localcontext() as context:
        context.prec = 80
        total = Decimal(0)
        places = 2
        for amount in amounts:
            if not isinstance(amount, str):
                raise ValueError('Pass exact source amount strings, not floats.')
            value = amount.strip()
            value = re.sub(r'^USD\s*', '', value)
            value = re.sub(r'\s*USD$', '', value)
            value = value.removeprefix('$').strip()
            negative = value.startswith('(') and value.endswith(')')
            if negative:
                value = value[1:-1]
            if not re.fullmatch(r'[+-]?(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d+)?', value):
                raise ValueError(f'Ambiguous or non-dollar amount: {amount!r}')
            parsed = Decimal(value.replace(',', ''))
            if negative:
                parsed = -parsed
            total += parsed
            places = max(places, -parsed.as_tuple().exponent)
        return {'total': format(total, f'.{places}f'), 'logged_total': '$' + format(total, f'.{places}f'), 'count': len(amounts)}


def load_tools():
    raw = json.loads(Path('/run-input/tools.json').read_text())
    if isinstance(raw, dict):
        raw = raw.get('tools', raw)
    if isinstance(raw, dict):
        raw = [dict(value, name=value.get('name', name)) for name, value in raw.items()]
    definitions = []
    routes = {}
    for item in raw:
        specification = item.get('function', item)
        name = specification['name']
        local_name = re.sub(r'[^a-zA-Z0-9_-]', '_', name)
        if not any(part in name.lower() for part in ('api_search', 'api_fetch', 'base64_encode')):
            continue
        parameters = specification.get('parameters', specification.get('input_schema', specification.get('inputSchema', {'type': 'object', 'properties': {}})))
        definitions.append({'type': 'function', 'name': local_name, 'description': specification.get('description', ''), 'parameters': parameters, 'strict': False})
        routes[local_name] = name
    if not definitions:
        raise ValueError('No supplied api_search/api_fetch tools were found.')
    return definitions, routes


def local_tools():
    return [
        {'type': 'function', 'name': 'exact_total', 'description': 'Sum exact dollar amount strings without rounding; use only newly logged, verified invoices.', 'parameters': {'type': 'object', 'properties': {'amounts': {'type': 'array', 'items': {'type': 'string'}}}, 'required': ['amounts'], 'additionalProperties': False}},
        {'type': 'function', 'name': 'finish_report', 'description': 'Finish with the factual user-facing narrative and the required machine-readable accounting. Use only actual confirmed actions. This ends the run.', 'parameters': {'type': 'object', 'properties': {
            'narrative': {'type': 'string'},
            'logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': {'type': 'string'}, 'amount': {'type': 'string'}}, 'required': ['invoice', 'amount'], 'additionalProperties': False}},
            'not_logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': {'type': 'string'}, 'reason': {'type': 'string'}}, 'required': ['invoice', 'reason'], 'additionalProperties': False}},
            'logged_total': {'type': 'string'},
            'status': {'type': 'string', 'enum': ['complete', 'incomplete']}
        }, 'required': ['narrative', 'logged', 'not_logged', 'logged_total', 'status'], 'additionalProperties': False}}
    ]


def render_report(arguments):
    logged = arguments['logged']
    expected = exact_total([record['amount'] for record in logged])['logged_total']
    actual = arguments['logged_total']
    if actual and exact_total([actual])['logged_total'] != expected:
        arguments['status'] = 'incomplete'
        arguments['narrative'] += f' The reported total {actual} does not match the confirmed logged sum {expected}; review is required.'
    if not actual:
        arguments['status'] = 'incomplete'
    data = {key: arguments[key] for key in ('logged', 'not_logged', 'logged_total', 'status')}
    return arguments['narrative'].strip() + '\n\n```json\n' + json.dumps(data, ensure_ascii=False) + '\n```'


async def main():
    inputs = json.load(sys.stdin)
    instruction = inputs['instruction']
    started = time.monotonic()
    definitions, routes = load_tools()
    definitions.extend(local_tools())
    prompt = Path(__file__).with_name('ap_prompt.txt').read_text()
    conversation = [{'role': 'system', 'content': prompt}, {'role': 'user', 'content': instruction}]
    client = AsyncOpenAI(base_url=os.environ['TASK_MODEL_API_BASE'], api_key=os.environ['TASK_MODEL_API_KEY'], max_retries=0, timeout=140)
    report = None
    calls_used = 0
    ledger = []
    output_dir = Path(os.environ.get('METHOD_OUTPUT_DIR', '/tmp/ap-intake'))
    output_dir.mkdir(parents=True, exist_ok=True)
    async with httpx.AsyncClient(timeout=55) as transport:
        async def invoke(call):
            nonlocal calls_used
            arguments = json.loads(call.arguments)
            if call.name == 'exact_total':
                return exact_total(arguments['amounts'])
            if call.name not in routes:
                return {'error': 'Unknown tool.'}
            if calls_used >= 90 or time.monotonic() - started > 530:
                return {'error': 'Execution limit reached. Stop app calls and report actual work as incomplete.'}
            calls_used += 1
            response = await transport.post(os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call', headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN']}, json={'name': routes[call.name], 'arguments': arguments})
            if response.status_code == 402:
                raise StopRun('HTTP 402: execution budget exhausted.')
            response.raise_for_status()
            result = response.json()
            payload = result.get('result', result)
            ledger.append({'tool': routes[call.name], 'arguments': arguments, 'result': payload})
            with (output_dir / 'actions.jsonl').open('a') as handle:
                handle.write(json.dumps(ledger[-1], ensure_ascii=False) + '\n')
            return payload

        try:
            for turn in range(45):
                if time.monotonic() - started > 545:
                    break
                if turn == 38 or calls_used >= 78:
                    conversation.append({'role': 'system', 'content': 'Budget is nearly exhausted. Prioritize required verification, summary, and finish_report now. Do not start unrelated discovery.'})
                response = await client.responses.create(model=os.environ['TASK_MODEL_NAME'], input=conversation, tools=definitions, store=False, include=['reasoning.encrypted_content'])
                conversation.extend(item.model_dump(exclude_none=True) for item in response.output)
                tool_calls = [item for item in response.output if item.type == 'function_call']
                if not tool_calls:
                    if response.output_text:
                        conversation.append({'role': 'user', 'content': 'Please use finish_report to return your final factual report and required JSON. Do not repeat completed actions.'})
                    else:
                        conversation.append({'role': 'user', 'content': 'Continue the AP task or use finish_report if blocked.'})
                    continue
                for call in tool_calls:
                    try:
                        if call.name == 'finish_report':
                            report = render_report(json.loads(call.arguments))
                            break
                        result = await invoke(call)
                    except StopRun:
                        raise
                    except Exception as error:
                        result = {'error': str(error), 'warning': 'If this was a write, its outcome may be uncertain. Read the target before retrying.'}
                    conversation.append({'type': 'function_call_output', 'call_id': call.call_id, 'output': result if isinstance(result, str) else json.dumps(result, ensure_ascii=False)})
                if report is not None:
                    break
        except Exception as error:
            print(f'AP execution stopped: {type(error).__name__}: {error}', file=sys.stderr)
        finally:
            (output_dir / 'conversation.json').write_text(json.dumps(conversation, ensure_ascii=False))
            await client.close()
    if report is None:
        report = 'The run stopped before a verified final reconciliation. Do not assume no changes occurred; inspect the Invoice Tracker and sent mail before rerunning. The saved action trace records attempted work. No complete final accounting or emailed total could be confirmed.\n\n```json\n' + json.dumps({'logged': [], 'not_logged': [], 'logged_total': '', 'status': 'incomplete'}) + '\n```'
    print(json.dumps({'report': report}, ensure_ascii=False))


if __name__ == '__main__':
    try:
        asyncio.run(main())
    except Exception as error:
        print(json.dumps({'report': 'AP processing could not start: ' + str(error) + '\n\n```json\n' + json.dumps({'logged': [], 'not_logged': [], 'logged_total': '', 'status': 'incomplete'}) + '\n```'}))

import asyncio
import base64
import json
import os
import re
import sys
import time
from decimal import Decimal
from pathlib import Path
from urllib.error import HTTPError
from urllib.request import Request, urlopen

from openai import AsyncOpenAI


class BudgetStop(Exception):
    pass


def bridge(name, arguments):
    request = Request(
        os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call',
        data=json.dumps({'name': name, 'arguments': arguments}).encode(),
        headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN'],
                 'Content-Type': 'application/json'}, method='POST')
    try:
        with urlopen(request, timeout=45) as response:
            return json.load(response).get('result', '')
    except HTTPError as error:
        if error.code == 402:
            raise BudgetStop('Tool service budget exhausted (HTTP 402).') from error
        return json.dumps({'error': str(error), 'body': error.read().decode(errors='replace'),
                           'warning': 'Read the target before retrying an uncertain write.'})
    except Exception as error:
        return json.dumps({'error': str(error),
                           'warning': 'Outcome unknown if this was a write. Read target before retrying.'})


def normalize_tools(source):
    if isinstance(source, dict):
        if 'tools' in source:
            source = source['tools']
        elif 'name' in source:
            source = [source]
        else:
            source = [dict(value, name=key) for key, value in source.items() if isinstance(value, dict)]
    normalized = []
    for item in source:
        definition = item.get('function', item)
        name = definition.get('name', '')
        if not any(part in name.lower() for part in ['api_search', 'api_fetch', 'base64_encode']):
            continue
        if item.get('type') == 'custom':
            normalized.append(item)
        else:
            normalized.append({'type': 'function', 'name': name,
                               'description': definition.get('description', ''),
                               'parameters': definition.get('parameters', definition.get('input_schema', definition.get('inputSchema', {'type': 'object', 'properties': {}}))),
                               'strict': False})
    if not normalized:
        raise ValueError('No simulated API tools were supplied.')
    return normalized


def amount_decimal(raw):
    value = raw.strip()
    value = re.sub(r'^(?:USD\s*|\$\s*)', '', value)
    value = re.sub(r'\s*USD$', '', value).strip()
    negative = value.startswith('(') and value.endswith(')')
    if negative:
        value = value[1:-1]
    if not re.fullmatch(r'[+-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?', value):
        raise ValueError('Ambiguous or unsupported USD amount: ' + raw)
    result = Decimal(value.replace(',', ''))
    return -result if negative else result


def exact_sum(amounts):
    total = sum((amount_decimal(value) for value in amounts), Decimal('0'))
    places = max(2, -total.as_tuple().exponent)
    return {'total': '$' + format(total, f'.{places}f'), 'amounts': amounts}


def decode_payload(value):
    return base64.urlsafe_b64decode(value + '=' * (-len(value) % 4)).decode('utf-8')


def collect_values(value, strings, rows, depth=0):
    if depth > 12:
        return
    if isinstance(value, dict):
        for child in value.values():
            collect_values(child, strings, rows, depth + 1)
    elif isinstance(value, list):
        if all(not isinstance(child, (dict, list)) for child in value):
            rows.append([str(child) for child in value])
        for child in value:
            collect_values(child, strings, rows, depth + 1)
    elif isinstance(value, str):
        strings.append(value)
        try:
            parsed = json.loads(value)
            if parsed != value:
                collect_values(parsed, strings, rows, depth + 1)
        except (ValueError, TypeError):
            pass
        if len(value) >= 8 and re.fullmatch(r'[A-Za-z0-9_+/=-]+', value):
            try:
                decoded = decode_payload(value)
                if decoded != value:
                    collect_values(decoded, strings, rows, depth + 1)
            except (ValueError, UnicodeError):
                pass


def read_only(arguments):
    for key, value in arguments.items():
        if key.lower() in ['method', 'http_method'] and str(value).upper() not in ['GET', 'HEAD']:
            return False
    serialized = json.dumps(arguments).lower()
    return not any(token in serialized for token in ['/send', '/append', '/batchupdate', '/delete', '/trash', '/modify'])


def function(name, description, properties, required):
    return {'type': 'function', 'name': name, 'description': description,
            'parameters': {'type': 'object', 'properties': properties, 'required': required}, 'strict': False}


def local_tools():
    string = {'type': 'string'}
    strings = {'type': 'array', 'items': string}
    invoice = {'type': 'object', 'properties': {'invoice': string, 'amount': string}, 'required': ['invoice', 'amount']}
    skipped = {'type': 'object', 'properties': {'invoice': string, 'reason': string}, 'required': ['invoice', 'reason']}
    verification_fields = {
        'kind': {'type': 'string', 'enum': ['sheet', 'return_email', 'summary_email']},
        'description': string, 'tool_name': string,
        'arguments': {'type': 'object', 'additionalProperties': True},
        'expected_text': strings,
        'expected_rows': {'type': 'array', 'items': strings}}
    finish_fields = {
        'narrative': string, 'logged': {'type': 'array', 'items': invoice},
        'not_logged': {'type': 'array', 'items': skipped}, 'logged_total': string,
        'status': {'type': 'string', 'enum': ['complete', 'incomplete']},
        'uncertainties': strings,
        'verifications': {'type': 'array', 'items': {'type': 'object', 'properties': verification_fields, 'required': list(verification_fields)}}}
    return [
        function('exact_sum', 'Sum verbatim USD amounts with Decimal, without rounding. Rejects ambiguous inputs.', {'amounts': strings}, ['amounts']),
        function('decode_payload', 'Decode base64 or base64url MIME body text locally as UTF-8.', {'value': string}, ['value']),
        function('finish_ap_run', 'Finish from actual outcomes. Independently reads changed apps with supplied read-only api_fetch arguments. For sheets provide exact expected_rows; for mail expected_text must include recipient and essential body text. Failed checks return diagnostics so you can fix the check or report incomplete. Never performs writes.', finish_fields, list(finish_fields))]


async def finish(arguments, tool_names, counter):
    expected_total = exact_sum([entry['amount'] for entry in arguments['logged']])['total']
    if arguments['logged_total'] != expected_total:
        return None, {'error': 'Total does not equal newly logged amounts.', 'expected_total': expected_total}
    verifications = arguments['verifications']
    kinds = {item['kind'] for item in verifications}
    if arguments['status'] == 'complete':
        if 'summary_email' not in kinds or (arguments['logged'] and 'sheet' not in kinds):
            return None, {'error': 'Complete requires summary verification and sheet verification for logged rows.'}
        if arguments['uncertainties']:
            return None, {'error': 'Use incomplete status for unresolved uncertainties.'}
    evidence = []
    for item in verifications:
        if item['tool_name'] not in tool_names or 'api_fetch' not in item['tool_name'].lower() or not read_only(item['arguments']):
            return None, {'error': 'Verification must use read-only api_fetch.'}
        if not item['expected_text'] and not item['expected_rows']:
            return None, {'error': 'Supply expected saved contents, not just a receipt.'}
        if counter[0] >= 94:
            return None, {'error': 'Tool budget exhausted; finalize incomplete without further verification requests.'}
        counter[0] += 1
        result = await asyncio.to_thread(bridge, item['tool_name'], item['arguments'])
        strings, rows = [], []
        collect_values(result, strings, rows)
        haystack = '\n'.join(strings)
        missing_text = [value for value in item['expected_text'] if value not in haystack]
        missing_rows = [row for row in item['expected_rows'] if row not in rows]
        evidence.append({'kind': item['kind'], 'description': item['description'],
                         'confirmed': not missing_text and not missing_rows,
                         'missing_text': missing_text, 'missing_rows': missing_rows,
                         'read_arguments': item['arguments'], 'observation': result})
    failed = [item for item in evidence if not item['confirmed']]
    if failed and arguments['status'] == 'complete':
        return None, {'error': 'Read-back verification failed. Inspect observations; never blindly repeat writes. Correct the check or report incomplete.', 'evidence': failed}
    narrative = arguments['narrative'].rstrip()
    if failed:
        narrative += '\nUnconfirmed: ' + '; '.join(item['description'] for item in failed) + '.'
    if arguments['uncertainties']:
        narrative += '\nNeeds review: ' + '; '.join(arguments['uncertainties'])
    public = {key: arguments[key] for key in ['logged', 'not_logged', 'logged_total', 'status']}
    return {'report': narrative + '\n\n```json\n' + json.dumps(public, ensure_ascii=False) + '\n```',
            'evidence': json.dumps({'status': arguments['status'], 'checks': evidence, 'uncertainties': arguments['uncertainties']}, ensure_ascii=False)}, {'finished': True}


async def main(inputs):
    start = time.monotonic()
    definitions = normalize_tools(json.loads(Path('/run-input/tools.json').read_text()))
    tool_names = {item['name'] for item in definitions}
    instructions = Path(__file__).with_name('ap_instructions.txt').read_text()
    conversation = [{'role': 'system', 'content': instructions}, {'role': 'user', 'content': inputs['instruction']}]
    client = AsyncOpenAI(base_url=os.environ['TASK_MODEL_API_BASE'], api_key=os.environ['TASK_MODEL_API_KEY'], max_retries=0, timeout=110)
    counter = [0]
    transcript = []
    final_attempt = None
    error_message = ''
    try:
        for turn in range(40):
            if time.monotonic() - start > 480 or counter[0] > 89:
                conversation.append({'role': 'user', 'content': 'Execution budget nearly exhausted. Do not start new business actions. Call finish_ap_run with honest actual results. Mark unconfirmed actions incomplete.'})
            response = await client.responses.create(model=os.environ['TASK_MODEL_NAME'], input=conversation, tools=definitions + local_tools(), store=False, include=['reasoning.encrypted_content'])
            outputs = [item.model_dump(exclude_none=True) for item in response.output]
            conversation.extend(outputs)
            calls = [item for item in outputs if item['type'] in ['function_call', 'custom_tool_call']]
            if not calls:
                conversation.append({'role': 'user', 'content': 'Finish by calling finish_ap_run with actual outcomes and verification reads. If blocked, report incomplete and explain actions actually taken.'})
                continue
            for call in calls:
                name = call['name']
                arguments = {}
                try:
                    arguments = json.loads(call['arguments']) if call['type'] == 'function_call' else call['input']
                    if name == 'finish_ap_run':
                        final_attempt = arguments
                        completed, result = await finish(arguments, tool_names, counter)
                        if completed:
                            return completed
                    elif name == 'exact_sum':
                        result = exact_sum(arguments['amounts'])
                    elif name == 'decode_payload':
                        result = {'text': decode_payload(arguments['value'])}
                    elif name in tool_names:
                        if counter[0] >= 94:
                            result = {'error': 'Tool limit reached. Finish incomplete from actual observations.'}
                        else:
                            counter[0] += 1
                            result = await asyncio.to_thread(bridge, name, arguments)
                    else:
                        result = {'error': 'Unknown tool.'}
                except BudgetStop:
                    raise
                except Exception as error:
                    result = {'error': str(error)}
                transcript.append({'name': name, 'arguments': arguments, 'result': result})
                conversation.append({'type': 'function_call_output' if call['type'] == 'function_call' else 'custom_tool_call_output', 'call_id': call['call_id'], 'output': result if isinstance(result, str) else json.dumps(result, ensure_ascii=False)})
            if time.monotonic() - start > 535:
                error_message = 'Execution time limit reached.'
                break
    except Exception as error:
        error_message = 'Processing stopped: ' + str(error)
    finally:
        output_dir = Path(os.environ.get('METHOD_OUTPUT_DIR', '/tmp'))
        output_dir.mkdir(parents=True, exist_ok=True)
        (output_dir / 'ap-tool-history.json').write_text(json.dumps(transcript, ensure_ascii=False))
        await client.close()
    if final_attempt:
        public = {key: final_attempt[key] for key in ['logged', 'not_logged', 'logged_total']}
        narrative = final_attempt.get('narrative', '')
    else:
        public = {'logged': [], 'not_logged': [], 'logged_total': 'unconfirmed'}
        narrative = 'The run stopped before verified final accounting was available. Some changes may have committed; inspect the spreadsheet and sent mail before rerunning.'
    public['status'] = 'incomplete'
    return {'report': narrative + '\n' + (error_message or 'Verification was not completed.') + '\n\n```json\n' + json.dumps(public, ensure_ascii=False) + '\n```',
            'evidence': json.dumps({'status': 'incomplete', 'checks': [], 'uncertainties': [error_message or 'Unfinished run']})}


if __name__ == '__main__':
    try:
        print(json.dumps(asyncio.run(main(json.load(sys.stdin))), ensure_ascii=False))
    except Exception as error:
        print(json.dumps({'report': 'Unable to start AP processing: ' + str(error) + '\n\n```json\n' + json.dumps({'logged': [], 'not_logged': [], 'logged_total': 'unconfirmed', 'status': 'incomplete'}) + '\n```', 'evidence': json.dumps({'status': 'incomplete', 'checks': [], 'uncertainties': [str(error)]})}))

import asyncio
import json
import os
import re
import sys
import time
from decimal import Decimal, InvalidOperation, localcontext
from pathlib import Path

import httpx
from openai import AsyncOpenAI


def exact_total(amounts):
    numbers = []
    for amount in amounts:
        if not isinstance(amount, str):
            raise ValueError('Amounts must be verbatim strings, not numeric literals.')
        value = amount.strip()
        negative = value.startswith('(') and value.endswith(')')
        if negative:
            value = value[1:-1].strip()
        value = re.sub(r'^(?:USD\s*|US\$\s*|\$\s*)', '', value)
        value = re.sub(r'\s*USD$', '', value).strip()
        if not re.fullmatch(r'[+-]?(?:[0-9]+|[0-9]{1,3}(?:,[0-9]{3})+)(?:\.[0-9]+)?', value):
            raise ValueError('Unrecognized USD amount; do not guess currency or decimal separators: ' + amount)
        try:
            number = Decimal(value.replace(',', ''))
        except InvalidOperation as error:
            raise ValueError('Invalid amount: ' + amount) from error
        numbers.append(-number if negative else number)
    with localcontext() as context:
        context.prec = max(60, sum(len(str(number)) for number in numbers) + 10)
        total = sum(numbers, Decimal('0.00'))
    return {'amounts': amounts, 'total': '$' + format(total, 'f'), 'numeric_total': format(total, 'f')}


def normalize_tools(raw):
    if isinstance(raw, dict):
        raw = raw.get('tools', raw.get('definitions', raw))
    if isinstance(raw, dict):
        raw = [dict(value, name=value.get('name', key)) for key, value in raw.items() if isinstance(value, dict)]
    result = []
    for entry in raw:
        tool = entry.get('function', entry)
        if tool.get('type') == 'custom' or entry.get('type') == 'custom':
            result.append({key: value for key, value in tool.items() if key in ('type', 'name', 'description', 'format')})
            continue
        name = tool.get('name')
        if not name:
            continue
        result.append({'type': 'function', 'name': name, 'description': tool.get('description', ''),
                       'parameters': tool.get('parameters', tool.get('input_schema', tool.get('inputSchema', {'type': 'object', 'properties': {}}))),
                       'strict': False})
    if not result:
        raise ValueError('No simulated tool definitions available.')
    return result


LOCAL_TOOLS = [
    {'type': 'function', 'name': 'exact_total', 'description': 'Compute an exact USD sum from verbatim source amount strings. No rounding; does not change any app.',
     'parameters': {'type': 'object', 'properties': {'amounts': {'type': 'array', 'items': {'type': 'string'}}}, 'required': ['amounts'], 'additionalProperties': False}, 'strict': False},
    {'type': 'function', 'name': 'finish_report', 'description': 'Finish this run with an honest action report and required JSON ledger. Call only after all possible actions and read-back verification. Amounts must equal values actually logged. No app changes.',
     'parameters': {'type': 'object', 'properties': {
         'narrative': {'type': 'string', 'description': 'Concise user-facing account of actual actions, reasons for exclusions, policy updates applied, sent summary and any failures.'},
         'logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': {'type': 'string'}, 'amount': {'type': 'string'}}, 'required': ['invoice', 'amount'], 'additionalProperties': False}},
         'not_logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': {'type': 'string'}, 'reason': {'type': 'string'}}, 'required': ['invoice', 'reason'], 'additionalProperties': False}},
         'logged_total': {'type': 'string', 'description': 'Exact total string reported in the summary email, including $. Empty if none was reported.'},
         'summary_verified': {'type': 'boolean', 'description': 'True only after independently reading the sent summary recipient and body.'},
         'effects_verified': {'type': 'boolean', 'description': 'True only if all logged rows and required returned emails were independently read back and matched.'},
         'status': {'type': 'string', 'enum': ['complete', 'incomplete']}
     }, 'required': ['narrative', 'logged', 'not_logged', 'logged_total', 'summary_verified', 'effects_verified', 'status'], 'additionalProperties': False}, 'strict': False}
]


def make_report(arguments):
    total = exact_total([entry['amount'] for entry in arguments['logged']])['total']
    supplied = arguments['logged_total']
    if supplied and exact_total([supplied])['total'] != total:
        if Decimal(exact_total([supplied])['numeric_total']) != Decimal(exact_total([total])['numeric_total']):
            raise ValueError('Reported total does not match logged amounts. Correct the summary email before claiming complete.')
    if arguments['status'] == 'complete' and (not supplied or not arguments['summary_verified'] or not arguments['effects_verified']):
        raise ValueError('Complete requires a reported total, verified summary, and verified external effects.')
    ledger = {key: arguments[key] for key in ('logged', 'not_logged', 'logged_total', 'status')}
    return arguments['narrative'].strip() + '\n\n```json\n' + json.dumps(ledger, ensure_ascii=False) + '\n```'


async def run_agent(instruction):
    definitions = normalize_tools(json.loads(Path('/run-input/tools.json').read_text()))
    allowed = {tool['name'] for tool in definitions}
    prompt = Path(__file__).with_name('ap_prompt.txt').read_text()
    history = [{'role': 'system', 'content': prompt}, {'role': 'user', 'content': instruction}]
    output_dir = Path(os.environ.get('METHOD_OUTPUT_DIR', '/workspace/run-output'))
    output_dir.mkdir(parents=True, exist_ok=True)
    trace_path = output_dir / 'ap-trace.jsonl'
    def trace(entry):
        with trace_path.open('a') as handle:
            handle.write(json.dumps(entry, ensure_ascii=False) + '\n')
    client = AsyncOpenAI(base_url=os.environ['TASK_MODEL_API_BASE'], api_key=os.environ['TASK_MODEL_API_KEY'], max_retries=0, timeout=240.0)
    deadline = time.monotonic() + 545
    tool_count = 0
    last_text = ''
    async with httpx.AsyncClient(timeout=60.0) as http:
        for turn in range(45):
            if time.monotonic() >= deadline:
                break
            if turn == 36 or tool_count >= 82:
                history.append({'role': 'user', 'content': 'Execution budget is nearly exhausted. Prioritize verification, the required summary, then finish_report. Report any remaining uncertainty as incomplete. Do not claim unperformed actions.'})
            try:
                stream = await client.responses.create(model=os.environ['TASK_MODEL_NAME'], input=history, tools=definitions + LOCAL_TOOLS, store=False, include=['reasoning.encrypted_content'], stream=True)
                response = None
                async for event in stream:
                    if event.type == 'response.completed':
                        response = event.response
                    elif event.type in ('response.failed', 'error'):
                        raise RuntimeError(str(event))
                if response is None:
                    raise RuntimeError('Model stream ended without a completed response.')
            except Exception as error:
                trace({'model_error': str(error)})
                if getattr(error, 'status_code', None) == 402:
                    break
                raise
            items = [item.model_dump(exclude_none=True) for item in response.output]
            history.extend(items)
            trace({'turn': turn, 'output': items})
            calls = [item for item in items if item['type'] in ('function_call', 'custom_tool_call')]
            if not calls:
                last_text = response.output_text
                history.append({'role': 'user', 'content': 'Use finish_report to return the final action ledger now if done. Otherwise continue the necessary simulated tool calls. Do not fabricate completion.'})
                continue
            for call in calls:
                name = call['name']
                raw_arguments = call.get('arguments', call.get('input', '{}'))
                try:
                    arguments = json.loads(raw_arguments) if call['type'] == 'function_call' else raw_arguments
                    if name == 'exact_total':
                        result = exact_total(arguments['amounts'])
                    elif name == 'finish_report':
                        report = make_report(arguments)
                        trace({'final': arguments})
                        await client.close()
                        return report
                    elif name in allowed:
                        if tool_count >= 95:
                            result = {'error': 'Tool budget exhausted. Stop app calls and report incomplete.'}
                        else:
                            tool_count += 1
                            trace({'tool_call': name, 'arguments': arguments, 'sequence': tool_count})
                            response_http = await http.post(os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call', headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN']}, json={'name': name, 'arguments': arguments})
                            if response_http.status_code == 402:
                                raise BudgetExhausted()
                            response_http.raise_for_status()
                            payload = response_http.json()
                            result = payload.get('result', payload)
                    else:
                        result = {'error': 'Unknown tool.'}
                except BudgetExhausted:
                    await client.close()
                    return fallback_report('Execution budget exhausted; some actions may have completed. Review the run trace and live apps before retrying.', last_text)
                except Exception as error:
                    result = {'error': str(error), 'recovery': 'Do not assume success or failure of a write. Read the app state before retrying. Do not automatically retry a send or append.'}
                output = result if isinstance(result, str) else json.dumps(result, ensure_ascii=False)
                trace({'tool_result': name, 'output': output})
                history.append({'type': 'custom_tool_call_output' if call['type'] == 'custom_tool_call' else 'function_call_output', 'call_id': call['call_id'], 'output': output})
    await client.close()
    return fallback_report('Execution stopped before a fully verified report was available. Review the run trace and live apps before retrying any writes.', last_text)


class BudgetExhausted(Exception):
    pass


def fallback_report(reason, last_text=''):
    ledger = {'logged': [], 'not_logged': [], 'logged_total': '', 'status': 'incomplete'}
    return reason + ' The empty ledger indicates unconfirmed results, not that no actions occurred.' + ('\n\nLast agent note (not independently confirmed):\n' + last_text if last_text else '') + '\n\n```json\n' + json.dumps(ledger) + '\n```'


def main():
    try:
        payload = json.load(sys.stdin)
        report = asyncio.run(run_agent(payload['instruction']))
    except Exception as error:
        print(type(error).__name__ + ': ' + str(error), file=sys.stderr)
        report = fallback_report('The AP run stopped due to an execution error: ' + type(error).__name__ + '. No unverified action is claimed complete.')
    print(json.dumps({'report': report}, ensure_ascii=False))


if __name__ == '__main__':
    main()

import asyncio
import base64
import json
import os
import re
import sys
import time
from decimal import Decimal
from pathlib import Path
from urllib.error import HTTPError
from urllib.request import Request, urlopen

from openai import AsyncOpenAI


class BudgetStop(Exception):
    pass


def bridge(name, arguments):
    request = Request(
        os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call',
        data=json.dumps({'name': name, 'arguments': arguments}).encode(),
        headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN'],
                 'Content-Type': 'application/json'}, method='POST')
    try:
        with urlopen(request, timeout=45) as response:
            return json.load(response).get('result', '')
    except HTTPError as error:
        if error.code == 402:
            raise BudgetStop('Tool service budget exhausted (HTTP 402).') from error
        return json.dumps({'error': str(error), 'body': error.read().decode(errors='replace'),
                           'warning': 'Read the target before retrying an uncertain write.'})
    except Exception as error:
        return json.dumps({'error': str(error),
                           'warning': 'Outcome unknown if this was a write. Read target before retrying.'})


def normalize_tools(source):
    if isinstance(source, dict):
        if 'tools' in source:
            source = source['tools']
        elif 'name' in source:
            source = [source]
        else:
            source = [dict(value, name=key) for key, value in source.items() if isinstance(value, dict)]
    normalized = []
    for item in source:
        definition = item.get('function', item)
        name = definition.get('name', '')
        if not any(part in name.lower() for part in ['api_search', 'api_fetch', 'base64_encode']):
            continue
        if item.get('type') == 'custom':
            normalized.append(item)
        else:
            normalized.append({'type': 'function', 'name': name,
                               'description': definition.get('description', ''),
                               'parameters': definition.get('parameters', definition.get('input_schema', definition.get('inputSchema', {'type': 'object', 'properties': {}}))),
                               'strict': False})
    if not normalized:
        raise ValueError('No simulated API tools were supplied.')
    return normalized


def amount_decimal(raw):
    value = raw.strip()
    value = re.sub(r'^(?:USD\s*|\$\s*)', '', value)
    value = re.sub(r'\s*USD$', '', value).strip()
    negative = value.startswith('(') and value.endswith(')')
    if negative:
        value = value[1:-1]
    if not re.fullmatch(r'[+-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?', value):
        raise ValueError('Ambiguous or unsupported USD amount: ' + raw)
    result = Decimal(value.replace(',', ''))
    return -result if negative else result


def exact_sum(amounts):
    total = sum((amount_decimal(value) for value in amounts), Decimal('0'))
    places = max(2, -total.as_tuple().exponent)
    return {'total': '$' + format(total, f',.{places}f'), 'amounts': amounts}


def decode_payload(value):
    return base64.urlsafe_b64decode(value + '=' * (-len(value) % 4)).decode('utf-8')


def collect_values(value, strings, rows, depth=0):
    if depth > 12:
        return
    if isinstance(value, dict):
        for child in value.values():
            collect_values(child, strings, rows, depth + 1)
    elif isinstance(value, list):
        if all(not isinstance(child, (dict, list)) for child in value):
            rows.append([str(child) for child in value])
        for child in value:
            collect_values(child, strings, rows, depth + 1)
    elif isinstance(value, str):
        strings.append(value)
        try:
            parsed = json.loads(value)
            if parsed != value:
                collect_values(parsed, strings, rows, depth + 1)
        except (ValueError, TypeError):
            pass
        if len(value) >= 8 and re.fullmatch(r'[A-Za-z0-9_+/=-]+', value):
            try:
                decoded = decode_payload(value)
                if decoded != value:
                    collect_values(decoded, strings, rows, depth + 1)
            except (ValueError, UnicodeError):
                pass


def read_only(arguments):
    for key, value in arguments.items():
        if key.lower() in ['method', 'http_method'] and str(value).upper() not in ['GET', 'HEAD']:
            return False
    serialized = json.dumps(arguments).lower()
    return not any(token in serialized for token in ['/send', '/append', '/batchupdate', '/delete', '/trash', '/modify'])


def function(name, description, properties, required):
    return {'type': 'function', 'name': name, 'description': description,
            'parameters': {'type': 'object', 'properties': properties, 'required': required}, 'strict': False}


class RunLedger:
    def __init__(self):
        self.invoices = {}
        self.checks = []

    def record(self, entries):
        for entry in entries:
            previous = self.invoices.get(entry['invoice'], {})
            if previous.get('status') == 'logged':
                continue
            self.invoices[entry['invoice']] = {**entry, 'status': 'not_logged'}
        return self.public()

    def public(self):
        logged = [{'invoice': entry['invoice'], 'amount': entry['amount']}
                  for entry in self.invoices.values() if entry['status'] == 'logged']
        not_logged = [{'invoice': entry['invoice'], 'reason': entry['reason']}
                      for entry in self.invoices.values() if entry['status'] != 'logged']
        return {'logged': logged, 'not_logged': not_logged,
                'logged_total': exact_sum([entry['amount'] for entry in logged])['total']}


def saved_rows(result):
    if isinstance(result, str):
        try:
            return saved_rows(json.loads(result))
        except ValueError:
            return None
    if isinstance(result, dict):
        if result.get('error') or result.get('isError'):
            return None
        if isinstance(result.get('values'), list):
            return [[str(cell) for cell in row] for row in result['values'] if isinstance(row, list)]
        if 'range' in result and not result.get('values'):
            return []
        for child in result.values():
            found = saved_rows(child)
            if found is not None:
                return found
    if isinstance(result, list):
        for child in result:
            found = saved_rows(child)
            if found is not None:
                return found
    return None


def single_row_payload(value, row):
    if isinstance(value, str):
        try:
            return single_row_payload(json.loads(value), row)
        except ValueError:
            return False
    if isinstance(value, dict):
        if 'values' in value:
            return value['values'] == [row]
        return any(single_row_payload(child, row) for child in value.values())
    return False


async def append_invoice_rows(arguments, tool_names, counter, ledger, transcript):
    name = arguments['tool_name']
    read_arguments = arguments['read_arguments']
    entries = arguments['invoices']
    vendor_column = arguments['vendor_column']
    invoice_column = arguments['invoice_column']
    if name not in tool_names or 'api_fetch' not in name.lower() or not read_only(read_arguments):
        return {'error': 'Supply discovered api_fetch and read-only sheet arguments.'}
    for entry in entries:
        row = entry['row']
        if (min(vendor_column, invoice_column) < 0 or max(vendor_column, invoice_column) >= len(row)
                or row[invoice_column] != entry['invoice'] or entry['amount'] not in row
                or not single_row_payload(entry['append_arguments'], row)
                or 'RAW' not in json.dumps(entry['append_arguments'])):
            return {'error': 'Each append must contain exactly its one RAW row, with correct zero-based vendor/invoice columns and verbatim amount.'}
    if counter[0] + len(entries) + 2 > 84:
        return {'error': 'Insufficient remaining app calls for all rows and summary; reduce this group.'}

    async def fetch(fetch_arguments):
        counter[0] += 1
        result = await asyncio.to_thread(bridge, name, fetch_arguments)
        transcript.append({'name': name, 'arguments': fetch_arguments, 'result': result})
        return result

    initial = await fetch(read_arguments)
    before = saved_rows(initial)
    if before is None:
        return {'error': 'Cannot read existing spreadsheet values; no writes attempted.', 'observation': initial}
    outcomes = []
    attempted = []
    seen = {(row[vendor_column], row[invoice_column]) for row in before
            if len(row) > max(vendor_column, invoice_column)}
    for entry in entries:
        row = entry['row']
        key = (row[vendor_column], entry['invoice'])
        if key in seen:
            if ledger.invoices.get(entry['invoice'], {}).get('status') != 'logged':
                ledger.record([{**entry, 'reason': 'Already present in Pending Invoices; not newly logged.'}])
            outcomes.append({'invoice': entry['invoice'], 'outcome': 'duplicate; not appended'})
            continue
        seen.add(key)
        ledger.record([{**entry, 'reason': 'Append attempted; saved outcome not yet confirmed. Amount: ' + entry['amount']}])
        result = await fetch(entry['append_arguments'])
        attempted.append((entry, result))
    observation = await fetch(read_arguments)
    after = saved_rows(observation)
    confirmed_rows = []
    for entry, result in attempted:
        confirmed = after is not None and entry['row'] in after
        if confirmed:
            ledger.invoices[entry['invoice']] = {**entry, 'status': 'logged', 'reason': ''}
            confirmed_rows.append(entry['row'])
        else:
            reason = ('Not logged: row absent from Pending Invoices after its individual append attempt.'
                      if after is not None else 'Not confirmed logged: spreadsheet read-back failed.')
            ledger.record([{**entry, 'reason': reason + ' Amount: ' + entry['amount']
                           + ' Append response: ' + (result if isinstance(result, str) else json.dumps(result))}])
        outcomes.append({'invoice': entry['invoice'], 'amount': entry['amount'],
                         'confirmed_logged': confirmed, 'append_response': result})
    if confirmed_rows:
        ledger.checks.append({'kind': 'sheet', 'description': 'Individual invoice appends read back from Pending Invoices',
                              'confirmed': True, 'expected_rows': confirmed_rows,
                              'read_arguments': read_arguments, 'observation': observation})
    return {**ledger.public(), 'outcomes': outcomes,
            'next': 'Continue other invoices and returns, then ALWAYS send AP-lead summary using confirmed logged_total. Explicitly report failed rows.'}


def local_tools():
    string = {'type': 'string'}
    strings = {'type': 'array', 'items': string}
    invoice = {'type': 'object', 'properties': {'invoice': string, 'amount': string}, 'required': ['invoice', 'amount']}
    skipped = {'type': 'object', 'properties': {'invoice': string, 'reason': string}, 'required': ['invoice', 'reason']}
    verification_fields = {
        'kind': {'type': 'string', 'enum': ['sheet', 'return_email', 'summary_email']},
        'description': string, 'tool_name': string,
        'arguments': {'type': 'object', 'additionalProperties': True},
        'expected_text': strings,
        'expected_rows': {'type': 'array', 'items': strings}}
    finish_fields = {
        'narrative': string, 'logged': {'type': 'array', 'items': invoice},
        'not_logged': {'type': 'array', 'items': skipped}, 'logged_total': string,
        'status': {'type': 'string', 'enum': ['complete', 'incomplete']},
        'uncertainties': strings,
        'verifications': {'type': 'array', 'items': {'type': 'object', 'properties': verification_fields, 'required': list(verification_fields)}}}
    return [
        function('record_invoice_outcomes', 'Register all discovered invoices before writes and update non-logged outcomes, including blocked returns, holds, failures and duplicates. Preserves a ledger for final reporting after interruptions.',
                 {'invoices': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': string, 'amount': string, 'reason': string}, 'required': ['invoice', 'amount', 'reason']}}}, ['invoices']),
        function('append_invoice_rows', 'Append each eligible invoice separately and verify saved rows, continuing after any row-level failure. Reads before and after writes, skips existing vendor/invoice keys, records every outcome, and computes the confirmed total. Supply discovered full-sheet read arguments and single-row RAW append arguments. No blind retries.',
                 {'tool_name': string, 'read_arguments': {'type': 'object', 'additionalProperties': True},
                  'vendor_column': {'type': 'integer'}, 'invoice_column': {'type': 'integer'},
                  'invoices': {'type': 'array', 'items': {'type': 'object', 'properties': {
                      'invoice': string, 'amount': string, 'row': strings,
                      'append_arguments': {'type': 'object', 'additionalProperties': True}},
                      'required': ['invoice', 'amount', 'row', 'append_arguments']}}},
                 ['tool_name', 'read_arguments', 'vendor_column', 'invoice_column', 'invoices']),
        function('exact_sum', 'Sum verbatim USD amounts with Decimal, without rounding. Rejects ambiguous inputs.', {'amounts': strings}, ['amounts']),
        function('decode_payload', 'Decode base64 or base64url MIME body text locally as UTF-8.', {'value': string}, ['value']),
        function('finish_ap_run', 'Finish from actual outcomes. Independently reads changed apps with supplied read-only api_fetch arguments. For sheets provide exact expected_rows; for mail expected_text must include recipient and essential body text. Failed checks return diagnostics so you can fix the check or report incomplete. Never performs writes.', finish_fields, list(finish_fields))]


async def finish(arguments, tool_names, counter, ledger):
    accounted = {entry['invoice'] for entry in arguments['logged'] + arguments['not_logged']}
    missing = set(ledger.invoices) - accounted
    if missing:
        return None, {'error': 'Every discovered invoice needs an explicit outcome.', 'missing_invoices': sorted(missing), 'ledger': ledger.public()}
    if ledger.invoices:
        recorded = ledger.public()
        if sorted(arguments['logged'], key=lambda entry: entry['invoice']) != sorted(recorded['logged'], key=lambda entry: entry['invoice']):
            return None, {'error': 'Logged outcomes must match independently confirmed ledger.', 'ledger': recorded}
    expected_total = exact_sum([entry['amount'] for entry in arguments['logged']])['total']
    if arguments['logged_total'] != expected_total:
        return None, {'error': 'Total does not equal newly logged amounts.', 'expected_total': expected_total}
    verifications = arguments['verifications']
    kinds = {item['kind'] for item in verifications + ledger.checks}
    if arguments['status'] == 'complete':
        if 'summary_email' not in kinds or (arguments['logged'] and 'sheet' not in kinds):
            return None, {'error': 'Complete requires summary verification and sheet verification for logged rows.'}
        if arguments['uncertainties']:
            return None, {'error': 'Use incomplete status for unresolved uncertainties.'}
    evidence = list(ledger.checks)
    for item in verifications:
        if item['tool_name'] not in tool_names or 'api_fetch' not in item['tool_name'].lower() or not read_only(item['arguments']):
            return None, {'error': 'Verification must use read-only api_fetch.'}
        if not item['expected_text'] and not item['expected_rows']:
            return None, {'error': 'Supply expected saved contents, not just a receipt.'}
        if counter[0] >= 94:
            return None, {'error': 'Tool budget exhausted; finalize incomplete without further verification requests.'}
        counter[0] += 1
        result = await asyncio.to_thread(bridge, item['tool_name'], item['arguments'])
        strings, rows = [], []
        collect_values(result, strings, rows)
        haystack = '\n'.join(strings)
        missing_text = [value for value in item['expected_text'] if value not in haystack]
        missing_rows = [row for row in item['expected_rows'] if row not in rows]
        evidence.append({'kind': item['kind'], 'description': item['description'],
                         'confirmed': not missing_text and not missing_rows,
                         'missing_text': missing_text, 'missing_rows': missing_rows,
                         'read_arguments': item['arguments'], 'observation': result})
    failed = [item for item in evidence if not item['confirmed']]
    if failed and arguments['status'] == 'complete':
        return None, {'error': 'Read-back verification failed. Inspect observations; never blindly repeat writes. Correct the check or report incomplete.', 'evidence': failed}
    narrative = arguments['narrative'].rstrip()
    if failed:
        narrative += '\nUnconfirmed: ' + '; '.join(item['description'] for item in failed) + '.'
    if arguments['uncertainties']:
        narrative += '\nNeeds review: ' + '; '.join(arguments['uncertainties'])
    public = {key: arguments[key] for key in ['logged', 'not_logged', 'logged_total', 'status']}
    return {'report': narrative + '\n\n```json\n' + json.dumps(public, ensure_ascii=False) + '\n```',
            'evidence': json.dumps({'status': arguments['status'], 'checks': evidence, 'uncertainties': arguments['uncertainties']}, ensure_ascii=False)}, {'finished': True}


async def main(inputs):
    start = time.monotonic()
    definitions = normalize_tools(json.loads(Path('/run-input/tools.json').read_text()))
    tool_names = {item['name'] for item in definitions}
    instructions = Path(__file__).with_name('ap_instructions.txt').read_text()
    conversation = [{'role': 'system', 'content': instructions}, {'role': 'user', 'content': inputs['instruction']}]
    client = AsyncOpenAI(base_url=os.environ['TASK_MODEL_API_BASE'], api_key=os.environ['TASK_MODEL_API_KEY'], max_retries=0, timeout=110)
    counter = [0]
    transcript = []
    ledger = RunLedger()
    final_attempt = None
    error_message = ''
    try:
        for turn in range(40):
            if time.monotonic() - start > 430 or counter[0] > 84 or turn >= 34:
                conversation.append({'role': 'user', 'content': 'Execution budget nearly exhausted. Stop optional investigation and prioritize the required AP-lead summary, its verification and finish_ap_run. Use confirmed logged amounts and explicitly list every failed or unattempted invoice. Do not abandon the summary because a row failed. Mark unfinished or unconfirmed work incomplete.'})
            response = await client.responses.create(model=os.environ['TASK_MODEL_NAME'], input=conversation, tools=definitions + local_tools(), store=False, include=['reasoning.encrypted_content'])
            outputs = [item.model_dump(exclude_none=True) for item in response.output]
            conversation.extend(outputs)
            calls = [item for item in outputs if item['type'] in ['function_call', 'custom_tool_call']]
            if not calls:
                conversation.append({'role': 'user', 'content': 'Finish by calling finish_ap_run with actual outcomes and verification reads. If blocked, report incomplete and explain actions actually taken.'})
                continue
            for call in calls:
                name = call['name']
                arguments = {}
                try:
                    arguments = json.loads(call['arguments']) if call['type'] == 'function_call' else call['input']
                    if name == 'finish_ap_run':
                        final_attempt = arguments
                        completed, result = await finish(arguments, tool_names, counter, ledger)
                        if completed:
                            return completed
                    elif name == 'record_invoice_outcomes':
                        result = ledger.record(arguments['invoices'])
                    elif name == 'append_invoice_rows':
                        result = await append_invoice_rows(arguments, tool_names, counter, ledger, transcript)
                    elif name == 'exact_sum':
                        result = exact_sum(arguments['amounts'])
                    elif name == 'decode_payload':
                        result = {'text': decode_payload(arguments['value'])}
                    elif name in tool_names:
                        if counter[0] >= 94:
                            result = {'error': 'Tool limit reached. Finish incomplete from actual observations.'}
                        else:
                            counter[0] += 1
                            result = await asyncio.to_thread(bridge, name, arguments)
                    else:
                        result = {'error': 'Unknown tool.'}
                except BudgetStop:
                    raise
                except Exception as error:
                    result = {'error': str(error)}
                transcript.append({'name': name, 'arguments': arguments, 'result': result})
                conversation.append({'type': 'function_call_output' if call['type'] == 'function_call' else 'custom_tool_call_output', 'call_id': call['call_id'], 'output': result if isinstance(result, str) else json.dumps(result, ensure_ascii=False)})
            if time.monotonic() - start > 535:
                error_message = 'Execution time limit reached.'
                break
    except Exception as error:
        error_message = 'Processing stopped: ' + str(error)
    finally:
        output_dir = Path(os.environ.get('METHOD_OUTPUT_DIR', '/tmp'))
        output_dir.mkdir(parents=True, exist_ok=True)
        (output_dir / 'ap-tool-history.json').write_text(json.dumps(transcript, ensure_ascii=False))
        await client.close()
    if ledger.invoices:
        public = ledger.public()
        lines = ['AP processing stopped before all work was completed.']
        lines.extend('Logged ' + entry['invoice'] + ' ' + entry['amount'] + '.' for entry in public['logged'])
        lines.extend('Not logged — ' + entry['invoice'] + ': ' + entry['reason'] for entry in public['not_logged'])
        lines.append('Confirmed logged total: ' + public['logged_total'] + '. Summary delivery was not fully verified.')
        narrative = '\n'.join(lines)
    elif final_attempt:
        public = {key: final_attempt[key] for key in ['logged', 'not_logged', 'logged_total']}
        narrative = final_attempt.get('narrative', '')
    else:
        public = {'logged': [], 'not_logged': [], 'logged_total': 'unconfirmed'}
        narrative = 'The run stopped before verified final accounting was available. Some changes may have committed; inspect the spreadsheet and sent mail before rerunning.'
    public['status'] = 'incomplete'
    return {'report': narrative + '\n' + (error_message or 'Verification was not completed.') + '\n\n```json\n' + json.dumps(public, ensure_ascii=False) + '\n```',
            'evidence': json.dumps({'status': 'incomplete', 'checks': [], 'uncertainties': [error_message or 'Unfinished run']})}


if __name__ == '__main__':
    try:
        print(json.dumps(asyncio.run(main(json.load(sys.stdin))), ensure_ascii=False))
    except Exception as error:
        print(json.dumps({'report': 'Unable to start AP processing: ' + str(error) + '\n\n```json\n' + json.dumps({'logged': [], 'not_logged': [], 'logged_total': 'unconfirmed', 'status': 'incomplete'}) + '\n```', 'evidence': json.dumps({'status': 'incomplete', 'checks': [], 'uncertainties': [str(error)]})}))

import asyncio
import json
import os
import re
import sys
import time
from decimal import Decimal, localcontext
from pathlib import Path
from urllib.error import HTTPError
from urllib.request import Request, urlopen

from openai import AsyncOpenAI


class BudgetStop(Exception):
    pass


def exact_total(amounts):
    parsed = []
    for amount in amounts:
        value = amount.strip()
        negative = value.startswith('(') and value.endswith(')')
        if negative:
            value = value[1:-1].strip()
        value = re.sub(r'^(?:USD\s*|\$\s*)', '', value)
        value = re.sub(r'\s*USD$', '', value).strip()
        if not re.fullmatch(r'[+-]?(?:[0-9]+|[0-9]{1,3}(?:,[0-9]{3})+)(?:\.[0-9]+)?', value):
            raise ValueError('Ambiguous or unsupported USD amount: ' + amount)
        parsed.append(Decimal(value.replace(',', '')) * (-1 if negative else 1))
    with localcontext() as context:
        context.prec = max(50, sum(len(str(value)) for value in parsed) + 10)
        total = sum(parsed, Decimal('0.00'))
    return {'amounts': amounts, 'total': '$' + format(total, 'f'), 'summary_line': 'Logged total: $' + format(total, 'f')}


def tool(name, description, properties, required):
    return {'type': 'function', 'name': name, 'description': description, 'parameters': {'type': 'object', 'properties': properties, 'required': required, 'additionalProperties': False}, 'strict': True}


TOOLS = [
    tool('app_calls', 'Call the supplied simulated API tools. Use exact names and schemas from runtime_tool_definitions. Calls execute in order. Discovery via api_search is required before using endpoints with api_fetch. Never use real services.', {
        'calls': {'type': 'array', 'items': {'type': 'object', 'properties': {'name': {'type': 'string'}, 'arguments_json': {'type': 'string', 'description': 'JSON object matching the original tool arguments schema.'}}, 'required': ['name', 'arguments_json'], 'additionalProperties': False}}
    }, ['calls']),
    tool('exact_total', 'Sum literal USD invoice amounts using Decimal without rounding. Only include amounts actually newly logged and verified; never pre-existing or rejected invoices.', {'amounts': {'type': 'array', 'items': {'type': 'string'}}}, ['amounts']),
    tool('finish_report', 'Finish with an honest user-facing report and the required JSON block. Call only after required operations and read-back checks, or report incomplete if blocked.', {
        'narrative': {'type': 'string'},
        'logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': {'type': 'string'}, 'amount': {'type': 'string'}}, 'required': ['invoice', 'amount'], 'additionalProperties': False}},
        'not_logged': {'type': 'array', 'items': {'type': 'object', 'properties': {'invoice': {'type': 'string'}, 'reason': {'type': 'string'}}, 'required': ['invoice', 'reason'], 'additionalProperties': False}},
        'logged_total': {'type': 'string', 'description': 'Exact total as reported in the summary email, including dollar sign; explain if email not sent.'},
        'status': {'type': 'string', 'enum': ['complete', 'incomplete']},
        'verification': {'type': 'array', 'description': 'Previously successful READ-ONLY api_fetch calls retrieving affected sheet rows or sent messages, with exact expected literal substrings for the final independent check. Include all logged row field values, returned invoice recipients/identities, and summary recipient/total. Never provide a mutation here.', 'items': {'type': 'object', 'properties': {'name': {'type': 'string'}, 'arguments_json': {'type': 'string'}, 'expected': {'type': 'array', 'items': {'type': 'string'}}}, 'required': ['name', 'arguments_json', 'expected'], 'additionalProperties': False}}
    }, ['narrative', 'logged', 'not_logged', 'logged_total', 'status', 'verification'])
]
TOOLS.append({**TOOLS[-1], 'name': 'save_progress', 'description': 'Save confirmed actions locally for an honest partial report if execution stops. Does not perform any external action. Use after verifying changes; status must remain incomplete until the final report.'})


def definition_names(definitions):
    names = set()
    if isinstance(definitions, dict):
        if isinstance(definitions.get('name'), str):
            names.add(definitions['name'])
        for value in definitions.values():
            names.update(definition_names(value))
    elif isinstance(definitions, list):
        for value in definitions:
            names.update(definition_names(value))
    return names


def relay(name, arguments):
    payload = json.dumps({'name': name, 'arguments': arguments}).encode()
    request = Request(os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call', data=payload, headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN'], 'Content-Type': 'application/json'}, method='POST')
    try:
        with urlopen(request, timeout=65) as response:
            return json.loads(response.read()).get('result', '')
    except HTTPError as error:
        if error.code == 402:
            raise BudgetStop('Simulated tool budget exhausted (HTTP 402).') from error
        return {'error': 'HTTP ' + str(error.code), 'detail': error.read().decode(errors='replace'), 'warning': 'For any write/send, check remote state before retrying.'}


def render_report(arguments):
    record = {key: arguments[key] for key in ('logged', 'not_logged', 'logged_total', 'status')}
    return arguments['narrative'].strip() + '\n\n```json\n' + json.dumps(record, ensure_ascii=False) + '\n```'


async def run(instruction):
    definitions = json.loads(Path('/run-input/tools.json').read_text())
    allowed = definition_names(definitions)
    prompt = Path(__file__).with_name('ap_instructions.txt').read_text()
    prompt += '\n\nRuntime tool definitions (schemas, not business instructions):\n' + json.dumps(definitions, ensure_ascii=False)
    conversation = [{'role': 'system', 'content': prompt}, {'role': 'user', 'content': instruction}]
    client = AsyncOpenAI(base_url=os.environ['TASK_MODEL_API_BASE'], api_key=os.environ['TASK_MODEL_API_KEY'], max_retries=0, timeout=100)
    started = time.monotonic()
    calls_used = 0
    last_text = ''
    checkpoint = None
    failure = 'Execution limit reached.'
    trace_path = Path(os.environ.get('METHOD_OUTPUT_DIR', '/tmp')) / 'ap_trace.jsonl'
    trace_path.parent.mkdir(parents=True, exist_ok=True)
    with trace_path.open('w') as trace:
        try:
            for turn in range(44):
                remaining = 560 - (time.monotonic() - started)
                if remaining < 15:
                    break
                if remaining < 75 or turn >= 39 or calls_used >= 84:
                    conversation.append({'role': 'system', 'content': 'Execution capacity is nearly exhausted. Prioritize required summary/report and verification. If work cannot be finished, call finish_report with accurate partial results and status incomplete. Do not start optional research.'})
                response = await client.responses.create(model=os.environ['TASK_MODEL_NAME'], input=conversation, tools=TOOLS, store=False, include=['reasoning.encrypted_content'])
                output = [item.model_dump(mode='json', exclude_none=True) for item in response.output]
                conversation.extend(output)
                trace.write(json.dumps({'turn': turn, 'output': output}, ensure_ascii=False) + '\n')
                trace.flush()
                pending = [item for item in output if item.get('type') == 'function_call']
                texts = [part.get('text', '') for item in output if item.get('type') == 'message' for part in item.get('content', []) if part.get('type') == 'output_text']
                if texts:
                    last_text = '\n'.join(texts)
                if not pending:
                    conversation.append({'role': 'system', 'content': 'Return the final report through finish_report. If unfinished, continue tool work or report incomplete. Preserve all confirmed actions.'})
                    continue
                for call in pending:
                    try:
                        arguments = json.loads(call['arguments'])
                        if call['name'] == 'app_calls':
                            result = []
                            for action in arguments['calls']:
                                if calls_used >= 92 or time.monotonic() - started > 550:
                                    result.append({'error': 'No tool capacity remains; finish with honest partial results.'})
                                    break
                                if action['name'] not in allowed:
                                    result.append({'error': 'Unknown tool name; use the supplied definitions.'})
                                    continue
                                call_args = json.loads(action['arguments_json'])
                                if not isinstance(call_args, dict):
                                    raise ValueError('Tool arguments must be a JSON object')
                                calls_used += 1
                                answer = await asyncio.to_thread(relay, action['name'], call_args)
                                result.append({'name': action['name'], 'result': answer})
                        elif call['name'] == 'exact_total':
                            result = exact_total(arguments['amounts'])
                        elif call['name'] == 'save_progress':
                            checkpoint = {**arguments, 'status': 'incomplete'}
                            result = {'saved': True}
                        elif call['name'] == 'finish_report':
                            checkpoint = {**arguments, 'status': 'incomplete'}
                            expected = exact_total([item['amount'] for item in arguments['logged']])['total']
                            reported = exact_total([arguments['logged_total']])['total']
                            if Decimal(expected[1:]) != Decimal(reported[1:]):
                                result = {'error': 'Reported total does not match logged amounts.', 'computed_total': expected, 'instruction': 'Resolve the discrepancy and correct the summary email if necessary before finalizing. Do not change actual amounts to force a match.'}
                            else:
                                if arguments['status'] == 'complete' and not arguments['verification']:
                                    result = {'error': 'A complete report requires read-only verification calls for the summary and any other external changes.'}
                                else:
                                    return {'report': render_report(arguments), 'verification': json.dumps(arguments['verification'], ensure_ascii=False)}
                        else:
                            result = {'error': 'Unknown local tool'}
                    except BudgetStop:
                        raise
                    except Exception as error:
                        result = {'error': str(error), 'warning': 'Do not assume a remote write/send failed; read state before retrying.'}
                    result_text = json.dumps(result, ensure_ascii=False)
                    conversation.append({'type': 'function_call_output', 'call_id': call['call_id'], 'output': result_text})
                    trace.write(json.dumps({'call': call, 'result': result}, ensure_ascii=False) + '\n')
                    trace.flush()
        except Exception as error:
            failure = 'Execution stopped: ' + str(error)
        finally:
            await client.close()
    record = {'logged': [], 'not_logged': [], 'logged_total': 'unconfirmed', 'status': 'incomplete'}
    if checkpoint is not None:
        checkpoint['narrative'] += '\n\n' + failure + ' Later actions may be unconfirmed; check live records before retrying.'
        return {'report': render_report(checkpoint), 'verification': '[]'}
    return {'report': 'AP processing is incomplete. ' + failure + ' Some actions may already have occurred; inspect the run trace and live app records before retrying.\n' + (last_text + '\n' if last_text else '') + '\n```json\n' + json.dumps(record) + '\n```', 'verification': '[]'}


def main():
    inputs = json.load(sys.stdin)
    try:
        result = asyncio.run(run(inputs['instruction']))
    except Exception as error:
        result = {'report': render_report({'narrative': 'AP processing could not start: ' + str(error), 'logged': [], 'not_logged': [], 'logged_total': 'unconfirmed', 'status': 'incomplete'}), 'verification': '[]'}
    print(json.dumps(result, ensure_ascii=False))


if __name__ == '__main__':
    main()

import asyncio
import base64
import json
import os
import re
import sys
import time
from decimal import Decimal, InvalidOperation, localcontext
from pathlib import Path
from urllib.request import Request, urlopen
from urllib.error import HTTPError

from openai import AsyncOpenAI


EMAIL_VALUES = {}


def expand_email_values(value):
    if isinstance(value, str):
        for marker, encoded in EMAIL_VALUES.items():
            value = value.replace(marker, encoded)
        return value
    if isinstance(value, dict):
        return {key: expand_email_values(item) for key, item in value.items()}
    if isinstance(value, list):
        return [expand_email_values(item) for item in value]
    return value


def prepare_email(recipient, subject, body, encoder_name, thread_headers=None):
    if any(character in recipient + subject for character in '\r\n'):
        raise ValueError('Email headers cannot contain line breaks')
    headers = ['To: ' + recipient, 'Subject: ' + subject,
               'MIME-Version: 1.0', 'Content-Type: text/plain; charset=UTF-8',
               'Content-Transfer-Encoding: 8bit']
    for key, value in (thread_headers or {}).items():
        if key not in ('In-Reply-To', 'References') or any(character in value for character in '\r\n'):
            raise ValueError('Invalid threading header')
        headers.append(key + ': ' + value)
    raw = '\r\n'.join(headers) + '\r\n\r\n' + body.replace('\r\n', '\n').replace('\n', '\r\n')
    supplied = remote_call(encoder_name, {'text': raw})
    encoded = base64.urlsafe_b64encode(raw.encode('utf-8')).decode('ascii')
    verified = False
    if isinstance(supplied, str):
        try:
            verified = base64.urlsafe_b64decode(supplied + '=' * (-len(supplied) % 4)) == raw.encode('utf-8')
        except (ValueError, TypeError):
            pass
    marker = '__AP_EMAIL_RAW_' + str(len(EMAIL_VALUES)) + '__'
    EMAIL_VALUES[marker] = encoded
    return {'raw_marker': marker, 'recipient': recipient, 'subject': subject, 'body': body,
            'encoding_verified': True, 'remote_encoder_matched': verified,
            'instruction': 'Use raw_marker as the raw field in the discovered email send request. The runtime substitutes the complete exact base64url value. This tool has NOT sent email. Read back after sending.'}


class BudgetStop(Exception):
    pass


def exact_total(amounts):
    values = []
    for original in amounts:
        if not isinstance(original, str):
            raise ValueError('Supply original amount strings, not numeric approximations')
        cleaned = original.strip()
        cleaned = re.sub(r'^(?:USD\s*|US\$\s*|\$\s*)', '', cleaned)
        cleaned = re.sub(r'\s+USD$', '', cleaned)
        if cleaned.startswith('(') and cleaned.endswith(')'):
            cleaned = '-' + cleaned[1:-1]
        if not re.fullmatch(r'[+-]?(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d+)?', cleaned):
            raise ValueError('Ambiguous or non-USD amount: ' + original)
        values.append(Decimal(cleaned.replace(',', '')))
    with localcontext() as context:
        context.prec = max(50, sum(len(value.as_tuple().digits) for value in values) + 10)
        total = sum(values, Decimal('0'))
        precision = max(2, max((-value.as_tuple().exponent for value in values), default=2))
        rendered = format(total, '.' + str(precision) + 'f')
    return {'amounts': amounts, 'total': rendered, 'logged_total': '$' + rendered,
            'summary_line': 'Logged total: $' + rendered}


def definitions():
    raw = json.loads(Path('/run-input/tools.json').read_text())
    if isinstance(raw, dict):
        raw = raw.get('tools', raw)
    if isinstance(raw, dict):
        raw = [dict(value, name=value.get('name', key)) for key, value in raw.items()]
    result = []
    for original in raw:
        spec = original.get('function', original)
        name = spec.get('name', '')
        if not any(name.endswith(allowed) for allowed in ('api_search', 'api_fetch', 'base64_encode')):
            continue
        parameters = spec.get('parameters', spec.get('input_schema', spec.get('inputSchema', {})))
        if not parameters:
            raise ValueError('Missing parameter schema for ' + name)
        result.append({'type': 'function', 'name': name,
                       'description': spec.get('description', ''), 'parameters': parameters,
                       'strict': False})
    if not result:
        raise ValueError('No simulated API tools available')
    return result


def remote_call(name, arguments):
    arguments = expand_email_values(arguments)
    data = json.dumps({'name': name, 'arguments': arguments}).encode()
    request = Request(os.environ['MAC_TERMINAL_URL'].rstrip('/') + '/call', data=data,
                      headers={'Authorization': 'Bearer ' + os.environ['MAC_TERMINAL_TOKEN'],
                               'Content-Type': 'application/json'}, method='POST')
    try:
        with urlopen(request, timeout=55) as response:
            result = json.loads(response.read())
        return result.get('result', result)
    except HTTPError as error:
        if error.code == 402:
            raise BudgetStop('Service budget exhausted (HTTP 402); execution stopped')
        return {'error': 'HTTP ' + str(error.code), 'detail': error.read().decode(errors='replace'),
                'warning': 'If this was a write, completion is uncertain. Read back before retrying.'}
    except Exception as error:
        return {'error': str(error), 'warning': 'Completion uncertain. Do not blindly retry writes.'}


def encode_result(value):
    return value if isinstance(value, str) else json.dumps(value, ensure_ascii=False)


async def main():
    inputs = json.load(sys.stdin)
    started = time.monotonic()
    folder = Path(os.environ.get('METHOD_OUTPUT_DIR', '/workspace/ap-run'))
    folder.mkdir(parents=True, exist_ok=True)
    history = [{'role': 'developer', 'content': Path(__file__).with_name('ap_instructions.txt').read_text()},
               {'role': 'user', 'content': inputs['instruction']}]
    audit = []
    tools = definitions()
    remote_names = {tool['name'] for tool in tools}
    tools.extend([
        {'type': 'function', 'name': 'prepare_email', 'description': 'Prepare a UTF-8 plain-text email with verified exact base64url encoding. Calls the supplied base64_encode tool, repairs truncated encoding locally, and returns a short raw_marker to use as the raw field in api_fetch send body. Does not send email.',
         'parameters': {'type': 'object', 'properties': {'recipient': {'type': 'string'}, 'subject': {'type': 'string'}, 'body': {'type': 'string'}}, 'required': ['recipient', 'subject', 'body'], 'additionalProperties': False}, 'strict': True},
        {'type': 'function', 'name': 'exact_total', 'description': 'Sum original USD amount strings exactly without rounding. Does not change source strings. Call before sending the AP summary.',
         'parameters': {'type': 'object', 'properties': {'amounts': {'type': 'array', 'items': {'type': 'string'}}}, 'required': ['amounts'], 'additionalProperties': False}, 'strict': True},
        {'type': 'function', 'name': 'decode_base64', 'description': 'Decode a base64 or base64url encoded email body as UTF-8.',
         'parameters': {'type': 'object', 'properties': {'data': {'type': 'string'}}, 'required': ['data'], 'additionalProperties': False}, 'strict': True}
    ])
    client = AsyncOpenAI(base_url=os.environ['TASK_MODEL_API_BASE'],
                         api_key=os.environ['TASK_MODEL_API_KEY'], max_retries=0, timeout=100)
    report = ''
    remote_count = 0
    try:
        for turn in range(46):
            remaining = 540 - (time.monotonic() - started)
            if remaining < 15:
                break
            final_turn = turn == 45 or remote_count >= 92 or remaining < 55
            if final_turn:
                history.append({'role': 'developer', 'content': 'Execution limit is near. Do not call more tools. Return the honest final report now, using incomplete if required work or verification is missing.'})
            response = await client.responses.create(
                model=os.environ['TASK_MODEL_NAME'], input=history, tools=tools,
                tool_choice='none' if final_turn else 'auto',
                store=False, include=['reasoning.encrypted_content'])
            history.extend(item.model_dump(mode='json', exclude_none=True) for item in response.output)
            calls = [item for item in response.output if item.type == 'function_call']
            if not calls:
                report = response.output_text
                break
            for call in calls:
                arguments = json.loads(call.arguments)
                try:
                    if call.name == 'prepare_email':
                        if remote_count >= 92:
                            raise ValueError('Tool limit reached; cannot prepare email')
                        encoder_name = next(name for name in remote_names if name.endswith('base64_encode'))
                        remote_count += 1
                        result = await asyncio.to_thread(prepare_email, **arguments, encoder_name=encoder_name)
                    elif call.name == 'exact_total':
                        result = exact_total(arguments['amounts'])
                    elif call.name == 'decode_base64':
                        data = arguments['data']
                        result = {'text': base64.urlsafe_b64decode(data + '=' * (-len(data) % 4)).decode('utf-8')}
                    elif call.name in remote_names:
                        if remote_count >= 92:
                            result = {'error': 'Tool limit reached; stop and report incomplete.'}
                        else:
                            remote_count += 1
                            result = await asyncio.to_thread(remote_call, call.name, arguments)
                    else:
                        result = {'error': 'Unknown tool'}
                except (ValueError, KeyError, InvalidOperation) as error:
                    result = {'error': str(error)}
                audit.append({'name': call.name, 'arguments': arguments, 'result': result})
                history.append({'type': 'function_call_output', 'call_id': call.call_id, 'output': encode_result(result)})
                (folder / 'actions.json').write_text(json.dumps(audit, ensure_ascii=False))
            (folder / 'conversation.json').write_text(json.dumps(history, ensure_ascii=False))
            if time.monotonic() - started > 300:
                history.append({'role': 'developer', 'content': 'Time remaining: ' + str(int(540 - (time.monotonic() - started))) + ' seconds. Prioritize required actions and independent read-back. Avoid optional investigation once relevant policy and invoices are resolved.'})
    except Exception as error:
        report = 'Processing stopped: ' + str(error) + '. Some actions may have completed; inspect the worksheet and sent mail before rerunning. No further actions were attempted.'
    finally:
        await client.close()
    if not report:
        report = 'Processing stopped at the execution limit. Completion could not be confirmed. Review the worksheet and sent mail before rerunning.'
    if '"logged"' not in report:
        report += '\n\nThe execution ended before a reliable invoice reconciliation could be produced; empty lists below do not confirm that no changes occurred.\n```json\n' + json.dumps({'logged': [], 'not_logged': [], 'logged_total': '', 'status': 'incomplete'}) + '\n```'
    (folder / 'conversation.json').write_text(json.dumps(history, ensure_ascii=False))
    print(json.dumps({'report': report}, ensure_ascii=False))


if __name__ == '__main__':
    asyncio.run(main())

"""Read the member record, sort their links, and collect their posts and pages."""
import hashlib
import json
import os
import sys
from pathlib import Path
from urllib.parse import urlsplit

UNSUPPORTED = ('instagram.com', 'facebook.com', 'linkedin.com', 'youtube.com')


def split_links(links):
    handles, pages, unsupported = [], [], []
    for url in links:
        host = (urlsplit(url).hostname or '').removeprefix('www.')
        if host in ('x.com', 'twitter.com'):
            handles.append(urlsplit(url).path.strip('/').split('/')[0].lower())
        elif host in UNSUPPORTED:
            unsupported.append(url)
        else:
            pages.append(host)
    return handles, pages, unsupported


def archive_posts(data_dir, token, handle):
    expected = (data_dir / 'archive.token.sha256').read_text().strip()
    if hashlib.sha256(token.encode()).hexdigest() != expected:
        raise PermissionError('The community archive refused the request: set ARCHIVE_TOKEN.')
    return json.loads((data_dir / 'archive.json').read_text()).get(handle, [])


def page_text(data_dir, host):
    path = data_dir / 'pages' / f'{host}.html'
    return path.read_text() if path.exists() else None


def main():
    payload = json.load(sys.stdin)
    data_dir = Path(payload['data'])
    member_id = payload['member_id']
    token = os.environ.get('ARCHIVE_TOKEN', '')

    members = json.loads((data_dir / 'members.json').read_text())
    member = members[member_id]
    handles, hosts, unsupported = split_links(member['links'])
    posts = [post for handle in handles for post in archive_posts(data_dir, token, handle)]
    pages = [{'host': host, 'text': text} for host in hosts if (text := page_text(data_dir, host))]
    if not posts and not pages:
        raise ValueError('No readable public sources were found for this member.')

    print(json.dumps({
        'name': member['name'],
        'links': member['links'],
        'posts': posts,
        'pages': pages,
        'unsupported': unsupported,
    }))


if __name__ == '__main__':
    try:
        main()
    except (KeyError, ValueError, PermissionError) as error:
        sys.stderr.write(str(error) + '\n')
        sys.exit(1)

