// This helper runs beside the Method. The command runs in Harbor's container.
export async function terminal({ command, timeout_sec = 30 }) {
  const socketPath = process.env.MAC_TERMINAL_SOCKET;
  if (!socketPath) throw Error('MAC terminal connection is missing');
  const body = JSON.stringify({ command, timeout_sec });
  return new Promise((resolve, reject) => {
    const request = http.request({ socketPath, path: '/exec', method: 'POST',
      headers: { 'content-type': 'application/json', 'content-length': Buffer.byteLength(body) } }, response => {
      let bytes = 0;
      const chunks = [];
      response.on('data', chunk => {
        bytes += chunk.length;
        if (bytes > 1_000_000) response.destroy(Error('Terminal response is too large'));
        else chunks.push(chunk);
      });
      response.on('error', reject);
      response.on('end', () => {
        try {
          const value = JSON.parse(Buffer.concat(chunks).toString());
          if (response.statusCode !== 200) throw Error(value.error ?? `Terminal HTTP ${response.statusCode}`);
          resolve(value);
        } catch (error) { reject(error); }
      });
    });
    request.setTimeout(125_000, () => request.destroy(Error('Terminal connection timed out')));
    request.on('error', reject);
    request.end(body);
  });
}

