    for await (const chunk of process.stdin) {
      input += chunk;
      if (Buffer.byteLength(input) > 100_000) throw Error('Terminal request is too large');
    }
    console.log(JSON.stringify(await terminal(JSON.parse(input))));
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}

"""Read the inbox, the AP Slack channel, and the Blocked Vendors sheet. Writes nothing."""
import json
from api import call, io, parsed, sheet_rows


def handle(_):
    inbox = parsed(call('GET', 'https://gmail.googleapis.com/gmail/v1/users/me/messages', params={'maxResults': 100}))
    if 'messages' not in inbox:
        raise SystemExit(f'Reading the inbox failed: {inbox}')
    emails = []
    for item in inbox.get('messages', []):
        message = parsed(call('GET', f"https://gmail.googleapis.com/gmail/v1/users/me/messages/{item['id']}"))
        if 'error' in message:
            raise SystemExit(f"Reading message {item['id']} failed: {message}")
        emails.append(message)
    slack = parsed(call('GET', 'https://slack.com/api/conversations.history', params={'channel': 'C_AP'}))
    if 'messages' not in slack:
        raise SystemExit(f'Reading the AP channel failed: {slack}')
    blocked = sheet_rows('Blocked Vendors')
    raw = json.dumps({'emails': emails, 'ap_slack_channel': slack['messages'], 'blocked_vendors_sheet': blocked})
    return {'raw': raw}


io(handle)

import base64
import copy
import json
import re
import sys
import time
from collections import Counter
from email.utils import getaddresses, parseaddr
from urllib.parse import quote

from app_tools import StopRun, call_tool, collect_names, total_amounts, tool_definitions


def unpack(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except (TypeError, ValueError):
            pass
    return value


def object_field(arguments, key):
    value = unpack(arguments.get(key))
    return copy.deepcopy(value) if isinstance(value, dict) else {}


def replace_text(value, marker, replacement):
    if isinstance(value, str):
        return value.replace(marker, replacement)
    if isinstance(value, list):
        return [replace_text(item, marker, replacement) for item in value]
    if isinstance(value, dict):
        return {key: replace_text(item, marker, replacement) for key, item in value.items()}
    return value


class Api:
    def __init__(self, state, seconds, ceiling):
        self.state = state
        self.deadline = time.monotonic() + seconds
        self.ceiling = ceiling

    def call(self, recipe, write=False):
        if self.state.get('stop'):
            raise StopRun('Service stopped; no further API calls are allowed')
        if time.monotonic() > self.deadline or self.state.get('api_calls', 0) >= self.ceiling:
            raise RuntimeError('Reserved execution budget reached; remaining actions are incomplete')
        if not isinstance(recipe, dict) or not recipe.get('name') or not isinstance(recipe.get('arguments'), dict):
            raise ValueError('Missing discovered API recipe')
        self.state['api_calls'] = self.state.get('api_calls', 0) + 1
        try:
            result = unpack(call_tool(recipe['name'], recipe['arguments'], 'write' if write else 'read'))
        except StopRun:
            self.state['stop'] = True
            raise
        if isinstance(result, dict) and (result.get('error') or result.get('ok') is False):
            raise RuntimeError(json.dumps(result, ensure_ascii=False))
        return result


def rows_from(result):
    if not isinstance(result, dict) or not isinstance(result.get('values', []), list):
        raise ValueError('Tracker did not return cell values')
    if 'values' not in result and 'range' not in result:
        raise ValueError('Tracker readback did not identify the requested range')
    return result.get('values', [])


def row_key(row):
    row = list(row)
    while row and row[-1] == '':
        row.pop()
    return tuple(row)


def header(message, name):
    for entry in message.get('payload', {}).get('headers', []):
        if entry.get('name', '').lower() == name.lower():
            return entry.get('value', '')
    return ''


def body_text(message):
    if isinstance(message.get('body_plain'), str):
        return message['body_plain']
    parts = []

    def walk(part):
        data = part.get('body', {}).get('data')
        if data and part.get('mimeType', 'text/plain') == 'text/plain':
            parts.append(base64.urlsafe_b64decode(data + '=' * (-len(data) % 4)).decode('utf-8'))
        for child in part.get('parts', []):
            walk(child)

    walk(message.get('payload', {}))
    return '\n'.join(parts)


def verify_mail(message, recipient, text, thread_id=''):
    if not isinstance(message, dict):
        raise ValueError('Sent message could not be read back')
    addresses = message.get('to') or header(message, 'To')
    addresses = addresses if isinstance(addresses, list) else [addresses]
    recipients = [address.lower() for _, address in getaddresses(addresses)]
    labels = message.get('labelIds', message.get('label_ids', []))
    if recipient.lower() not in recipients or 'SENT' not in labels:
        raise ValueError('Sent-message recipient or SENT state could not be verified')
    if body_text(message).replace('\r\n', '\n').rstrip('\n') != text.replace('\r\n', '\n').rstrip('\n'):
        raise ValueError('Sent-message body differs from the exact intended notification')
    actual_thread = message.get('threadId', message.get('thread_id'))
    if thread_id and actual_thread != thread_id:
        raise ValueError('Return email was not verified in the original thread')
    return {'id': message.get('id', message.get('message_id')), 'recipient': recipient,
            'body': text, 'sent': True, 'thread_id': actual_thread}


def encoded_value(value, text):
    candidates = [value] if isinstance(value, str) else []
    if isinstance(value, dict):
        candidates.extend(item for item in value.values() if isinstance(item, str))
    for candidate in candidates:
        try:
            decoded = base64.urlsafe_b64decode(candidate + '=' * (-len(candidate) % 4)).decode('utf-8')
            if decoded == text:
                return candidate.replace('+', '-').replace('/', '_').rstrip('=')
        except Exception:
            pass
    raise ValueError('Encoding tool did not return an exact base64 encoding of the notification')


def send_mail(api, mail, recipient, subject, text, thread_id='', message_id='', parts=None):
    if any('\r' in value or '\n' in value for value in (recipient, subject, message_id, thread_id)):
        raise ValueError('Unsafe newline in email header metadata; message not sent')
    if parseaddr(recipient)[1] != recipient or '@' not in recipient:
        raise ValueError('Return sender address is not a verified plain mailbox')
    headers = [{'name': 'From', 'value': 'ap@company.example.com'},
               {'name': 'To', 'value': recipient}, {'name': 'Subject', 'value': subject}]
    if message_id:
        headers.extend([{'name': 'In-Reply-To', 'value': message_id}, {'name': 'References', 'value': message_id}])
    recipe = copy.deepcopy(mail['send'])
    arguments = recipe['arguments']
    encoded_text = text
    if mail.get('format', 'payload') == 'raw':
        encoded_text = '\r\n'.join(entry['name'] + ': ' + entry['value'] for entry in headers)
        encoded_text += '\r\nMIME-Version: 1.0\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Transfer-Encoding: 8bit\r\n\r\n' + text
    encoder = replace_text(mail['encode'], '__TEXT__', encoded_text)
    encoded = encoded_value(api.call(encoder), encoded_text)
    if mail.get('format', 'payload') == 'raw':
        if parts:
            raise ValueError('Required attachment parts cannot be dropped from a raw return')
        payload = {'raw': encoded}
    else:
        content = {'mimeType': 'text/plain', 'headers': headers, 'body': {'data': encoded}}
        if parts:
            content = {'mimeType': 'multipart/mixed', 'headers': headers,
                       'parts': [{'mimeType': 'text/plain', 'body': {'data': encoded}}] + parts}
        payload = {'payload': content}
    if thread_id:
        payload['threadId'] = thread_id
    arguments['body'] = json.dumps(payload, ensure_ascii=False)
    result = api.call(recipe, write=True)
    message_id_sent = result.get('id', result.get('message_id')) if isinstance(result, dict) else None
    if not message_id_sent:
        raise ValueError('Send completion is uncertain: no sent message ID. Do not resend blindly.')
    read = replace_text(mail['get'], '__MESSAGE_ID__', quote(message_id_sent, safe=''))
    try:
        return verify_mail(api.call(read), recipient, text, thread_id)
    except Exception as error:
        raise ValueError('Message ' + message_id_sent + ' was sent but readback is unverified: ' + str(error)) from error


def invoice_fields(invoice, columns):
    row = invoice['row']
    if not isinstance(row, list) or not row or not all(isinstance(cell, str) for cell in row):
        raise ValueError('Invoice row must contain only literal source strings')
    for field in ('vendor', 'invoice', 'date', 'amount', 'due_date'):
        if not isinstance(invoice.get(field), str) or not invoice[field]:
            raise ValueError('Missing required invoice field: ' + field)
        if row[columns[field]] != invoice[field]:
            raise ValueError('Row does not preserve planned ' + field)
    total_amounts([invoice['amount']])
    return row


def record(plan):
    state = {'plan': plan, 'logged': [], 'not_logged': [], 'returns': [], 'issues': list(plan.get('issues', [])),
             'api_calls': plan.get('read_calls', 0), 'stop': plan.get('stop', False), 'readback': []}
    if not plan.get('sources_complete'):
        state['issues'].append('The required source review was not completed.')
    api = Api(state, 105, 89)
    invoices = plan.get('invoices', [])
    sheet = plan.get('sheet', {})
    columns = sheet.get('columns', {})
    before = None
    attempts = []
    if any(invoice.get('disposition') == 'log' for invoice in invoices):
        try:
            before = rows_from(api.call(sheet['read']))
        except Exception as error:
            state['issues'].append('Tracker baseline read failed: ' + str(error))
    seen = set()
    for invoice in invoices:
        disposition = invoice.get('disposition')
        item = {'invoice': invoice.get('invoice', ''), 'reason': invoice.get('reason', ''),
                'vendor': invoice.get('vendor', ''), 'amount': invoice.get('amount', '')}
        if disposition != 'log':
            if disposition == 'hold' or disposition not in ('return', 'duplicate'):
                state['issues'].append('Invoice ' + item['invoice'] + ' is unresolved: ' + item['reason'])
            state['not_logged'].append(item)
            continue
        try:
            row = invoice_fields(invoice, columns)
            if before is None:
                raise ValueError('Not appended because the tracker could not be checked for duplicates')
            identity = (invoice['vendor'], invoice['invoice'])
            existing = any(len(saved) > max(columns['vendor'], columns['invoice']) and
                           (saved[columns['vendor']], saved[columns['invoice']]) == identity for saved in before)
            if existing or identity in seen:
                item['reason'] = 'Already present in the tracker or a duplicate submission; not logged again.'
                state['not_logged'].append(item)
                continue
            seen.add(identity)
            recipe = copy.deepcopy(sheet['append'])
            arguments = recipe['arguments']
            params = object_field(arguments, 'params')
            params.update({'valueInputOption': 'RAW', 'insertDataOption': 'INSERT_ROWS'})
            arguments['params'] = json.dumps(params)
            body = object_field(arguments, 'body')
            body.update({'majorDimension': 'ROWS', 'values': [row]})
            arguments['body'] = json.dumps(body, ensure_ascii=False)
            attempt = {'invoice': invoice, 'error': '', 'receipt': None}
            attempts.append(attempt)
            try:
                attempt['receipt'] = api.call(recipe, write=True)
            except Exception as error:
                attempt['error'] = str(error)
        except Exception as error:
            item['reason'] = 'Not logged: ' + str(error)
            state['not_logged'].append(item)
            state['issues'].append(invoice.get('invoice', '') + ': ' + str(error))
    if attempts:
        available = Counter()
        read_error = ''
        try:
            after = rows_from(api.call(sheet['read']))
            state['readback'] = after
            available = Counter(row_key(row) for row in after) - Counter(row_key(row) for row in before)
        except Exception as error:
            read_error = str(error)
            state['issues'].append('Tracker readback failed: ' + read_error)
        for attempt in attempts:
            invoice = attempt['invoice']
            identity = row_key(invoice['row'])
            if available[identity] > 0:
                available[identity] -= 1
                state['logged'].append({**invoice, 'receipt': attempt['receipt'], 'verified': True})
            else:
                reason = ('Not logged: the append failed and the row was absent from readback. ' + attempt['error']) if attempt['error'] and not read_error else (
                    'Not confirmed as logged: ' + (read_error or 'The exact intended row was absent from readback.'))
                state['not_logged'].append({'invoice': invoice['invoice'], 'vendor': invoice['vendor'],
                                            'amount': invoice['amount'], 'reason': reason})
                state['issues'].append(invoice['invoice'] + ': ' + reason)
    for invoice in invoices:
        if invoice.get('disposition') != 'return':
            continue
        try:
            sender = parseaddr(invoice['sender'])[1]
            if not sender or not invoice.get('return_text'):
                raise ValueError('Missing original sender or required return text')
            if invoice.get('prior_return_id'):
                recipe = replace_text(plan['mail']['get'], '__MESSAGE_ID__', quote(invoice['prior_return_id'], safe=''))
                receipt = verify_mail(api.call(recipe), sender, invoice['return_text'], invoice.get('thread_id', ''))
            else:
                subject = invoice.get('subject', '')
                subject = subject if subject.lower().startswith('re:') else 'Re: ' + subject
                receipt = send_mail(api, plan['mail'], sender, subject, invoice['return_text'],
                                    invoice.get('thread_id', ''), invoice.get('message_id_header', ''), invoice.get('return_parts'))
            state['returns'].append({'invoice': invoice['invoice'], 'receipt': receipt,
                                      'previously_sent': bool(invoice.get('prior_return_id'))})
        except Exception as error:
            reason = 'Vendor return incomplete for ' + invoice.get('invoice', '') + ': ' + str(error)
            state['issues'].append(reason)
            for item in state['not_logged']:
                if item['invoice'] == invoice.get('invoice') and item['vendor'] == invoice.get('vendor'):
                    item['reason'] += ' ' + reason
    return state


def recover_mail(api):
    names = collect_names(tool_definitions())
    search = next(name for name in names if name.endswith('api_search'))
    fetch = next(name for name in names if name.endswith('api_fetch'))
    encode = next(name for name in names if name.endswith('base64_encode'))
    result = api.call({'name': search, 'arguments': {'query': 'gmail messages send get', 'top_k': 20}})
    endpoints = result.get('results', [])
    send = next(item for item in endpoints if item.get('id', '').endswith('messages.send'))
    read = next(item for item in endpoints if item.get('id', '').endswith('messages.get'))
    def recipe(endpoint, message=False):
        url = endpoint['url'].replace('{userId}', 'ap@company.example.com').replace('{id}', '__MESSAGE_ID__')
        return {'name': fetch, 'arguments': {'method': endpoint['method'], 'url': url,
                                            'params': '{"format":"full"}' if message else None, 'body': None}}
    return {'send': recipe(send), 'get': recipe(read, True), 'format': 'payload',
            'encode': {'name': encode, 'arguments': {'text': '__TEXT__'}}}


def report_lines(state, total):
    plan = state['plan']
    date = plan.get('date')
    if not date:
        match = re.search(r'\b\d{4}-\d{2}-\d{2}\b', plan.get('instruction', ''))
        date = match.group() if match else 'requested morning'
    lines = ['AP processing for ' + date, '', 'Newly logged and verified in Invoice Tracker / Pending Invoices:']
    for invoice in state['logged']:
        lines.extend(['- ' + invoice['vendor'] + ' — ' + invoice['invoice'] + ' — ' + invoice['amount'],
                      '  Date: ' + invoice['date'] + '; Due date: ' + invoice['due_date']])
        if invoice.get('reason'):
            lines.append('  ' + invoice['reason'])
    if not state['logged']:
        lines.append('- None.')
    lines.extend(['', 'Not logged:'])
    for invoice in state['not_logged']:
        lines.append('- ' + invoice.get('vendor', '') + ' — ' + invoice['invoice'] +
                     (' — ' + invoice['amount'] if invoice.get('amount') else '') + ': ' + invoice['reason'])
    if not state['not_logged']:
        lines.append('- None.')
    lines.extend(['', 'Vendor returns:'])
    for returned in state['returns']:
        receipt = returned['receipt']
        lines.append('- ' + returned['invoice'] + ': ' + ('previously sent; verified' if returned['previously_sent'] else 'sent and verified') +
                     ' to ' + receipt['recipient'] + ' (message ' + str(receipt['id']) + ').')
    if not state['returns']:
        lines.append('- None confirmed this run.')
    if plan.get('policy_evidence'):
        lines.extend(['', 'Policy review: ' + plan['policy_evidence']])
    if state['issues']:
        lines.extend(['', 'Unresolved work:'] + ['- ' + issue for issue in state['issues']])
    lines.extend(['', 'Logged total: ' + total])
    return date, lines


def finish(state):
    api = Api(state, 42, 98)
    total = total_amounts([invoice['amount'] for invoice in state['logged']])['total']
    date, lines = report_lines(state, total)
    summary_status = 'incomplete' if state['issues'] else 'complete'
    body = '\n'.join(lines + ['', 'Status: ' + summary_status]) + '\n'
    receipt = None
    try:
        if state.get('stop'):
            raise StopRun('Service limit reached; no further API calls are allowed')
        mail = state['plan'].get('mail')
        if not mail or not all(mail.get(field) for field in ('send', 'get', 'encode')):
            mail = recover_mail(api)
        receipt = send_mail(api, mail, 'ap-lead@company.example.com',
                            'AP processing summary - ' + date + ' - ' + summary_status, body)
        lines.extend(['', 'Summary sent and verified to ap-lead@company.example.com (message ' + str(receipt['id']) + ').'])
    except Exception as error:
        state['issues'].append('Summary delivery incomplete: ' + str(error))
        lines.extend(['', 'Summary email to ap-lead@company.example.com was not confirmed sent: ' + str(error)])
    final = {'logged': [{'invoice': invoice['invoice'], 'amount': invoice['amount']} for invoice in state['logged']],
             'not_logged': [{'invoice': invoice['invoice'], 'reason': invoice['reason']} for invoice in state['not_logged']],
             'logged_total': total, 'status': 'incomplete' if state['issues'] or not receipt else 'complete'}
    lines.extend(['', 'Status: ' + final['status'], '', '```json', json.dumps(final, ensure_ascii=False), '```'])
    return {'report': '\n'.join(lines), 'completion': json.dumps({'final': final, 'summary': receipt,
                                                                'computed_total': total}, ensure_ascii=False)}


def check(inputs, mode):
    outputs = inputs.get('outputs', inputs)
    if mode == 'check_record':
        state = unpack(outputs['execution'])
        rows = Counter(row_key(row) for row in state['readback'])
        for invoice in state['logged']:
            if not invoice.get('verified') or rows[row_key(invoice['row'])] <= 0:
                raise ValueError('Logged claim lacks exact readback evidence')
        if any(not item['receipt'].get('sent') for item in state['returns']):
            raise ValueError('Return claim lacks sent-message evidence')
    else:
        completion = unpack(outputs['completion'])
        final = completion['final']
        if final['logged_total'] != total_amounts([item['amount'] for item in final['logged']])['total']:
            raise ValueError('Final total does not match actual verified rows')
        if completion['summary'] and 'Logged total: ' + final['logged_total'] not in completion['summary']['body'].splitlines():
            raise ValueError('Sent summary differs from final total')
        if not outputs['report'].endswith(json.dumps(final, ensure_ascii=False) + '\n```'):
            raise ValueError('Final report is missing the required JSON')
        if final['status'] == 'complete' and not completion['summary']:
            raise ValueError('Complete report lacks sent summary evidence')
    return {'status': 'pass', 'reason': 'Report reconciles with external readback evidence; any failures are explicitly incomplete.', 'evidence': []}


def main():
    mode = sys.argv[1]
    inputs = json.load(sys.stdin)
    if mode.startswith('check_'):
        try:
            result = check(inputs, mode)
        except Exception as error:
            result = {'status': 'fail', 'reason': str(error), 'evidence': []}
    elif mode == 'record':
        plan = unpack(inputs['plan'])
        result = {'execution': json.dumps(record(plan), ensure_ascii=False)}
    else:
        result = finish(unpack(inputs['execution']))
    print(json.dumps(result, ensure_ascii=False))


if __name__ == '__main__':
    main()

import json
import os
import sys
import time
from email.utils import getaddresses
from pathlib import Path
from urllib.parse import quote

from ap_agent import BudgetStop, exact_total, relay
from ap_journal import message_fields, object_value


def recipients(value):
    return {address.lower() for _, address in getaddresses([value])}


class Executor:
    def __init__(self, plan, transport=relay, output_dir=None):
        self.plan = plan
        self.transport = transport
        self.calls = plan.get('calls_used', 0)
        self.started = time.monotonic()
        self.directory = Path(output_dir or os.environ.get('METHOD_OUTPUT_DIR', '/tmp'))
        self.directory.mkdir(parents=True, exist_ok=True)
        self.events = []
        self.outcomes = []
        self.issues = list(plan.get('issues', []))
        self.checks = []
        self.summary = {'state': 'not_sent', 'total': None}
        self.halted = False
        for invoice in plan.get('invoices', []):
            state = {'hold': 'held', 'already_logged': 'preexisting', 'return': 'blocked', 'log': 'pending'}[invoice['disposition']]
            self.outcomes.append({'invoice': invoice, 'state': state, 'reason': invoice['reason'], 'return_state': None})
        self.persist()

    def persist(self):
        data = {'outcomes': self.outcomes, 'summary': self.summary, 'issues': self.issues, 'events': self.events}
        temporary = self.directory / 'ap_outcomes.tmp'
        temporary.write_text(json.dumps(data, ensure_ascii=False))
        temporary.replace(self.directory / 'ap_outcomes.json')

    def call(self, name, arguments):
        if self.halted or self.calls >= 94 or time.monotonic() - self.started > 170:
            raise BudgetStop('Execution capacity exhausted; no further external calls.')
        self.calls += 1
        event = {'name': name, 'arguments': arguments, 'state': 'attempted'}
        self.events.append(event)
        self.persist()
        try:
            answer = self.transport(name, arguments)
        except BudgetStop:
            self.halted = True
            raise
        except Exception as error:
            answer = {'error': str(error), 'ambiguous': True}
        event.update(result=answer, state='returned')
        self.persist()
        return answer

    def fetch(self, arguments):
        return self.call(self.plan['fetch_tool'], arguments)

    def template(self, name):
        return json.loads(self.plan[name])

    def read_sheet(self):
        arguments = self.template('sheet_read_json')
        result = object_value(self.fetch(arguments))
        if 'values' not in result or result.get('error'):
            raise ValueError('Cannot independently read Pending Invoices: ' + json.dumps(result, ensure_ascii=False))
        rows = result['values']
        if not isinstance(rows, list):
            raise ValueError('Invalid spreadsheet values.')
        if not rows or rows[0] != self.plan['headers']:
            raise ValueError('Pending Invoices headers changed or do not match the plan; no blind writes.')
        return rows

    def matches(self, rows, invoice):
        columns = self.plan['columns']
        return [row for row in rows[1:] if len(row) > max(columns['vendor'], columns['invoice']) and str(row[columns['vendor']]) == invoice['vendor'] and str(row[columns['invoice']]) == invoice['invoice']]

    def observe_rows(self, rows, outcomes):
        for outcome in outcomes:
            invoice = outcome['invoice']
            matches = self.matches(rows, invoice)
            if not matches:
                continue
            actual = matches[0]
            if len(actual) <= self.plan['columns']['amount']:
                continue
            outcome['state'] = 'logged'
            outcome['actual_row'] = actual
            outcome['amount'] = str(actual[self.plan['columns']['amount']])
            expected = invoice['row']
            if len(matches) != 1 or actual[:len(expected)] != expected:
                outcome['reason'] = 'Row exists but differs from intended literal values; review required.'
                self.issues.append(invoice['invoice'] + ': ' + outcome['reason'])
            self.persist()

    def append(self, outcomes):
        arguments = self.template('sheet_append_json')
        arguments['body'] = json.dumps({'majorDimension': 'ROWS', 'values': [outcome['invoice']['row'] for outcome in outcomes]}, ensure_ascii=False)
        for outcome in outcomes:
            outcome['state'] = 'write_unconfirmed'
        self.persist()
        answer = self.fetch(arguments)
        for outcome in outcomes:
            outcome['write_response'] = answer
        self.persist()
        rows = self.read_sheet()
        self.observe_rows(rows, outcomes)
        return rows

    def process_rows(self):
        pending = [outcome for outcome in self.outcomes if outcome['state'] == 'pending']
        if not pending:
            return
        rows = self.read_sheet()
        for outcome in pending:
            matches = self.matches(rows, outcome['invoice'])
            if matches:
                outcome['state'] = 'preexisting'
                outcome['reason'] = 'Already present in Pending Invoices; not appended or counted again.'
                if matches[0][:len(outcome['invoice']['row'])] != outcome['invoice']['row']:
                    outcome['state'] = 'held'
                    outcome['reason'] = 'Existing invoice has conflicting values; held for review without overwriting.'
        pending = [outcome for outcome in pending if outcome['state'] == 'pending']
        self.persist()
        if not pending:
            return
        rows = self.append(pending)
        missing = [outcome for outcome in pending if outcome['state'] != 'logged']
        for outcome in missing:
            if len(pending) > 1 and not self.matches(rows, outcome['invoice']):
                rows = self.append([outcome])
            if outcome['state'] != 'logged':
                outcome['state'] = 'write_failed'
                outcome['reason'] = 'Spreadsheet did not accept this invoice; independent read-back confirms no row. Response: ' + str(outcome.get('write_response', 'No write receipt.'))
                self.persist()
        logged_rows = [outcome['actual_row'] for outcome in pending if outcome['state'] == 'logged']
        if logged_rows:
            self.checks.append({'name': self.plan['fetch_tool'], 'arguments_json': self.plan['sheet_read_json'], 'expected': [], 'rows': logged_rows})

    def read_message(self, identifier):
        arguments = self.template('message_read_json')
        arguments['url'] = arguments['url'].replace('{message_id}', quote(identifier, safe=''))
        answer = self.fetch(arguments)
        return message_fields(answer), arguments

    def verify_message(self, observed, recipient, subject, body):
        if recipients(observed.get('to', '')) != recipients(recipient) or observed.get('subject') != subject:
            return False
        actual = observed.get('body', '').replace('\r\n', '\n').strip()
        intended = body.replace('\r\n', '\n').strip()
        if recipient == 'ap-lead@company.example.com':
            return intended.splitlines()[0] in actual.splitlines()
        return actual == intended

    def add_message_check(self, arguments, recipient, subject, body):
        expected = {'to': recipient, 'subject': subject, 'body': body}
        if recipient == 'ap-lead@company.example.com':
            expected['summary_line'] = body.splitlines()[0]
        self.checks.append({'name': self.plan['fetch_tool'], 'arguments_json': json.dumps(arguments), 'expected': [], 'message': expected})

    def find_sent(self, recipient, subject, body):
        arguments = self.template('sent_list_json')
        for page in range(3):
            result = object_value(self.fetch(arguments))
            if result.get('error') or 'messages' not in result:
                if result.get('resultSizeEstimate') == 0:
                    return None
                raise ValueError('Cannot inspect Sent safely before sending.')
            for message in result['messages']:
                fields = message_fields(message)
                if fields.get('subject') and fields['subject'] != subject:
                    continue
                if fields.get('to') and recipients(fields['to']) != recipients(recipient):
                    continue
                identifier = message.get('id', message.get('message_id', ''))
                if not identifier:
                    continue
                observed, read_args = self.read_message(identifier)
                if self.verify_message(observed, recipient, subject, body):
                    self.add_message_check(read_args, recipient, subject, body)
                    return {'state': 'verified_existing', 'id': identifier}
            if not result.get('nextPageToken'):
                return None
            params = object_value(arguments.get('params'))
            params['pageToken'] = result['nextPageToken']
            arguments['params'] = json.dumps(params)
        raise ValueError('Sent pagination incomplete; refusing a potentially duplicate send.')

    def send(self, recipient, subject, body, destination, existing_id=''):
        if any(character in recipient + subject for character in ['\r', '\n']):
            raise ValueError('Unsafe email header; use literal invoice identity in the body, not a multiline header.')
        if existing_id:
            observed, read_args = self.read_message(existing_id)
            if self.verify_message(observed, recipient, subject, body):
                self.add_message_check(read_args, recipient, subject, body)
                destination.update(state='verified_existing', id=existing_id)
                self.persist()
                return
        existing = self.find_sent(recipient, subject, body)
        if existing:
            destination.update(existing)
            self.persist()
            return
        encoded = self.call(self.plan['encode_tool'], {'text': body})
        if isinstance(encoded, str):
            try:
                decoded_result = json.loads(encoded)
            except ValueError:
                decoded_result = encoded
        else:
            decoded_result = encoded
        if isinstance(decoded_result, dict):
            decoded_result = next((decoded_result[key] for key in ['encoded', 'base64', 'result', 'data'] if isinstance(decoded_result.get(key), str)), '')
        if not isinstance(decoded_result, str) or not decoded_result:
            raise ValueError('Email encoding failed.')
        arguments = self.template('send_json')
        arguments['body'] = json.dumps({'payload': {'mimeType': 'text/plain', 'headers': [{'name': 'To', 'value': recipient}, {'name': 'Subject', 'value': subject}], 'body': {'data': decoded_result}}}, ensure_ascii=False)
        destination.update(state='unconfirmed', to=recipient, subject=subject, body=body)
        self.persist()
        answer = object_value(self.fetch(arguments))
        identifier = answer.get('id', answer.get('message_id', ''))
        if identifier:
            destination.update(state='accepted', id=identifier)
            self.persist()
            observed, read_args = self.read_message(identifier)
            if self.verify_message(observed, recipient, subject, body):
                destination['state'] = 'verified'
                self.add_message_check(read_args, recipient, subject, body)
        else:
            found = self.find_sent(recipient, subject, body)
            if found:
                destination.update(found)
            else:
                destination.update(state='unconfirmed', error=answer)
        self.persist()

    def process_returns(self):
        for outcome in self.outcomes:
            if outcome['state'] != 'blocked':
                continue
            invoice = outcome['invoice']
            outcome['return_state'] = {'state': 'not_sent'}
            try:
                self.send(invoice['sender'], invoice['return_subject'], invoice['return_body'], outcome['return_state'], invoice['existing_return_id'])
            except BudgetStop:
                raise
            except Exception as error:
                self.issues.append(invoice['invoice'] + ': return could not be fully verified: ' + str(error))
                self.persist()

    def accounting(self):
        logged = []
        not_logged = []
        for outcome in self.outcomes:
            invoice = outcome['invoice']
            if outcome['state'] == 'logged':
                logged.append({'invoice': invoice['invoice'], 'amount': outcome['amount']})
                continue
            reason = outcome['reason'] or 'Not processed.'
            if outcome['state'] == 'blocked':
                state = (outcome['return_state'] or {}).get('state', 'not_sent')
                phrase = {'verified': 'Returned and verified', 'verified_existing': 'Previously returned; verified', 'accepted': 'Return send accepted; read-back unconfirmed', 'unconfirmed': 'Return attempted; send unconfirmed', 'not_sent': 'Return not sent'}[state]
                reason += ' ' + phrase + ' to ' + invoice['sender'] + '.'
            elif outcome['state'] in ('pending', 'write_unconfirmed'):
                reason += ' Logging not completed or remains unconfirmed; inspect live rows before retrying.'
            not_logged.append({'invoice': invoice['invoice'], 'reason': reason})
        return logged, not_logged

    def work_complete(self):
        if self.issues or not self.plan.get('coverage_complete'):
            return False
        for outcome in self.outcomes:
            if outcome['state'] in ('logged', 'preexisting'):
                continue
            if outcome['state'] == 'blocked' and (outcome['return_state'] or {}).get('state') in ('verified', 'verified_existing'):
                continue
            return False
        return True

    def send_summary(self):
        logged, not_logged = self.accounting()
        total = exact_total([invoice['amount'] for invoice in logged])
        lines = ['Logged total: ' + total, '', 'Invoice Tracker / Pending Invoices', 'Logged:']
        lines.extend(invoice['invoice'] + ' | ' + invoice['amount'] for invoice in logged)
        if not logged:
            lines.append('None newly logged.')
        lines.extend(['', 'Not logged:'])
        lines.extend(invoice['invoice'] + ' | ' + invoice['reason'] for invoice in not_logged)
        if not not_logged:
            lines.append('None.')
        if self.plan.get('policy_notes'):
            lines.extend(['', self.plan['policy_notes']])
        if self.issues:
            lines.extend(['', 'Attention:'] + self.issues)
        if not self.plan.get('coverage_complete'):
            lines.append('Mailbox or policy coverage is incomplete.')
        lines.extend(['', 'Processing status: ' + ('complete' if self.work_complete() else 'incomplete')])
        self.summary['total'] = total
        self.persist()
        self.send('ap-lead@company.example.com', 'AP processing summary - ' + self.plan['date'], '\n'.join(lines), self.summary)

    def result(self):
        logged, not_logged = self.accounting()
        total = exact_total([invoice['amount'] for invoice in logged])
        state = self.summary['state']
        complete = self.work_complete() and state in ('verified', 'verified_existing')
        lines = [str(len(logged)) + ' invoices logged and read-back verified in Invoice Tracker / Pending Invoices.']
        if state in ('verified', 'verified_existing'):
            lines.append(('Summary already sent' if state == 'verified_existing' else 'Summary sent') + ' to ap-lead@company.example.com and verified.')
            lines.append('Logged total: ' + self.summary['total'])
            reported = self.summary['total']
        elif state == 'accepted':
            lines.append('Summary send accepted for ap-lead@company.example.com; independent read-back is unconfirmed. Submitted line: Logged total: ' + self.summary['total'])
            reported = self.summary['total']
        else:
            lines.append(('Summary send attempted but unconfirmed.' if state == 'unconfirmed' else 'Summary not sent.') + ' Confirmed logged total: ' + total)
            reported = self.summary.get('total') if state == 'unconfirmed' else total
        for invoice in not_logged:
            lines.append(invoice['invoice'] + ': ' + invoice['reason'])
        lines.extend('Attention: ' + issue for issue in self.issues)
        if not self.plan.get('coverage_complete'):
            lines.append('Attention: investigation coverage is incomplete.')
        record = {'logged': logged, 'not_logged': not_logged, 'logged_total': reported, 'status': 'complete' if complete else 'incomplete'}
        return {'report': '\n'.join(lines) + '\n\n```json\n' + json.dumps(record, ensure_ascii=False) + '\n```', 'verification': json.dumps(self.checks, ensure_ascii=False)}

    def run(self):
        if self.plan.get('fatal'):
            self.issues.append(self.plan['fatal'])
            return self.result()
        try:
            try:
                self.process_rows()
            except BudgetStop:
                raise
            except Exception as error:
                self.issues.append('Spreadsheet processing: ' + str(error))
                self.persist()
            self.process_returns()
            self.send_summary()
        except Exception as error:
            self.issues.append('Remaining actions stopped: ' + str(error))
            self.persist()
        return self.result()


def main():
    payload = json.load(sys.stdin)
    executor = Executor(json.loads(payload['plan']))
    print(json.dumps(executor.run(), ensure_ascii=False))


if __name__ == '__main__':
    main()

