"""Bounded local reads and checked, recoverable outreach writes. No dependencies."""
import datetime as dt
import fcntl
import hashlib
import json
import os
from pathlib import Path
import re
import sys
import tempfile


def digest(text):
    return hashlib.sha256(text.encode()).hexdigest()


def safe(path):
    path = Path(path).absolute()
    if 'sensitive' in path.parts:
        raise ValueError('Sensitive paths are not allowed')
    for parent in [path, *path.parents]:
        if parent.is_symlink():
            raise ValueError('Symbolic links are not allowed')
    return path


def local(root, name, folder):
    if not re.fullmatch(folder + r'/[a-z0-9][a-z0-9.-]*\.md', name):
        raise ValueError('Invalid record path')
    return safe(root / name)


def source_files(root):
    result = {}
    for folder in ['people', 'inbox']:
        base = safe(root / folder)
        for path in sorted(base.iterdir()):
            # Reject links before reading or following them, including directory links.
            safe(path)
            if path.name.startswith('.'):
                continue
            if path.is_dir() or path.suffix != '.md':
                raise ValueError('Unprocessed source format in ' + folder)
            name = str(path.relative_to(root))
            local(root, name, folder)
            result[name] = path
    return result


def history(text):
    marker = '\n## History\n'
    if text.count(marker) != 1:
        raise ValueError('Person must have exactly one History section')
    return text.split(marker, 1)[1]


def frontmatter(text):
    if not text.startswith('---\n') or '\n---\n' not in text[4:]:
        raise ValueError('Missing person frontmatter')
    block = text[4:].split('\n---\n', 1)[0]
    values = {}
    for key in ['name', 'next_action', 'next_action_date', 'contact_allowed']:
        matches = re.findall(r'^' + key + r':\s*(.*)$', block, re.M)
        if len(matches) != 1:
            raise ValueError('Missing or repeated person field: ' + key)
        values[key] = matches[0].strip()
    if values['contact_allowed'] not in ('true', 'false'):
        raise ValueError('Invalid contact restriction')
    date = values['next_action_date'].strip('"\'')
    if date != 'null':
        dt.date.fromisoformat(date)
    return values


def atomic(path, text):
    safe(path)
    with tempfile.NamedTemporaryFile('w', dir=path.parent, delete=False) as file:
        temp = file.name
        os.chmod(temp, 0o600)
        file.write(text)
        file.flush()
        os.fsync(file.fileno())
    os.replace(temp, path)


def index_path(root):
    return safe(root / 'runs' / '.follow-through-index.json')


def read_index(root):
    path = index_path(root)
    if not path.exists():
        return None
    value = json.loads(path.read_text())
    if value.get('version') != 1 or value.get('root') != str(root):
        raise ValueError('Invalid resolution index; do not discard it silently')
    for name, sha in value['hashes'].items():
        local(root, name, 'people' if name.startswith('people/') else 'inbox')
        if not re.fullmatch('[0-9a-f]{64}', sha):
            raise ValueError('Invalid resolution index hash')
    return value


def index_text(root, hashes):
    return json.dumps({'version': 1, 'root': str(root), 'hashes': hashes}, sort_keys=True, indent=2)


def snapshot(args):
    root = safe(args['root'])
    dt.date.fromisoformat(args['day'])
    run = safe(args['run_folder'])
    if run.parent != root / 'runs' or not re.fullmatch(r'\d{4}-\d{2}-\d{2}-follow-through-\d+', run.name):
        raise ValueError('Use an unused dated follow-through folder directly under runs')
    run.mkdir(exist_ok=True)
    if (run / 'result.md').exists() or (run / 'apply-receipt.json').exists():
        raise ValueError('This run folder already has a result; use resume or a new folder')
    records = []
    total = 0
    for name, path in source_files(root).items():
        if path.stat().st_size > 150000:
            raise ValueError('A source exceeds the input limit; no records were changed')
        text = path.read_text()
        total += len(text.encode())
        if total > 500000:
            raise ValueError('Source set exceeds 500 KB; stop and split the review explicitly')
        if name.startswith('people/'):
            history(text)
            frontmatter(text)
        records.append({'path': name, 'sha256': digest(text), 'text': text})
    baseline = read_index(root)
    previous = baseline['hashes'] if baseline else {}
    hashes = {row['path']: row['sha256'] for row in records}
    changes = [{'path': name, 'kind': 'added' if name not in previous else 'modified'}
               for name, sha in hashes.items() if previous.get(name) != sha]
    changes += [{'path': name, 'kind': 'removed'} for name in previous if name not in hashes]
    value = json.dumps({'root': str(root), 'day': args['day'], 'run_folder': str(run),
                        'records': records, 'changes': changes, 'bootstrap': baseline is None,
                        'baseline': baseline})
    # An empty collection causes zero resolver invocations, not an LLM no-op.
    return {'snapshot': value, 'resolve_batches': [value] if changes else []}


def apply(args):
    snap = json.loads(args['snapshot'])
    plans = args['plans']
    if len(plans) != int(bool(snap['changes'])):
        raise ValueError('Expected one resolution for changed inputs, zero otherwise')
    plan = json.loads(plans[0]) if plans else {'reviewed': [], 'people': [], 'inbox': [],
        'briefing': '# Follow through — ' + snap['day'] + '\n\nResolution skipped: no source changes. '
                    'Person files are unchanged. Read the current person files for today’s due work and preparation.\n'}
    root, run = safe(snap['root']), safe(snap['run_folder'])
    originals = {r['path']: r for r in snap['records']}
    changed = {row['path'] for row in snap['changes']}
    if sorted(plan['reviewed']) != sorted(changed):
        raise ValueError('Plan does not account for every changed source exactly once')
    desired = {}
    for row in plan['people']:
        name = row['path']
        local(root, name, 'people')
        if name in desired:
            raise ValueError('Repeated person update')
        if not row['causes'] or not set(row['causes']) <= changed:
            raise ValueError('Each update needs changed source paths as causes')
        old = originals.get(name, {}).get('text', '')
        if old:
            if row['create_prefix']:
                raise ValueError('Cannot regenerate an existing person')
            prefix = old.split('\n## History\n', 1)[0]
            for edit in row['edits']:
                before, after = edit['before'], edit['after']
                if not before or prefix.count(before) != 1:
                    raise ValueError('Edit must match exactly one current passage')
                if before == prefix or before.startswith('---\n') and '\n## ' in before:
                    raise ValueError('Replace individual facts, not the whole current state')
                prefix = prefix.replace(before, after, 1)
        else:
            if name in {c['path'] for c in snap['changes'] if c['kind'] == 'removed'}:
                raise ValueError('Do not recreate a removed person automatically')
            if row['edits'] or not row['create_prefix'].strip():
                raise ValueError('A new person needs an initial prefix and no edits')
            prefix = row['create_prefix'].rstrip()
        if '\n## History' in prefix:
            raise ValueError('History cannot be supplied in the current-state prefix')
        fields = frontmatter(prefix + '\n')
        for heading in (['Context', 'Current state', 'Commitments', 'Open questions'] if not old else []):
            if '\n## ' + heading + '\n' not in prefix + '\n':
                raise ValueError('Missing current-state section: ' + heading)
        if old and frontmatter(old)['contact_allowed'] == 'false' and fields['contact_allowed'] != 'false':
            raise ValueError('Cannot restore contact permission automatically')
        if fields['contact_allowed'] == 'false' and fields['next_action'] != 'null':
            raise ValueError('Keep restricted person actions in internal commitments; clear next_action')
        addition = row['history_additions'].strip()
        if addition and (not addition.startswith('### ') or 'Source:' not in addition):
            raise ValueError('New history requires an event heading and Source')
        prior = history(old) if old else '\n'
        desired[name] = prefix + ('\n' if old else '\n\n') + '## History\n' + ('\n' + addition + '\n' if addition else '') + prior
    for row in plan['inbox']:
        name = row['path']
        local(root, name, 'inbox')
        if name not in originals or name not in changed or name in desired or not row['append'].strip():
            raise ValueError('Invalid inbox append')
        old = originals[name]['text']
        addition = row['append'].strip()
        desired[name] = old if addition in old else old + '\n\n' + addition + '\n'
    if not plan['briefing'].strip():
        raise ValueError('Missing briefing')
    report = run / 'result.md'
    desired[str(report.relative_to(root))] = plan['briefing'].rstrip() + '\n'
    receipt_path = run / 'apply-receipt.json'
    plan_hash = digest(args['snapshot'] + json.dumps(plans))
    # Advisory lock serializes this writer. Every input is also checked for edits.
    with (safe(root / 'runs') / '.follow-through.lock').open('a') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        existing_receipt = None
        if receipt_path.exists():
            existing_receipt = json.loads(receipt_path.read_text())
            if existing_receipt['plan_hash'] != plan_hash:
                raise ValueError('Run folder belongs to another plan')
        baseline = read_index(root)
        if baseline != snap['baseline'] and not (existing_receipt and baseline == existing_receipt['index_after']):
            raise ValueError('Another resolution completed; take a new snapshot')
        current = source_files(root)
        allowed_new = set(desired) - set(originals)
        if set(current) - set(originals) - allowed_new or set(originals) - set(current):
            raise ValueError('Source list changed; take a new snapshot')
        for name, row in originals.items():
            observed = current[name].read_text()
            if digest(observed) != row['sha256'] and not (existing_receipt and observed == desired.get(name)):
                raise ValueError('Source changed; no new writes: ' + name)
        for name, content in desired.items():
            target = safe(root / name)
            if name not in originals and target.exists() and not (existing_receipt and target.read_text() == content):
                raise ValueError('Refusing to overwrite a new file: ' + name)
        hashes = {name: digest(desired.get(name, row['text'])) for name, row in originals.items()}
        hashes.update({name: digest(text) for name, text in desired.items() if name.startswith('people/')})
        index_after = json.loads(index_text(root, hashes))
        receipt = {'root': str(root), 'run_folder': str(run), 'report_path': str(report),
                   'plan_hash': plan_hash, 'originals': originals,
                   'index_after': index_after, 'resolution_skipped': not plans,
                   'writes': {name: digest(value) for name, value in desired.items()}}
        # Receipt precedes writes. A retry of this exact plan accepts original OR
        # already-written target bytes and finishes the remaining files.
        atomic(receipt_path, json.dumps(receipt, indent=2))
        for name, content in desired.items():
            target = safe(root / name)
            if not target.exists() or target.read_text() != content:
                atomic(target, content)
        verify_saved(receipt)
        # Commit only the exact reviewed/saved source bytes. Preparation or user
        # edits after this point remain new input for the next resolution.
        if read_index(root) != index_after:
            atomic(index_path(root), index_text(root, hashes))
    return {'saved': json.dumps({key: receipt[key] for key in ['root', 'run_folder', 'report_path']} |
                               {'changed_files': list(desired), 'resolution_skipped': not plans})}


def verify_saved(receipt):
    for name, expected in receipt['writes'].items():
        if digest(safe(Path(receipt['root']) / name).read_text()) != expected:
            raise ValueError('Saved content differs: ' + name)


def check(args, final=False):
    saved = json.loads(args['inputs']['saved'] if final else args['outputs']['saved'])
    root, run = safe(saved['root']), safe(saved['run_folder'])
    receipt = json.loads(safe(run / 'apply-receipt.json').read_text())
    if final:
        if args['outputs']['report_path'] != saved['report_path']:
            raise ValueError('Final report path differs')
        if not safe(Path(saved['report_path'])).read_text().strip():
            raise ValueError('Final report is empty')
        for name, row in receipt['originals'].items():
            current = safe(root / name).read_text()
            old = row['text']
            if name.startswith('people/'):
                frontmatter(current)
                if not history(current).endswith(history(old)):
                    raise ValueError('Original history changed: ' + name)
                if frontmatter(old)['contact_allowed'] == 'false' and frontmatter(current)['contact_allowed'] != 'false':
                    raise ValueError('Contact restriction changed')
            elif not current.startswith(old):
                raise ValueError('Original note changed: ' + name)
    else:
        verify_saved(receipt)
    return {'status': 'pass', 'reason': 'Verified report and retained source history.' if final else 'Verified all saved content hashes.',
            'evidence': [saved['report_path']]}


if __name__ == '__main__':
    try:
        args = json.load(sys.stdin)
        mode = sys.argv[1]
        result = snapshot(args) if mode == 'snapshot' else apply(args) if mode == 'apply' else check(args, mode == 'final-check')
        print(json.dumps(result))
    except Exception as error:
        if sys.argv[1] in ('check', 'final-check'):
            print(json.dumps({'status': 'fail', 'reason': str(error), 'evidence': []}))
        else:
            print(str(error), file=sys.stderr)
            sys.exit(1)

"""Read person records, inbox notes and run folders. Return only changed sources for extraction."""
import hashlib
import json
import os
import re
import sys
from pathlib import Path

OUT = Path(os.environ.get("METHOD_OUTPUT_DIR", "."))
MAX_BYTES = 600_000
BATCH_SOURCES = 4
BATCH_BYTES = 120_000

# Run folder name -> kind of work. First match wins.
RUN_KINDS = [
    ("maintenance", ("follow-through",)),
    ("research", ("person-research", "find-people", "happenstance", "contact-sources", "connections",
                  "candidates", "event-shortlist", "openai-event-leads", "next-20", "sf-meeting-targets",
                  "yc-sales-reference", "sf-outreach-review", "sf-trip")),
    ("drafting", ("draft", "invites", "invitation", "opener", "copy", "email", "edit", "subject-lines",
                  "reply", "plain", "intro", "follow-up", "coffee", "bookface")),
    ("meeting prep", ("prep", "questions", "meeting", "call", "paper", "handoff", "agreement", "use-case", "sf-tech-week")),
]


def safe(path):
    path = Path(path).absolute()
    if "sensitive" in path.parts:
        raise ValueError("Sensitive paths are not allowed")
    if path.is_symlink():
        raise ValueError("Symbolic links are not allowed: " + path.name)
    return path


def sha(text):
    return hashlib.sha256(text.encode()).hexdigest()


def frontmatter(text):
    if not text.startswith("---\n"):
        return {}
    block = text[4:].split("\n---\n", 1)[0]
    out = {}
    for line in block.splitlines():
        m = re.match(r"^(\w+):\s*(.*)$", line)
        if m:
            v = m.group(2).strip().strip("\"'")
            out[m.group(1)] = None if v == "null" else v
    return out


def run_kind(slug):
    for kind, keys in RUN_KINDS:
        if any(k in slug for k in keys):
            return kind
    return "other"


def drafted_names(result):
    """Names of people in a meeting-invites style result: '## 1. Name' headings."""
    return [m.strip() for m in re.findall(r"^## \d+\. (.+)$", result, re.M)]


def runs(root):
    out = []
    for path in sorted(safe(root / "runs").iterdir()):
        m = re.fullmatch(r"(\d{4}-\d{2}-\d{2})-(.+?)(?:-(\d{2}))?", path.name)
        if not path.is_dir() or not m:
            continue
        safe(path)
        result = path / "result.md"
        text = result.read_text(errors="replace") if result.is_file() and not result.is_symlink() else ""
        names = drafted_names(text) if ("invites" in m.group(2)) else []
        out.append({"folder": path.name, "date": m.group(1), "slug": m.group(2), "kind": run_kind(m.group(2)),
                    "has_result": bool(text), "drafted": names})
    return out


def main(args):
    root = safe(args["outreach_root"])
    cache = json.loads(args["known"]) if args.get("known") else {}
    sources, total = [], 0
    for folder in ("people", "inbox"):
        for path in sorted(safe(root / folder).glob("*.md")):
            safe(path)
            text = path.read_text()
            total += len(text.encode())
            name = f"{folder}/{path.name}"
            fm = frontmatter(text) if folder == "people" else {}
            sources.append({"path": name, "kind": "person" if folder == "people" else "note",
                            "name": fm.get("name") or path.stem, "sha256": sha(text), "text": text,
                            "frontmatter": fm})
    if total > MAX_BYTES:
        raise ValueError(f"Source records are {total} bytes; the limit is {MAX_BYTES}")
    changed = [s for s in sources if (cache.get(s["path"]) or {}).get("sha256") != s["sha256"]]
    removed = sorted(set(cache) - {s["path"] for s in sources})
    corpus = OUT / "corpus.json"
    corpus.write_text(json.dumps({"as_of": args["as_of"], "root": str(root),
                                  "sources": [{k: v for k, v in s.items() if k != "text"} for s in sources],
                                  "runs": runs(root), "changed": [s["path"] for s in changed], "removed": removed}))
    corpus.chmod(0o600)
    batches, group, size = [], [], 0
    for s in changed:
        n = len(s["text"].encode())
        if group and (len(group) >= BATCH_SOURCES or size + n > BATCH_BYTES):
            batches.append(group)
            group, size = [], 0
        group.append({"path": s["path"], "kind": s["kind"], "text": s["text"]})
        size += n
    if group:
        batches.append(group)
    batches = [json.dumps({"as_of": args["as_of"], "sources": b}) for b in batches]
    print(json.dumps({"type": "progress", "message": f"{len(sources)} sources, {len(changed)} changed"}), file=sys.stderr)
    return {"corpus": {"path": corpus.name, "sha256": hashlib.sha256(corpus.read_bytes()).hexdigest()},
            "batches": batches}


if __name__ == "__main__":
    print(json.dumps(main(json.load(sys.stdin))))

"""Merge extractions with the cache, count what happened, and compare with the last check."""
import collections
import datetime as dt
import hashlib
import json
import os
import re
import sys
from pathlib import Path

OUT = Path(os.environ.get("METHOD_OUTPUT_DIR", "."))
KINDS = {"met", "sent", "received", "scheduled", "held", "canceled", "drafted", "prepared", "deal", "skipped"}
CONTACT = {"met", "sent", "received", "scheduled", "held"}
TWO_WAY = {"met", "received", "held"}
STAGES = ["not_contacted", "contacted", "replied", "scheduled", "met", "engaged", "paying", "closed", "paused"]
OPEN = {"open", "waiting", "blocked", "prepared", "deferred"}
STALE_DAYS = 7


def load(ref):
    path = OUT / ref["path"]
    if hashlib.sha256(path.read_bytes()).hexdigest() != ref["sha256"]:
        raise ValueError("The corpus changed")
    return json.loads(path.read_text())


def parse_json(text):
    text = text.strip()
    m = re.search(r"\{.*\}", text, re.S)
    if not m:
        raise ValueError("Extraction is not JSON")
    return json.loads(m.group(0))


def date_or_none(v):
    if not v:
        return None
    try:
        return dt.date.fromisoformat(str(v)[:10]).isoformat()
    except ValueError:
        return None


def clean(x, path):
    """Validate one extraction. Unknown kinds fail the run instead of silently disappearing."""
    events = []
    for e in x.get("events") or []:
        if e.get("kind") not in KINDS:
            raise ValueError(f"{path}: unknown event kind {e.get('kind')!r}")
        events.append({"date": date_or_none(e.get("date")), "latest": date_or_none(e.get("latest_date")),
                       "kind": e["kind"], "actor": e.get("actor") or "ryan", "channel": e.get("channel") or "unknown",
                       "summary": e.get("summary") or "", "heading": e.get("heading") or "",
                       "certainty": e.get("certainty") or "reported"})
    commits = [{"id": c.get("id") or "", "owner": c.get("owner") or "ryan", "action": c.get("action") or "",
                "status": (c.get("status") or "open").lower(), "due": date_or_none(c.get("due")),
                "made_on": date_or_none(c.get("made_on"))} for c in x.get("commitments") or []]
    profile = x.get("profile") or None
    if profile and profile.get("stage") not in STAGES:
        raise ValueError(f"{path}: unknown stage {profile.get('stage')!r}")
    return {"events": events, "commitments": commits, "profile": profile,
            "intentions": x.get("intentions") or [], "claims": x.get("claims") or []}


def merge(corpus, extractions, cache):
    by_path = {s["path"]: s for s in corpus["sources"]}
    new_cache = {p: v for p, v in cache.items() if p in by_path and v.get("sha256") == by_path[p]["sha256"]}
    got = {}
    for text in extractions:
        for x in parse_json(text).get("sources") or []:
            if x.get("path") not in corpus["changed"] or x["path"] in got:
                raise ValueError(f"Unexpected or repeated extraction path {x.get('path')!r}")
            got[x["path"]] = x
    missing_x = set(corpus["changed"]) - set(got)
    if missing_x:
        raise ValueError("The model returned no extraction for " + ", ".join(sorted(missing_x)))
    for path, x in got.items():
        new_cache[path] = {"sha256": by_path[path]["sha256"], "x": clean(x, path)}
    missing = set(by_path) - set(new_cache)
    if missing:
        raise ValueError("No extraction for " + ", ".join(sorted(missing)))
    return new_cache


def when(e):
    """Best date for charts: the event date, else the latest possible date."""
    return e["date"] or e["latest"]


def people_table(corpus, cache, as_of):
    out = []
    for s in corpus["sources"]:
        if s["kind"] != "person":
            continue
        x = cache[s["path"]]["x"]
        prof = x["profile"] or {}
        fm = s["frontmatter"]
        ev = sorted(x["events"], key=lambda e: when(e) or "0000")
        dated = [e for e in ev if when(e)]
        contact = [e for e in dated if e["kind"] in CONTACT]
        two_way = [e for e in dated if e["kind"] in TWO_WAY]
        sent = [e for e in dated if e["kind"] == "sent"]
        last_sent = sent[-1] if sent else None
        replied_after = last_sent and any(e["kind"] in TWO_WAY | {"scheduled"} and e["actor"] != "ryan"
                                           and when(e) >= when(last_sent) and e is not last_sent for e in dated)
        unanswered = bool(last_sent) and not replied_after
        last_touch = contact[-1] if contact else None
        commits = x["commitments"]
        open_c = [c for c in commits if c["status"] in OPEN]
        overdue = [c for c in open_c if c["due"] and c["due"] < as_of]
        stage = prof.get("stage") or "not_contacted"
        if fm.get("contact_allowed") == "false":
            stage = "closed"
        out.append({
            "id": s["path"].split("/")[-1][:-3], "name": prof.get("name") or s["name"], "company": prof.get("company"),
            "role": prof.get("role"), "how_met": prof.get("how_met"), "origin": prof.get("origin") or "unknown",
            "segment": prof.get("segment") or "other", "stage": stage, "ball": prof.get("ball") or "unclear",
            "why": prof.get("why"), "risk": prof.get("risk"),
            "next_action": fm.get("next_action"), "next_action_date": fm.get("next_action_date"),
            "contact_allowed": fm.get("contact_allowed") != "false",
            "events": ev, "commitments": commits,
            "first_contact": contact[0] and when(contact[0]) if contact else None,
            "last_contact": when(last_touch) if last_touch else None,
            "last_two_way": when(two_way[-1]) if two_way else None,
            "days_since_contact": days(when(last_touch), as_of) if last_touch else None,
            "days_since_two_way": days(when(two_way[-1]), as_of) if two_way else None,
            "unanswered_send": when(last_sent) if unanswered else None,
            "days_waiting": days(when(last_sent), as_of) if unanswered else None,
            "open_commitments": len(open_c), "overdue": len(overdue),
            "ryan_open": sum(1 for c in open_c if c["owner"] in ("ryan", "both")),
            "undated_events": sum(1 for e in ev if not e["date"]),
        })
    return out


def days(a, b):
    return (dt.date.fromisoformat(b) - dt.date.fromisoformat(a)).days


def norm(name):
    return re.sub(r"[^a-z ]", "", name.lower()).split()


def build(corpus, cache, as_of, goals):
    people = people_table(corpus, cache, as_of)
    all_events = [dict(e, person=p["name"], pid=p["id"]) for p in people for e in p["events"]]
    dated = [e for e in all_events if when(e)]
    runs = [r for r in corpus["runs"] if r["date"] <= as_of]
    first = min([when(e) for e in dated] + [r["date"] for r in runs] + [as_of])
    start = dt.date.fromisoformat(first)
    start -= dt.timedelta(days=start.weekday())
    end = dt.date.fromisoformat(as_of)
    day_list = [(start + dt.timedelta(i)).isoformat() for i in range((end - start).days + 1)]

    daily = {d: collections.Counter() for d in day_list}
    for e in dated:
        d = min(when(e), as_of)
        if d in daily:
            daily[d][e["kind"]] += 1
    for r in runs:
        if r["date"] in daily:
            daily[r["date"]]["run:" + r["kind"]] += 1

    # Drafted invite names with no person record are drafts that were never recorded as sent.
    known = [set(norm(p["name"])) for p in people]
    drafted = collections.OrderedDict()
    for r in runs:
        for n in r["drafted"]:
            toks = set(norm(n))
            recorded = any(toks and toks <= k or (k and k <= toks) for k in known)
            drafted.setdefault(n, {"name": n, "first": r["date"], "runs": 0, "recorded": recorded})
            drafted[n]["runs"] += 1

    funnel_order = ["contacted", "replied", "scheduled", "met", "engaged", "paying"]
    reached = {s: sum(1 for p in people if p["stage"] not in ("not_contacted",) and
                      reach_rank(p) >= funnel_order.index(s)) for s in funnel_order}

    notes = [s for s in corpus["sources"] if s["kind"] == "note"]
    intentions = [dict(i, source=s["path"]) for s in notes for i in cache[s["path"]]["x"]["intentions"]]
    claims = [dict(c, source=s["path"]) for s in notes for c in cache[s["path"]]["x"]["claims"]]
    commitments = [dict(c, person=p["name"], pid=p["id"]) for p in people for c in p["commitments"]]
    for c in commitments:
        c["overdue"] = c["status"] in OPEN and bool(c["due"]) and c["due"] < as_of

    return {"asOf": as_of, "days": day_list, "goals": goals, "people": people,
            "daily": {d: dict(c) for d, c in daily.items() if c},
            "runs": runs, "drafted": list(drafted.values()), "funnel": reached,
            "commitments": commitments, "intentions": intentions, "claims": claims,
            "sources": {"people": sum(1 for s in corpus["sources"] if s["kind"] == "person"), "notes": len(notes),
                        "runs": len(runs), "changed": len(corpus["changed"]), "removed": len(corpus["removed"])}}


def reach_rank(p):
    """How far down the funnel a person has ever been, from their events and stage."""
    order = ["contacted", "replied", "scheduled", "met", "engaged", "paying"]
    rank = order.index(p["stage"]) if p["stage"] in order else -1
    kinds = {e["kind"] for e in p["events"]}
    ev_rank = max([-1] + [{"sent": 0, "received": 1, "scheduled": 2, "met": 3, "held": 3}[k]
                          for k in kinds if k in ("sent", "received", "scheduled", "met", "held")])
    if "deal" in kinds:
        ev_rank = max(ev_rank, 4)
    return max(rank, ev_rank)


def window(data, n):
    since = (dt.date.fromisoformat(data["asOf"]) - dt.timedelta(days=n - 1)).isoformat()
    c = collections.Counter()
    for d, k in data["daily"].items():
        if d >= since:
            c.update(k)
    return {"since": since, **dict(c)}


def snapshot(data):
    return {"as_of": data["asOf"],
            "people": {p["id"]: {"name": p["name"], "stage": p["stage"], "ball": p["ball"],
                                 "events": len(p["events"]), "last_contact": p["last_contact"],
                                 "open": p["open_commitments"], "overdue": p["overdue"]} for p in data["people"]},
            "totals": {k: sum(c.get(k, 0) for c in data["daily"].values()) for k in sorted(KINDS)},
            "runs": len(data["runs"]), "drafted_unrecorded": sum(1 for d in data["drafted"] if not d["recorded"])}


def changes(now, before):
    if not before:
        return {"previous_as_of": None, "items": []}
    items = []
    for k, p in now["people"].items():
        old = before["people"].get(k)
        if not old:
            items.append({"kind": "new", "text": f"New person record: {p['name']} ({p['stage']})"})
        elif old["stage"] != p["stage"]:
            items.append({"kind": "stage", "text": f"{p['name']} moved from {old['stage']} to {p['stage']}"})
        elif old["events"] != p["events"]:
            items.append({"kind": "events", "text": f"{p['name']}: {p['events'] - old['events']:+d} recorded events"})
        if old and p["overdue"] > old["overdue"]:
            items.append({"kind": "overdue", "text": f"{p['name']}: a promise became overdue"})
    for k in before["people"]:
        if k not in now["people"]:
            items.append({"kind": "removed", "text": f"Person record removed: {before['people'][k]['name']}"})
    for k in ("sent", "received", "held", "scheduled", "drafted", "prepared"):
        d = now["totals"].get(k, 0) - before["totals"].get(k, 0)
        if d:
            items.append({"kind": k, "text": f"{d:+d} {k} events"})
    d = now["runs"] - before["runs"]
    if d:
        items.append({"kind": "runs", "text": f"{d:+d} run folders (research, drafts, prep, maintenance)"})
    return {"previous_as_of": before["as_of"], "items": items}


def main(args):
    corpus = load(args["corpus"])
    cache = json.loads(args["known"]) if args.get("known") else {}
    cache = merge(corpus, args["extractions"], cache)
    data = build(corpus, cache, args["as_of"], args["goals"])
    snap = snapshot(data)
    before = json.loads(args["previous_snapshot"]) if args.get("previous_snapshot") else None
    data["changes"] = changes(snap, before)
    data["last7"], data["last14"] = window(data, 7), window(data, 14)
    path = OUT / "outreach-data.json"
    path.write_text(json.dumps(data, separators=(",", ":")))
    path.chmod(0o600)

    p = data["people"]
    brief = lambda q: {"name": q["name"], "company": q["company"], "stage": q["stage"], "ball": q["ball"],
                       "last_contact": q["last_contact"], "last_two_way": q["last_two_way"],
                       "unanswered_send": q["unanswered_send"], "days_waiting": q["days_waiting"],
                       "next_action": q["next_action"], "risk": q["risk"], "why": q["why"],
                       "open_promises": [f"{c['owner']}: {c['action']} ({c['status']}, due {c['due']})"
                                         for c in q["commitments"] if c["status"] in OPEN]}
    run_kinds = collections.Counter(r["kind"] for r in data["runs"])
    summary = {
        "as_of": data["asOf"],
        "data_notes": [
            "Events come only from Ryan's local person records. Contact that Ryan did not record is missing.",
            "Events with an unknown date are charted on the latest date they could have happened.",
            "Run folders are a proxy for preparation work, not hours. One folder can be minutes or an hour.",
            "Drafted names come from meeting-invites results. A drafted name with no person record was never recorded as sent; it may have been sent and not recorded."],
        "people_count": len(p),
        "stage_counts": dict(collections.Counter(q["stage"] for q in p)),
        "funnel_ever_reached": data["funnel"],
        "event_totals": snap["totals"],
        "last_7_days": data["last7"], "last_14_days": data["last14"],
        "run_folders_by_kind": dict(run_kinds),
        "run_folders_by_date": dict(collections.Counter(r["date"] for r in data["runs"])),
        "drafted_names_never_recorded_as_sent": [d["name"] for d in data["drafted"] if not d["recorded"]],
        "ball_with_ryan": [brief(q) for q in p if q["ball"] == "ryan"],
        "waiting_on_reply": [brief(q) for q in p if q["unanswered_send"]],
        "overdue_promises": [c for c in data["commitments"] if c["overdue"]],
        "open_promises_by_owner": dict(collections.Counter(c["owner"] for c in data["commitments"] if c["status"] in OPEN)),
        "stale_relationships": [brief(q) for q in p if q["days_since_two_way"] is not None
                                and q["days_since_two_way"] >= STALE_DAYS and q["stage"] not in ("closed", "paused")],
        "people": [brief(q) for q in p],
        "ryan_intentions": data["intentions"], "ryan_reported_results": data["claims"],
        "changes_since_last_check": data["changes"]}
    return {"data": {"path": path.name, "sha256": hashlib.sha256(path.read_bytes()).hexdigest()},
            "summary": json.dumps(summary, indent=1), "snapshot": json.dumps(snap),
            "new_cache": json.dumps(cache, separators=(",", ":"))}


if __name__ == "__main__":
    print(json.dumps(main(json.load(sys.stdin))))

"""Turn the raw export into dashboard data, a summary for the writer, and a snapshot."""
import collections
import datetime as dt
import hashlib
import json
import os
import sys
from pathlib import Path

OUT = Path(os.environ.get("METHOD_OUTPUT_DIR", "."))
YOU = "you"


def load(ref):
    path = OUT / ref["path"]
    if hashlib.sha256(path.read_bytes()).hexdigest() != ref["sha256"]:
        raise ValueError("The raw export changed")
    return json.loads(path.read_text())


def person_map(users, owners, excluded):
    """Owner accounts merge into one person. Excluded accounts are dropped."""
    owners = {e.lower() for e in owners}
    excluded = {e.lower() for e in excluded}
    ids, people = {}, {}
    for u in users:
        email = u["email"].lower()
        if email in excluded:
            continue
        pid = YOU if email in owners else u["id"]
        ids[u["id"]] = pid
        signup = u["created_at"][:10]
        if pid in people:
            people[pid]["signup"] = min(people[pid]["signup"], signup)
            people[pid]["accounts"] += 1
            continue
        name = "You" if pid == YOU else (u["name"] or email.split("@")[0])
        people[pid] = {"id": pid, "name": name, "domain": email.split("@")[-1], "signup": signup, "accounts": 1}
    if YOU in people:
        people[YOU]["note"] = f"You · {people[YOU]['accounts']} account" + ("s" if people[YOU]["accounts"] > 1 else "")
    for p in people.values():
        p.setdefault("note", p["domain"])
    return ids, people


def build(raw, owners, excluded, as_of):
    ids, people = person_map(raw["users"], owners, excluded)
    clamp = lambda d: min(d, as_of)
    act = collections.defaultdict(lambda: collections.defaultdict(collections.Counter))
    for r in raw["daily"]:
        pid = ids.get(r["user_id"])
        if pid:
            act[pid][clamp(r["day"])][r["event"]] += r["n"]
    runs_day = collections.defaultdict(collections.Counter)
    runs_person = collections.defaultdict(collections.Counter)
    for r in raw["runs_daily"]:
        pid = ids.get(r["user_id"])
        if not pid:
            continue
        runs_day[clamp(r["day"])][r["status"]] += r["n"]
        runs_person[pid][r["status"]] += r["n"]
        act[pid][clamp(r["day"])]["run"] += r["n"]
    methods = _sum_by(raw["methods"], ids, "n")
    chats = _sum_by(raw["threads"], ids, "threads")
    cli = _sum_by(raw["devices"], ids, "devices")

    first = min(p["signup"] for p in people.values())
    start = dt.date.fromisoformat(first)
    start -= dt.timedelta(days=start.weekday())  # Monday of the first signup week
    end = dt.date.fromisoformat(as_of)
    days = [(start + dt.timedelta(i)).isoformat() for i in range((end - start).days + 1)]

    activity = {}
    for pid in people:
        activity[pid] = {d: {"views": c["dashboard_visible"], "methods": c["method_created"], "runs": c["run"],
                             "calls": c["api_request"], "signup": c["signup"]}
                         for d, c in act[pid].items() if d >= days[0]}
    order = sorted(people.values(), key=lambda p: (p["id"] != YOU, p["signup"], p["name"]))
    plist = [{**p, "methods": methods[p["id"]], "runs": dict(runs_person[p["id"]]), "chats": chats[p["id"]],
              "cli": cli[p["id"]], "views": sum(a["views"] for a in activity[p["id"]].values())} for p in order]

    areas = collections.defaultdict(collections.Counter)
    routes = collections.Counter()
    for r in raw["routes"]:
        pid = ids.get(r["user_id"])
        if pid:
            areas[pid][area(r["route"] or "unmatched")] += r["n"]
            routes[(r["source"], r["route"] or "unmatched")] += r["n"]
    hours = {"you": [[0] * 24 for _ in range(7)], "others": [[0] * 24 for _ in range(7)]}
    for r in raw["hours"]:
        pid = ids.get(r["user_id"])
        if pid:
            hours["you" if pid == YOU else "others"][r["wd"]][r["hr"]] += r["n"]
    downloads = collections.defaultdict(collections.Counter)
    for r in raw["downloads"]:
        downloads[clamp(r["day"])][r["kind"]] += r["n"]
    sources = {r["kind"]: r["callers"] for r in raw["download_sources"]}

    return {"asOf": as_of, "days": days, "people": plist, "activity": activity,
            "runs": {d: dict(c) for d, c in runs_day.items()},
            "downloads": {d: dict(c) for d, c in downloads.items()}, "dlCallers": sources,
            "areas": {p: dict(c) for p, c in areas.items()},
            "routes": [[s, r, n] for (s, r), n in routes.most_common()], "hours": hours}


def _sum_by(rows, ids, key):
    out = collections.Counter()
    for r in rows:
        pid = ids.get(r["user_id"])
        if pid:
            out[pid] += r[key]
    return out


def area(route):
    if route.startswith("/api/cli/runs"): return "Run sync (CLI)"
    if route.startswith("/api/workspace/runs"): return "Run results"
    if any(k in route for k in ("improvements", "versions", "conversation")): return "Method editing"
    if route.startswith("/api/assistant"): return "Assistant chat"
    if route.startswith("/api/methods"): return "Method library"
    if route.startswith("/api/cli/"): return "Method sync (CLI)"
    return "Sign-in & account"


def stage(p):
    if sum(p["runs"].values()): return "Ran a method"
    if p["methods"]: return "Made a method"
    return "Looked around" if p["views"] or p["active_days"] > 1 else "Signed up only"


def snapshot(data):
    people = {}
    for p in data["people"]:
        days = sorted(data["activity"][p["id"]])
        people[p["id"]] = {"name": p["name"], "signup": p["signup"], "active_days": len(days),
                           "last_active": days[-1] if days else p["signup"], "runs": sum(p["runs"].values()),
                           "methods": p["methods"], "views": p["views"]}
        people[p["id"]]["stage"] = stage({**p, "active_days": len(days)})
    return {"as_of": data["asOf"], "people": people,
            "downloads": sum(sum(c.values()) for c in data["downloads"].values())}


def changes(now, before):
    """Differences since the last saved snapshot. Empty when there is none."""
    if not before:
        return {"previous_as_of": None, "items": []}
    since = before["as_of"]
    items = []
    new = [p["name"] for k, p in now["people"].items() if k not in before["people"]]
    if new: items.append({"kind": "signup", "text": f"{len(new)} new signup(s): {', '.join(new)}"})
    for k, p in now["people"].items():
        old = before["people"].get(k)
        if p["last_active"] > since and k != YOU:
            items.append({"kind": "active", "text": f"{p['name']} was active (last on {p['last_active']})"})
        if old and p["stage"] != old["stage"]:
            items.append({"kind": "stage", "text": f"{p['name']} moved from '{old['stage']}' to '{p['stage']}'"})
    def delta(key, who):
        return sum(p[key] for k, p in now["people"].items() if who(k)) - \
            sum(p[key] for k, p in before["people"].items() if who(k))
    for key, label in (("runs", "runs"), ("methods", "new methods"), ("views", "workspace visits")):
        y, o = delta(key, lambda k: k == YOU), delta(key, lambda k: k != YOU)
        if y or o: items.append({"kind": key, "text": f"{y + o} {label} ({y} by you, {o} by other people)"})
    d = now["downloads"] - before["downloads"]
    if d: items.append({"kind": "downloads", "text": f"{d} downloads"})
    return {"previous_as_of": since, "items": items}


def main(args):
    raw = load(args["raw"])
    data = build(raw, args["owner_emails"], args["excluded_emails"], args["as_of"])
    snap = snapshot(data)
    before = json.loads(args["previous_snapshot"]) if args.get("previous_snapshot") else None
    data["changes"] = changes(snap, before)
    path = OUT / "usage-data.json"
    path.write_text(json.dumps(data, separators=(",", ":")))
    path.chmod(0o600)
    summary = {"as_of": data["asOf"], "tracking_notes": [
        "Page visits and server requests are logged from 2026-09-18. Runs from 2026-09-08. Earlier activity counts only signups and new methods.",
        "Server request counts are inflated by pages that refresh by themselves.",
        "Download sources are network address plus client program, not people. Owner machines are included."],
        "people": snap["people"], "run_results_by_person": {p["name"]: p["runs"] for p in data["people"]},
        "downloads_total": snap["downloads"],
        "distinct_download_sources": {"all_file_types": data["dlCallers"].get("any", 0),
                                      "by_file_type": {k: v for k, v in data["dlCallers"].items() if k != "any"}},
        "changes_since_last_check": data["changes"]}
    return {"data": {"path": path.name, "sha256": hashlib.sha256(path.read_bytes()).hexdigest()},
            "summary": json.dumps(summary, indent=1), "snapshot": json.dumps(snap)}


if __name__ == "__main__":
    print(json.dumps(main(json.load(sys.stdin))))

